#!/bin/bash
# wave6.2.6-controls.sh — контроли волны 6.2.6 (долг прогона 6.2.4, находки
# №261…№270). Механический форк wave6.2.4-controls.sh (w624→w626,
# 6.2.4→6.2.6 всюду, КРОМЕ четырёх долговых меток 6.2.4.5/.6/.7/.12 — они
# сохраняют СВОИ номера намеренно, память criteria-index-pins-replay-labels).
#
# ЭТОТ ФОРК — РАБОТА ITEM 5 ПОСТАНОВКИ ВОЛНЫ (plan.md, §6.2.6, находки
# №267/№268): измеритель чинится по трём точкам.
#   (1) 6.2.6.1 получает три подпункта, потерянные в 6.2.4 (№268): сторож
#       нуля на всех четырёх правилах-двойниках №253 (w626_daemon_twin_exceptions,
#       wave6.2.6-metrics-lib.sh), ненулевой rule_exceptions_total по КАЖДОМУ
#       из четырёх rule_id (обоим именованным исключениям — verified-daemon-image
#       и новому verified-daemon-lineage, item 1 волны), и
#       exe_path_lookups_total{result} обеими границами окна.
#   (2) 6.2.6.11 зовёт _w626_metric_sum с фильтром по comm="w626sig" вместо
#       пустого аргумента (№267 — пустой фильтр суммировал ВСЕ comm, включая
#       позитивные контроли bash/sshd; сама возможность фильтровать в
#       _w626_metric_sum уже существовала).
#   (3) Новый критерий 6.2.6.15 печатает долю величины на нерезолвленном
#       образе (exe_path_lookups_total{unresolved}/(resolved+unresolved)) и
#       поимённый список comm тех алертов окна, чьё правило несёт исключение
#       на exe_path/lineage — диагностика гонки №261, порог не назначается.
#
# ВТОРОЙ ПРОХОД (08.09.2026): КРИТЕРИИ ITEMS 1/2/3/4 ВЖАТЫ В ЭТОТ ФАЙЛ.
#   6.2.4.5  — четыре половины исхода №253/№261, включая НОВУЮ четвёртую:
#              подачу от короткоживущего потомка cron (задание в /etc/cron.d)
#              и требование ненулевого rule_exceptions_total{verified-daemon-lineage}
#              как сторожа ложного нуля;
#   6.2.4.6  — заменяет 6.2.3.7 (метка сохранена, №269) и вычитает окно
#              стартов подов контроля 6.2.6.10 (item 3, №263);
#   6.2.4.7  — побег по-прежнему промотируется (отрицательный контроль item 2);
#   6.2.4.12 — время до заморозки на БОЕВОМ капе, поимённо, без порога;
#   6.2.6.16 — шлюз промоушена судится по корню; судит ОБА окна старта
#              контейнера — своё и вычтенное из 6.2.4.6 (item 3 ничего не теряет);
#   6.2.6.17 — stuck/overdue поимённо на обеих границах окна + именной
#              переход из журнала (item 4);
#   6.2.6.14 — сводный вердикт регрессионного пучка (реестр вынесенных меток).
#
# ITEM 6 (№269/№270 — страж полноты пайплайна, 6.2.6.18) ЖИВЁТ ВНЕ ЭТОГО
# ФАЙЛА: wave6.2.6-completeness-guard.sh, вызывается run-6.2.6-pipeline.sh
# ПОСЛЕ этого скрипта, сверяя таблицу меток постановки со списком меток, по
# которым здесь и в пайплайне реально вынесен вердикт (ПРОВАЛЕН/ДОСТИГНУТО/
# НЕИЗМЕРИМ в run-6.2.6.log). Расхождение — отказ собрать архив. Гейт
# офлайн-тестируем через `wave6.2.6-completeness-guard.sh --self-test`.
#
# ТРЕТИЙ ПРОХОД (09.09.2026) — ITEM 7 ПОСТАНОВКИ ВОЛНЫ (plan.md, §6.2.6,
# находки №278/№279/№280): три вердиктных дефекта контролей волны 6.2.5,
# унаследованных этим форком, исправлены здесь же:
#   6.2.4.7  — `incident_confirmed_attack` засчитывается ТОЛЬКО с корнем
#              подающего процесса побега; инциденты с иными корнями
#              печатаются справочно и в вердикт не идут (№278 — раньше
#              засчитывался любой инцидент-атака за окно подачи, включая
#              случайные корни вроде k3s-server).
#   6.2.6.A  — вердикт выносится по ДВУМ ПОЛОВИНАМ КОНЪЮНКТИВНО (длина
#              пролога > порога И дельта потерь за пролог = 0), без формы
#              `elif` — обе половины считаются независимо и сводятся одним
#              `if` в конце (№279, память elif-verdict-masks-independent-halves).
#              При ненулевых потерях печатается разбивка по {collector,reason}
#              из ebpf_guard_events_dropped_total на обоих снимках пролога.
#   6.2.4.6  — реестр судит по ДЕРЕВУ, а не по имени корня: инцидент, чья
#              цепочка ЦЕЛИКОМ состоит из фоновых акторов ноды (в т.ч.
#              run-parts/update-motd-*/00-header/landscape-sysinfo/
#              unattended-upgr), — ложь независимо от того, чьё имя стоит в
#              корне (№280 — прежняя форма судила по .details.root_comm и
#              пропускала sshd→run-parts→00-header, потому что корень sshd не
#              входит в реестр нодовых акторов, хотя ВСЯ остальная цепочка —
#              фоновая работа ноды).
#
#
# ИСТОРИЯ, item 3 постановки 6.2.3 (№249 + решение 4 — механизм немоты op=write установлен подачей,
# 06.09.2026): критерии 6.2.3.5/6.2.3.6 подают `echo … >> path` и
# `dd of=path` на один и тот же путь под /var/log/ и читают исход
# sigma_log_deletion по КАЖДОЙ подаче отдельно. Живой прогон на ebaka2 назвал
# механизм — FD→PATH (dup2 не хукнут): в NOFIX-сборке (dup-хуки отключены)
# ОБЕ подачи молчали (strace дал незапланированный факт — GNU dd с `of=`
# тоже идёт через open→dup2(fd,1)→write(1,…), а не пишет в свой собственный
# fd, как предполагала постановка), в WITHFIX — обе поднимают с верным
# путём. Хуки sys_enter_dup/dup2/dup3 (bpf/fileaccess.bpf.c, dup_commit)
# переносят fd_path_map на новый fd при возврате из dup-вызова; привязка не
# тихая — тот же счётчик ebpf_guard_file_hook_attach_total, что у chmod.
#
# ИСТОРИЯ, item 4 постановки 6.2.3 (№248, сужение верхушки шума, 06.09.2026): sigma_failed_login_syscall_daemon
# и rootkit_pam_module_added_daemon (rules/sigma-linux.yaml,
# rules/rootkit-detection.yaml) сужены осью op=write — были: любой read/open
# от sshd|cron, 3090/2400 и 2970/2280 алертов/окно на двух архивах 6.2.2,
# первые два источника разбивки (в) (6.2.6.2). Критерий 6.2.3.13 берёт обе
# половины живьём: фон (26 sshd-подключений за 90 с реального
# ssh-брутфорса на ebaka2) молчит; подделка identity (comm=sshd/cron через
# копию бинаря, а не `exec -a` — argv[0] не задаёт comm, задаёт basename
# пути execve), ДЕЙСТВИТЕЛЬНО пишущая в PAM, по-прежнему поднимает оба
# правила (severity=info, считаются в alerts_filtered_total, входят в
# формулу (а) — решение 1). Записи new-rules.txt датой 20260906.
#
# ИСТОРИЯ, item 1 постановки 6.2.3 (чинится измеритель — до всего остального):
#   №251  Инцидентный слой (6.2.2.9 → 6.2.3.7): вердикт строится на
#         ПОЛНОМ W626_NODE_ACTORS (список уже был в файле, цикл его не
#         использовал — критерий 6.2.2.9 проверял только
#         runc:[...]/flannel/comm измерителя и промахивался мимо
#         containerd-shim/k3s-server/kubelet/coredns/etc). Добавлено
#         разделение по фазам: инцидент с корнем из
#         W626_NODE_ACTORS∪W626_INSTR_COMMS_FLAT, чьё время попадает в окно
#         позитивных контролей [attack_phase_start, attack_phase_end], есть
#         ОЖИДАЕМЫЙ true positive и в ложь не засчитывается; вне окна —
#         засчитывается. Границы фазы пишутся эпохами в тот же
#         window-epoch.txt, что и границы тихого окна.
#   №252  HOME контроля — $W626_ART, а не /root (иначе .curlrc, .kube/cache,
#         .jq, .cache/go-build сами становятся источником алертов
#         drift_new_file_dir_sensitive, находка №252). Критерий доли
#         измерителя (6.2.2.5 → 6.2.6.3) проверяет ОБА пути — $W626_ART и
#         /root — и остаётся ВЕРДИКТОМ, а не поправкой к чтению. Список comm
#         измерителя (W626_INSTR_COMMS_FLAT) строится САМОСКАНИРОВАНИЕМ
#         текста этого файла (какие внешние команды он реально вызывает), а
#         не задаётся руками; sleep/setsid/sh/dd/printf обязаны быть
#         найдены — иначе преflight ПРОВАЛЕН.
#
# ИСТОРИЯ, item 2 постановки 6.2.3 (№248 + решение 1 — формула гейта закрывается):
#   Критерий 6.2.6.1 (было 6.2.2.1) печатает все ЧЕТЫРЕ слоя раздельно:
#   alerts_total, alerts_filtered_total, alerts_ratelimited_by_rule_total,
#   alerts_dedup_dropped_by_rule_total. Вердикт по-прежнему выносится
#   формулой (а) = alerts_total + alerts_filtered_total (info включительно,
#   решение 1: (б) без info отвергнута — переименование объёма, №232). Рядом
#   ОБЯЗАТЕЛЬНА величина (в) = сумма всех четырёх слоёв, БЕЗ порога (правило
#   5.9.6 — порог впервые измеренной величине не назначается). Страж ложного
#   PASS сохранён и уточнён: PASS по (а) при непустом списке правил с
#   ненулевым срезом лимитера ЗА ОКНО есть НЕИЗМЕРИМОСТЬ, а не взятый
#   критерий (FAIL при тех же условиях действителен). Новый критерий 6.2.6.2
#   ранжирует поимённую разбивку по (в) — через w626_value_v_by_rule
#   (wave6.2.6-metrics-lib.sh) — а не по остатку после лимитера, как делала
#   6.2.2.3; офлайн-сторож на ОБОИХ архивах 6.2.2 проверяет, что первыми
#   встают sigma_failed_login_syscall_daemon и rootkit_pam_module_added_daemon
#   (3090/2970 на collect-6.2.2-run1, 2400/2280 на collect-6.2.2), а не
#   c2_periodic_beacon_pattern (985/985) — см. --self-test в
#   wave6.2.6-metrics-lib.sh.
#
# ЧТО НАСЛЕДОВАНО БЕЗ ИЗМЕНЕНИЙ ИЗ 6.2.2 (перенумеровано механически, подача
# та же): №238 (список срезанных правил по метрике, w626_ratelimited_by_rule),
# №239 (разбивка величины по метрике, 6.2.2.3 остаётся под старым номером —
# критерий 6.2.3.12 в 6.2.3, регрессионный пучок этой волны — 6.2.6.14, ниже), №240 (эпоха вместо ISO-8601 для journalctl), №241
# (копия лога — последним действием, в пайплайне), №237 (заморозка базы
# дрейфа приращением счётчика), №236 (цена старта пода, порог 45/под), №244
# (профиль и потолок ресурсов пайплайном, 6.2.6.8/6.2.6.9), №243 (живой
# сторож monitored_syscalls).
#
# ЧТО ПЕРЕНЕСЕНО РЕГРЕССИЕЙ И ПОЧЕМУ СОХРАНИЛО СТАРЫЕ НОМЕРА. Контроли
# 6.2.1.2, 6.2.1.2b, 6.2.1.3, 6.2.1.6, 6.2.1.8, 6.2.1.9, 6.2.2.2, 6.2.2.3,
# 6.2.2.6, 6.2.3.5, 6.2.3.6, 6.2.3.13, 6.2.3.14 — тринадцать штук (плюс
# 6.2.4.6, инцидентный слой, ПЕРЕИМЕНОВАННЫЙ из 6.2.3.7 и дополненный
# вычитанием окна стартов подов — item 3) — стоят под СВОИМИ
# старыми метками (перечень зафиксирован постановкой волны 6.2.6, plan.md,
# критерий 6.2.6.14). Их метки НЕ перенумерованы намеренно (память
# criteria-index-pins-replay-labels): перенумерация меток — ровно то, что
# роняет преflight на прошлых архивах. Новые/изменённые критерии этой волны
# несут номера 6.2.6.*, и вердикт-файл читается однозначно.
#
# ЗАПУСК. Скрипт не самостоятелен: нужен живой агент с kubernetes.enabled:true
# и готовая нода. Провал контроля НЕ убивает чужой прогон (волна 6.0m,
# память die-only-for-unmeasurable-run); die() здесь только считает и пишет
# вердикт.
#   W626_API           — база HTTP API агента (http://<host>:19090)
#   W626_TOKEN         — bearer-токен (формат файла токена — admin=<...>)
#   W626_KUBECTL       — путь к kubectl
#   W626_NS            — namespace контролей (по умолчанию w626)
#   W626_WINDOW        — длина тихого окна объёма, с (по умолчанию 600)
#   W626_GATE          — гейт волны 6, алертов/ч (по умолчанию 100)
#   W626_GATE_FORMULA  — all | noinfo (решение по №232; по умолчанию all)
#   W626_CHURN_BUDGET  — порог цены старта пода (по умолчанию 45, №236)
#   W626_PROFILE_SECS  — длина окна pprof (по умолчанию 30, №244)
#   W626_SMOKE         — 1: смок-режим, все ветки исполняются на коротких
#                        временах; длинные ожидания укорочены, НИ ОДИН блок
#                        не пропускается (память smoke-only-does-not-cover-attack-window)
set -u
export TZ=UTC   # см. _w626_epoch/_w626_utc: встроенный printf вместо внешнего `date`

VPS_IP="${VPS_IP:-localhost}"
W626_API="${W626_API:-http://${VPS_IP}:19090}"
W626_TOKEN="${W626_TOKEN:-${EBPF_GUARD_TOKEN:-$(grep '^admin=' /var/lib/ebpf-guard/token 2>/dev/null | cut -d= -f2)}}"
W626_KUBECTL="${W626_KUBECTL:-/usr/local/bin/kubectl}"
W626_NS="${W626_NS:-w626}"
W626_WINDOW="${W626_WINDOW:-600}"
W626_GATE="${W626_GATE:-100}"
W626_GATE_FORMULA="${W626_GATE_FORMULA:-all}"
# ЗАПАС ГЕЙТА (открытый вопрос 16(б), постановка 6.2.6.1). Постановка требует
# PASS только при запасе не хуже 1,5× — «≤ 11 алертов за 600-секундное окно»,
# то есть 66/ч. В коде запас держится В ЧАСОВОЙ форме, а не абсолютным
# числом 11: смок гоняет окно короче 600 с, и абсолютный порог там означал бы
# совсем другой запас (при W626_WINDOW=120 одиннадцать алертов это 330/ч).
# 6.2.6.21 читает ЭТУ ЖЕ величину — до правки он считал свой порог сам, и
# критерий 6.2.6.1 мог вынести ДОСТИГНУТО при запасе, которого 6.2.6.21 не
# принимал (расхождение двух чисел в одном прогоне).
W626_GATE_MARGIN="${W626_GATE_MARGIN:-66}"
W626_CHURN_BUDGET="${W626_CHURN_BUDGET:-45}"
W626_PROFILE_SECS="${W626_PROFILE_SECS:-30}"
W626_SETUP="${W626_SETUP:-$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)}"
W626_SETTLE="${W626_SETTLE:-20}"
W626_POS_TIMEOUT="${W626_POS_TIMEOUT:-120}"
W626_CHURN="${W626_CHURN:-3}"
W626_SVC="${W626_SVC:-ebpf-guard-test.service}"
W626_VERDICTS="${W626_VERDICTS:-/root/wave6.2.6-controls-verdicts.txt}"
# КАТАЛОГ АРТЕФАКТОВ — ВНЕ /root/, и это не вкусовщина, а вторая половина
# критерия 6.2.6.3 (открытый вопрос 16). drift_new_file_dir_sensitive стоит на
# префиксах /root/, /home/, /var/spool/cron/, /etc/cron.d/, /etc/systemd/system/
# (rules/drift-rules.txt), то есть КАЖДАЯ запись снимка метрик в /root/… по
# построению производит алерт, который контроль потом считает частью
# измеренной величины. Смок 06.09.2026 это и напечатал. Порядок операций
# (правка №242) сужает окно гонки, но не убирает источник; убирает его путь.
# /var/lib/ вне всех файловых префиксов правил (проверено grep по rules/:
# waagent/tomcat/mysql/…/docker/containerd/rancher/kubelet — ни один не наш).
W626_ART="${W626_ART:-/var/lib/w626-artifacts}"
W626_REPO="${W626_REPO:-/opt/ebpf-guard}"
W626_GO="${W626_GO:-/usr/local/go/bin/go}"
W626_SMOKE="${W626_SMOKE:-0}"
W626_QUIET_LEAD="${W626_QUIET_LEAD:-70}"
W626_OPEN_SETTLE="${W626_OPEN_SETTLE:-15}"

WAVE624_FAILS=0
# Артефакты пишутся в КАТАЛОГ ЭТОГО ПРОГОНА и он очищается на старте
# (находка №228).
rm -rf "$W626_ART" 2>/dev/null || true
mkdir -p "$W626_ART" 2>/dev/null || true

# №258 (item 8 постановки 6.2.6): ФИФО для read-based ожидания тихого окна
# создаётся ЗДЕСЬ, задолго до t0, а НЕ рядом с самим ожиданием. `mkfifo` —
# внешняя команда (execve, comm=mkfifo) не хуже `sleep` в этом смысле; если
# вызвать её после фиксации t0, она сама станет тем самым инструментальным
# событием ВНУТРИ окна, которое чинит вся эта правка. Once здесь, до
# преflight'а и открытия окна, mkfifo не попадает в измеряемый период вовсе.
W626_QUIET_FIFO="$W626_ART/.quiet-window-fifo"
mkfifo "$W626_QUIET_FIFO" 2>/dev/null || true

# №252: HOME контроля — В КАТАЛОГЕ АРТЕФАКТОВ, не /root. Каждый curl/kubectl/
# jq, запущенный из-под этого скрипта под root, пишет свой конфиг/кеш в
# $HOME (.curlrc читается curl, .kube/cache — kubectl, .cache/go-build — go
# tool pprof в критерии 6.2.6.8); при HOME=/root это ровно тот путь, за
# которым следит drift_new_file_dir_sensitive (rules/drift-rules.txt,
# префикс /root/), и запись в него сама производит алерт, входящий в
# измеренную величину. Экспортируется ДО первого curl/kubectl этого файла.
export HOME="$W626_ART"
mkdir -p "$HOME" 2>/dev/null || true

# РЕЕСТР ВЫНЕСЕННЫХ ВЕРДИКТОВ (критерий 6.2.6.14 + вход стража 6.2.6.18).
# Пишется ОБЕИМИ функциями вердикта, а не только die(): регрессионный пучок
# 6.2.6.14 обязан отличить «метка вынесла ДОСТИГНУТО» от «метка не вынесла
# ничего», а вердикт-файл до этой правки хранил только провалы, и по нему
# тринадцать регрессий были неотличимы от нереализованных (тот же класс, что
# №269/№270, только внутри одного скрипта).
W626_EMITTED="$W626_ART/emitted-labels.txt"
: > "$W626_EMITTED" 2>/dev/null || true
#
# ПОДПУНКТЫ ПИШУТСЯ ПОД ОТДЕЛЬНЫМ КЛЮЧОМ (правка 09.09.2026, найдена при
# заведении подпункта (4) item 6). Критерий 6.2.6.1 выносит ЧЕТЫРЕ подпунктных
# вердикта («6.2.6.1 подпункт (3) ДОСТИГНУТО») ДО своего главного, и все они
# писались в реестр той же строкой «6.2.6.1 OK». Читатель реестра
# (6.2.6.21, условие 1: grep '^6\.2\.6\.1 OK$') не мог отличить их от главного
# вердикта — то есть при ПРОВАЛЕННОМ гейте критерий выхода из куста прочитал
# бы OK подпункта и объявил условие 1 взятым. Это ровно тот класс ложного
# PASS, ради которого 6.2.6.21 и заводился, только внутри его собственного
# входа. Ключ подпункта теперь «<метка>/подпункт», главный вердикт — «<метка>».
# Ключ считает библиотека (w626_label_key) — у неё есть офлайн-сторож,
# который зовёт ИМЕННО ЭТУ функцию. Откат на локальную копию нужен потому,
# что реестр пишется и в том случае, когда библиотека не подключилась (её
# отсутствие объявляется НЕИЗМЕРИМОСТЬЮ ниже, но реестр к этому моменту уже
# обязан работать: сама строка «библиотека не подключилась» пишется через die).
_w626_record_label() { # $1=OK|FAIL $2...=текст вердикта
    local _st="$1"; shift
    local _lbl
    if command -v w626_label_key >/dev/null 2>&1; then
        _lbl=$(w626_label_key "$*")
    else
        _lbl=$(printf '%s' "$*" | grep -oE '^6\.[0-9]+(\.[A-Za-z0-9]+)*' | head -1)
        case "$*" in *подпункт*) _lbl="${_lbl:+$_lbl/подпункт}" ;; esac
    fi
    [ -z "${_lbl:-}" ] && return 0
    echo "$_lbl $_st" >> "$W626_EMITTED" 2>/dev/null
    return 0
}
die() {
    echo "=== КОНТРОЛЬ ПРОВАЛЕН (прогон НЕ прерывается — волна 6.0m): $* ==="
    WAVE624_FAILS=$((WAVE624_FAILS + 1))
    _w626_record_label FAIL "$*"
    {
        echo "критерий=$(printf '%s' "$*" | grep -oE '^6\.[0-9]+(\.[A-Za-z0-9]+)*' | head -1)"
        echo "время_UTC=$(date -u +%FT%TZ)"
        echo "причина: $*"
        echo "---"
    } >> "$W626_VERDICTS" 2>/dev/null || true
    return 0
}
pass() { echo "OK: $*"; _w626_record_label OK "$*"; }

: > "$W626_VERDICTS" 2>/dev/null || true
echo "# wave6.2.6-controls.sh, прогон от $(date -u +%FT%TZ)" >> "$W626_VERDICTS"
echo "=== КОНТРОЛИ ВОЛНЫ 6.2.6 (долг прогона 6.2.3, находки №253…№260) ==="
echo "режим: $([ "$W626_SMOKE" = "1" ] && echo 'СМОК (короткие времена, все ветки исполняются)' || echo 'полный')"
echo "формула гейта (решение 1, №232/№248): $W626_GATE_FORMULA (all = включая severity=info, noinfo = без него; обе величины и величина (в) печатаются в любом случае)"
echo "HOME контроля (№252): $HOME"

# ─────────────────────────────────────────────────────────────────────────────
# ИЗМЕРИТЕЛЬНАЯ БИБЛИОТЕКА (№238/№239). Берётся source'ом, а не копией: у
# копии нет офлайн-сторожа, а у этого файла он есть и проходит на
# collect-6.2.1 (--self-test). Отсутствие библиотеки — не «работаем без
# разбивки», а неизмеримость критериев 6.2.2.2/6.2.2.3.
# ─────────────────────────────────────────────────────────────────────────────
W626_LIB="$W626_SETUP/wave6.2.6-metrics-lib.sh"
W626_LIB_OK=0
if [ -r "$W626_LIB" ]; then
    # shellcheck source=/dev/null
    . "$W626_LIB" && W626_LIB_OK=1
fi
# ВОССТАНОВЛЕНИЕ РЕЖИМА ОБОЛОЧКИ — не косметика, а дефект, пойманный смоком
# 06.09.2026 ДО прогона. wave6.2.6-metrics-lib.sh объявляет `set -euo pipefail`
# (правильно для самостоятельного файла со своим --self-test), но `source`
# переносит этот режим В ВЫЗЫВАЮЩИЙ скрипт. Контроли построены на том, что
# `grep`/`jq` без совпадения возвращают 1 и это НОРМАЛЬНЫЙ исход измерения
# («такого в журнале нет»), а не сбой: под `set -e` первый же такой grep убивал
# контроли МОЛЧА, посреди 6.2.1.6, и пайплайн спокойно собирал архив без
# единого критерия. Ровно тот класс, который ловит сама волна: измеритель,
# печатающий готовый вердикт по неполному прогону.
set +e +o pipefail
set -u
# Список правил-двойников №253 приходит из библиотеки (W626_TWIN_RULES).
# Дублируется значением по умолчанию: без библиотеки контроли ниже читают эту
# переменную под `set -u` и умерли бы на «unbound variable» посреди
# измерения, вместо того чтобы объявить критерий НЕИЗМЕРИМЫМ и идти дальше
# (память die-only-for-unmeasurable-run).
: "${W626_TWIN_RULES:=sigma_passwd_shadow_read_daemon sigma_log_deletion_daemon sigma_utmp_wtmp_modified_daemon sensitive_file_read_daemon}"
# То же и для функций, появившихся в библиотеке 14.09.2026 (№300/№302): без
# библиотеки они не объявлены, и вызов под `set -u` дал бы не «критерий
# неизмерим», а мусор в вердикте. Заглушки печатают ОТКАЗ словом, а не нулём
# (память die-only-for-unmeasurable-run + open-refusal exe_path).
if [ "$W626_LIB_OK" -ne 1 ]; then
    w626_window_top_tree() { printf '0\t(библиотека не подключилась)\t0'; }
    w626_tree_price_for_pid() { printf '0'; }
    w626_force_mechanism_is_winner() { return 1; }
    w626_c21_why() { printf '%s' "условия не разобраны: библиотека не подключилась (см. вердикт 6.2.2.2)"; }
fi
[ "$W626_LIB_OK" -eq 1 ] || die "6.2.2.2 НЕИЗМЕРИМ: не подключилась $W626_LIB — список срезанных правил и разбивка величины строились бы снова по стору, то есть воспроизвели бы дефекты №238/№239"

# Правила, для которых нода — единственный вход.
W626_K8S_RULES="cis_5_1_3_secret_access k8s_sa_token_read k8s_sa_token_projected_read k8s_hostpath_kubelet_access"
W626_HOST_RULES="cis_5_1_3_secret_access k8s_hostpath_kubelet_access"
W626_NODE_ACTORS="k3s-server kubelet containerd containerd-shim containerd-shim-runc-v2 runc runc:[1:CHILD] runc:[2:INIT] coredns local-path-prov kube-proxy pause iptables ip6tables kubectl flannel bridge loopback"

# ---------------------------------------------------------------------------
# №252: список comm ИЗМЕРИТЕЛЯ строится САМОСКАНИРОВАНИЕМ этого файла, а не
# задаётся руками. Находка №242 чинилась вручную дописанным cat/tail; находка
# №252 требует, чтобы список впредь не отставал от того, что скрипт реально
# запускает — кандидаты, найденные как отдельное слово (после пробела,
# `;`, `&`, `|`, `(` или `/`) где-то в тексте ЭТОГО файла, ВКЛЮЧАЮТСЯ
# автоматически. Список кандидатов конечен (это самоскан по словарю, а не
# полный статический анализ), но покрывает всё, чем контроль реально
# пользуется: sleep/setsid/sh/dd обязаны быть найдены — это явное требование
# критерия 6.2.6.3, и его отсутствие есть ПРОВАЛ преflight'а, а не тихая
# недостача.
# ---------------------------------------------------------------------------
W626_INSTR_CANDIDATES="curl jq bash sh head sed awk date tr sort systemctl journalctl cat tail stat find wc cut grep sleep setsid dd printf cp chmod mkdir rm seq pgrep readlink kubectl go"
W626_INSTR_COMMS_FLAT=""
W626_SELF="$W626_SETUP/wave6.2.6-controls.sh"
if [ -r "$W626_SELF" ]; then
    # Скан ИСПОЛНЯЕМОГО текста: строки-комментарии (включая эту преамбулу и
    # саму строку W626_INSTR_CANDIDATES, где перечислены ВСЕ кандидаты разом
    # и потому она тривиально "находит" каждый) вычищены — иначе самоскан
    # находит слово в СВОЁМ ЖЕ описании, а не в реальном вызове.
    _w626_selfcode=$(grep -vE '^[[:space:]]*#' "$W626_SELF" | grep -v '^W626_INSTR_CANDIDATES=')
    for _w626_c in $W626_INSTR_CANDIDATES; do
        if printf '%s\n' "$_w626_selfcode" | grep -qE "(^|[[:space:];&|(/])${_w626_c}([[:space:]\"'\`]|\$)" 2>/dev/null; then
            W626_INSTR_COMMS_FLAT="$W626_INSTR_COMMS_FLAT $_w626_c"
        fi
    done
fi
W626_INSTR_COMMS_FLAT="${W626_INSTR_COMMS_FLAT# }"
echo "  №252, список comm измерителя (самосканирование $W626_SELF): ${W626_INSTR_COMMS_FLAT:-ПУСТ}"
# ТРЕБОВАНИЕ КРИТЕРИЯ 6.2.6.3 (postановка): sleep/setsid/sh/dd обязаны
# присутствовать в списке. `dd` требуется здесь начиная с item 3 (6.2.3.5,
# №249, механизм немоты op=write — нагрузка `dd of=…`) — реальный вызов
# теперь есть в файле, страж больше не отложен.
for _w626_must in sleep setsid sh dd; do
    case " $W626_INSTR_COMMS_FLAT " in
        *" $_w626_must "*) ;;
        *) die "6.2.6.3 НЕИЗМЕРИМ: самоскан не нашёл '$_w626_must' в тексте $W626_SELF — обязательная команда списка (№252) не обнаружена; список comm измерителя неполон по построению" ;;
    esac
done
# Та же плоская строка — как JSON-массив, для jq (критерий 6.2.6.3).
W626_INSTR_COMMS=$(printf '%s\n' $W626_INSTR_COMMS_FLAT | jq -R . | jq -s -c . 2>/dev/null)
[ -n "${W626_INSTR_COMMS:-}" ] && [ "$W626_INSTR_COMMS" != "null" ] || W626_INSTR_COMMS='[]'

_w626_curl() { curl -s --max-time 30 -H "Authorization: Bearer $W626_TOKEN" "$@"; }
_w626_alerts() { _w626_curl "$W626_API/api/v1/alerts?limit=200000"; }
_w626_metrics() { _w626_curl "$W626_API/metrics"; }
# ЭПОХА — ВСТРОЕННЫМ printf, а не `date`. Каждый вызов внешнего `date` —
# это execve, а значит собственное событие измерителя: на прогоне 06.09.2026
# критерий 6.2.6.3 упал ровно на двух алертах comm=date, которые породил сам
# контроль строкой «окно открыто …» СРАЗУ ПОСЛЕ фиксации t0. Встроенный
# printf процесса не создаёт вовсе, поэтому источник исчезает, а не сдвигается.
# TZ=UTC экспортирован выше — форматы ниже эквивалентны `date -u`.
_w626_epoch() { local _e; printf -v _e '%(%s)T' -1; printf '%s' "$_e"; }
_w626_utc() { printf '%(%Y-%m-%dT%H:%M:%SZ)T' "$1"; }

# Сумма метрики по срезу. Прямая дельта двух срезов, а не строка таблицы:
# строка индексирована срезом лимитера (память f6b-table-indexed-by-limiter-cut).
_w626_metric_sum() { # $1=metric $2=список label-значений (rule_id ИЛИ comm; пусто = все) [$3=файл среза]
    # №267 (item 5): фильтр match'ит значение ЛЮБОГО лейбла в кавычках, а не
    # только rule_id="..." — иначе _w626_metric_sum не может выделить comm
    # для метрик без rule_id (ebpf_guard_drift_baseline_signature_cap_reached_total{comm=...}),
    # и вызывающая сторона (6.2.6.11) вынуждена звать её с пустым аргументом,
    # суммируя ВСЕ comm сразу. Возможность фильтровать уже была — не хватало
    # generic-совпадения по значению.
    # Само совпадение живёт в wave6.2.6-metrics-lib.sh (w626_metric_sum_file):
    # у библиотеки есть офлайн-сторож, который зовёт ИМЕННО ЭТУ функцию, а не
    # свою копию awk. Здесь остаётся только источник среза — живой /metrics
    # или файл. Откат на локальный awk — на случай, если библиотека не
    # подключилась (её отсутствие уже объявлено НЕИЗМЕРИМОСТЬЮ выше, но
    # молча падать на «команда не найдена» контроль не должен).
    local metric="$1" ids="${2:-}" src="${3:-}"
    if [ "$W626_LIB_OK" -eq 1 ]; then
        { [ -n "$src" ] && cat "$src" || _w626_metrics; } | w626_metric_sum_file "$metric" "$ids" -
    else
        # Откат на локальную копию: отсутствие библиотеки уже объявлено
        # НЕИЗМЕРИМОСТЬЮ выше, но контроль не должен падать «команда не
        # найдена» посреди измерения.
        { [ -n "$src" ] && cat "$src" || _w626_metrics; } | awk -v m="$metric" -v ids="$ids" '
            BEGIN { n = split(ids, a, " ") }
            $0 ~ "^"m"[{ ]" {
                if (n == 0) { s += $NF; next }
                for (i = 1; i <= n; i++) if (index($0, "\"" a[i] "\"")) { s += $NF; next }
            }
            END { printf "%d", s+0 }'
    fi
}
# Скалярная метрика без лейблов (process_*, go_*): $NF может быть в
# экспоненциальной записи (1.37413104e+08), поэтому печатается через %.0f.
_w626_metric_raw() { # $1=metric $2=файл среза
    awk -v m="$1" '$1 == m { printf "%.0f", $2+0; found=1; exit } END { if (!found) printf "" }' "$2" 2>/dev/null
}

# ---------------------------------------------------------------------------
# ОБЪЁМ И РЕШЕНИЕ №232.
#
# Формула 6.2.1 (№227) — alerts_total + alerts_filtered_total по всем
# severity. Находка №230 показала, что 94% величины прошлого прогона это
# severity=info, которого нет в сторе; №232 спрашивает владельца, считать ли
# его. Решение зафиксировано ДО прогона и в прогоне не меняется (критерий
# 6.2.6.1), но ОБЕ величины печатаются всегда: разница двух — это цена
# решения №232 числом, а не прогнозом.
#
# Почему вердикт по умолчанию по «all»: filtered_total — это то, что срезано
# min_severity. Формула без info позволяет «починить» шумное правило
# понижением его severity: величина упадёт, а работа агента (regex,
# обогащение, дедуп, кольцевой буфер) останется та же. Гейт перестал бы быть
# гейтом. См. plan.md, №232.
# ---------------------------------------------------------------------------
_w626_volume_all() { # $1=файл среза
    awk '/^ebpf_guard_alerts_total[{ ]/ || /^ebpf_guard_alerts_filtered_total[{ ]/ { s += $NF } END { printf "%d", s+0 }' "$1"
}
_w626_volume_noinfo() { # $1=файл среза
    awk '(/^ebpf_guard_alerts_total[{ ]/ || /^ebpf_guard_alerts_filtered_total[{ ]/) && !/severity="info"/ { s += $NF } END { printf "%d", s+0 }' "$1"
}
_w626_ratelimited() { _w626_metric_sum ebpf_guard_alerts_ratelimited_by_rule_total "${1:-}" "${2:-}"; }
# Потери событий БЕЗ path_denylist (№222): denylist — законный фильтр, а не
# потеря видимости.
_w626_real_drops() { # [$1=файл среза]
    { [ -n "${1:-}" ] && cat "$1" || _w626_metrics; } | awk '
        /^ebpf_guard_events_dropped_total\{/ && !/reason="path_denylist"/ { s += $NF }
        /^ebpf_guard_event_queue_dropped_total/ { s += $NF }
        END { printf "%d", s+0 }'
}
# Журнальный счётчик потерь (№222, второй слой). №240: журнал читается ОТ
# СТАРТА АГЕНТА, а не за всю историю юнита — иначе величина принадлежит
# прошлым прогонам.
# 6.2.9.F.4 (№294, item 4 волны 6.2.9.F): СТОРОЖ ПОТЕРЬ НА ГРАНИЦАХ ОКОН
# ПОДАЧИ, А НЕ ТОЛЬКО ТИХОГО ОКНА. До этой правки потери снимались только на
# границах [t0,t1] (6.2.6.A/6.2.6.0) — окна ПОДАЧИ (старты подов, побег,
# инициализация контейнера) мерились на приборе, который мог терять события
# незамеченно: журнал первого прогона показал 111 fileaccess/ringbuf_to_router
# внутри окна стартов подов и 645 syscall/ringbuf_to_router внутри окна
# подачи 6.2.6.16, и вердикты этих окон печатались без единого слова о
# потерях — «21,7 алертов/под» была нижней оценкой, объявленной измеренной.
# Печатает разбивку {collector,reason} между двумя снимками окна подачи;
# устанавливает _W626_LOSS_NONZERO=1, если суммарная дельта потерь (без
# path_denylist) ненулевая — вызывающая сторона обязана добавить в свой
# вердикт явное слово «НИЖНЯЯ ОЦЕНКА», а не молчать о потерях, как раньше.
#
# ИМЯ ОКНА ПЕРЕДАЁТСЯ БЕЗ НОМЕРА КРИТЕРИЯ. Строка этого сторожа несёт
# вердиктное слово, и метка чужого критерия внутри неё была бы прочитана
# стражем полноты (6.2.6.18 матчит «<метка> … (ДОСТИГНУТО|ПРОВАЛЕН|
# НЕИЗМЕРИМ|ИЗМЕРЕНО)» по всей строке) как вынесенный вердикт ПО ЧУЖОЙ
# МЕТКЕ — тот же класс ложного PASS, что №269. Номера критериев остаются в
# комментариях у call-site'ов.
#
# ОТСУТСТВУЮЩИЙ СНИМОК — НЕИЗМЕРИМОСТЬ, А НЕ НОЛЬ. `_w626_real_drops` при
# нечитаемом файле молча падает на ЖИВОЕ чтение /metrics (ветка `|| _w626_metrics`
# в её определении выше), и дельта двух живых чтений дала бы «потерь нет» на
# прогоне, где снимок просто не был снят. Файлы проверяются явно.
_w626_submission_loss_guard() { # $1=имя окна (БЕЗ номера критерия) $2=файл-начало $3=файл-конец
    local label="$1" f0="$2" f1="$3" d
    if [ ! -s "$f0" ] || [ ! -s "$f1" ]; then
        _W626_LOSS_NONZERO=0; _W626_LOSS_LAST=0
        die "6.2.9.F.4 НЕИЗМЕРИМ (№294): окно подачи «${label}» — снимок границы отсутствует или пуст ($(basename "$f0") / $(basename "$f1")), потери внутри окна снять нечем; вердикт этого окна остаётся НИЖНЕЙ ОЦЕНКОЙ без числа"
        return 0
    fi
    d=$(( $(_w626_real_drops "$f1") - $(_w626_real_drops "$f0") ))
    if [ "$W626_LIB_OK" -eq 1 ] && [ "${d:-0}" -ne 0 ]; then
        w626_drops_by_reason "$f0" "$f1" | sed 's/^/    /'
    fi
    if [ "${d:-0}" -ne 0 ]; then
        _W626_LOSS_NONZERO=1
    else
        _W626_LOSS_NONZERO=0
    fi
    _W626_LOSS_LAST=${d:-0}
    pass "6.2.9.F.4 ИЗМЕРЕНО (№294, порог величине не назначается): окно подачи «${label}» — дельта потерь без path_denylist = ${_W626_LOSS_LAST}$([ "${_W626_LOSS_NONZERO}" -eq 1 ] && echo ' (ненулевая: вердикт этого окна — НИЖНЯЯ ОЦЕНКА, разбивка по {collector,reason} выше)' || echo ' (ноль напечатан обеими границами, как требует постановка)')"
}
_w626_journal_since() {
    if [ -s /root/agent-start-6.2.6.epoch ]; then
        echo "@$(cat /root/agent-start-6.2.6.epoch)"
    else
        systemctl show "$W626_SVC" -p ActiveEnterTimestampMonotonic --value >/dev/null 2>&1
        local t; t=$(systemctl show "$W626_SVC" -p ActiveEnterTimestamp --value 2>/dev/null)
        local e; e=$(date -d "$t" +%s 2>/dev/null)
        [ -n "${e:-}" ] && echo "@$e" || echo "-1 hour"
    fi
}
_w626_journal_drops() {
    journalctl -u "$W626_SVC" --since "$(_w626_journal_since)" --no-pager 2>/dev/null \
        | grep -o '"bulk_dropped_since_start":[0-9]*' | tail -1 | cut -d: -f2
}

# Смок-режим укорачивает ОЖИДАНИЯ, но не выкидывает блоки.
if [ "$W626_SMOKE" = "1" ]; then
    W626_SETTLE=5
    W626_POS_TIMEOUT=30
    W626_QUIET_LEAD=10
    W626_OPEN_SETTLE=5
fi

# ─────────────────────────────────────────────────────────────────────────────
# ПРЕFLIGHT. Провал здесь означает, что величины ниже нечем читать.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.2 преflight ---"
command -v jq >/dev/null 2>&1 || die "6.2.2 преflight ПРОВАЛЕН: нет jq — все величины по стору неизмеримы"

if [ ! -x "$W626_KUBECTL" ]; then
    die "6.2.2 преflight ПРОВАЛЕН: kubectl не найден ($W626_KUBECTL) — ноду нечем подать на вход, любой ноль ниже приборный"
else
    _w626_ready=$("$W626_KUBECTL" get nodes --no-headers 2>/dev/null | awk '$2=="Ready"{n++} END{print n+0}')
    if [ "${_w626_ready:-0}" -lt 1 ]; then
        die "6.2.2 преflight ПРОВАЛЕН: ни одна нода не Ready"
    else
        pass "6.2.2 преflight: нод Ready = $_w626_ready ($("$W626_KUBECTL" version -o json 2>/dev/null | jq -r '.serverVersion.gitVersion // "?"'))"
    fi
fi

_w626_cfg="${W626_CONFIG:-$W626_SETUP/config-test.yaml}"
_w626_k8s_block=$(awk '/^kubernetes:/{f=1;next} f && /^[a-zA-Z#]/{exit} f' "$_w626_cfg" 2>/dev/null)
_w626_drift_cfg=$(awk '/drift_baseline:/{f=1;next} f && /^[a-zA-Z]/{exit} f' "$_w626_cfg" 2>/dev/null)
echo "$_w626_k8s_block" | grep -qE '^[[:space:]]*enabled:[[:space:]]*true[[:space:]]*(#.*)?$' \
    && pass "6.2.2 преflight: kubernetes.enabled: true в $_w626_cfg" \
    || die "6.2.2 преflight ПРОВАЛЕН: kubernetes.enabled НЕ true — энричер не конструируется, pod_name пуст по построению (находка №216)"

# pprof: без него критерий 6.2.6.8 нереализуем в принципе (находка №244:
# enable_pprof по умолчанию false, и config-test.yaml её никогда не включал —
# /debug/pprof/* 404-ил на живом стенде).
grep -qE '^[[:space:]]*enable_pprof:[[:space:]]*true[[:space:]]*(#.*)?$' "$_w626_cfg" 2>/dev/null \
    && pass "6.2.2 преflight: enable_pprof: true — окно профиля 6.2.6.8 реализуемо" \
    || die "6.2.6.8 НЕИЗМЕРИМ: enable_pprof не true в $_w626_cfg — /debug/pprof/* ответит 404, профиль снять нечем (находка №244)"

_w626_src=$(journalctl -u "$W626_SVC" --since "$(_w626_journal_since)" --no-pager 2>/dev/null | grep -o '"msg":"runtime enricher active","source":"[a-z]*"' | tail -1 | grep -oE '"source":"[a-z]*"' | cut -d'"' -f4)
_w626_k8s_up=$(journalctl -u "$W626_SVC" --since "$(_w626_journal_since)" --no-pager 2>/dev/null | grep -c 'k8s enricher active')
echo "  источник runtime-обогащения: ${_w626_src:-НЕ НАПЕЧАТАН}; строк «k8s enricher active»: $_w626_k8s_up"
[ "${_w626_k8s_up:-0}" -ge 1 ] || die "6.2.2 преflight ПРОВАЛЕН: в журнале нет «k8s enricher active» — pod_name будет пуст по причине вне продукта"

# №240, часть 1: журнал вообще читается ОТ СТАРТА АГЕНТА. Прогон 6.2.1 привёз
# journal-agent-6.2.1.log нулевого размера и не заметил этого.
_w626_jsince=$(_w626_journal_since)
_w626_jlines=$(journalctl -u "$W626_SVC" --since "$_w626_jsince" --no-pager 2>/dev/null | wc -l)
echo "  журнал агента с $_w626_jsince: $_w626_jlines строк"
[ "${_w626_jlines:-0}" -ge 1 ] \
    && pass "6.2.2 преflight: journalctl --since «${_w626_jsince}» даёт непустой журнал (№240: ISO-8601 «T…Z» systemd.time(7) НЕ разбирает, эпоха — разбирает)" \
    || die "6.2.2.4 ПРОВАЛЕН заранее: journalctl --since «${_w626_jsince}» даёт ПУСТО — архив этого прогона будет нереплеиваемым, как collect-6.2.1 (№240)"

# №243, живой сторож. config-test.yaml не задаёт monitored_syscalls, значит
# используется DefaultMonitoredSyscalls() из sampling.go: 19 номеров после
# снятия chmod/fchmod/fchmodat (90/91/268), 22 до него. Число в журнале
# отличает ЗАДЕПЛОЕННУЮ правку от лежащей в дереве.
_w626_ms=$(journalctl -u "$W626_SVC" --since "$_w626_jsince" --no-pager 2>/dev/null \
    | grep -o '"monitored_syscalls":[0-9]*' | tail -1 | cut -d: -f2)
_w626_ms_want=$(awk '/^func DefaultMonitoredSyscalls/,/^}/' "$W626_REPO/internal/bpf/sampling.go" 2>/dev/null | grep -cE '^[[:space:]]+[0-9]+,')
echo "  №243: monitored_syscalls в журнале = ${_w626_ms:-НЕ НАПЕЧАТАН}; в дереве DefaultMonitoredSyscalls() = ${_w626_ms_want:-?}"
if [ -z "${_w626_ms:-}" ]; then
    die "6.2.1.9 (№243) НЕИЗМЕРИМ: строки kernel_filter с monitored_syscalls нет в журнале — задеплоена правка или нет, по этому прогону не установить"
elif [ "${_w626_ms_want:-0}" -gt 0 ] && [ "${_w626_ms:-0}" -ne "${_w626_ms_want:-0}" ]; then
    die "6.2.1.9 (№243) ПРОВАЛЕН: агент поднят на бинаре с ${_w626_ms} syscall'ами, а дерево описывает ${_w626_ms_want}. Правка №243 (снятие chmod с syscall-оси) НЕ задеплоена: chmod по-прежнему даёт второе, никем не читаемое событие, и цена ring buffer в 6.2.6.1 измеряется НЕ на том коде, что лежит в дереве"
else
    pass "6.2.1.9 (№243) ДОСТИГНУТО (половина «деплой»): monitored_syscalls=${_w626_ms} совпадает с деревом — chmod снят с syscall-оси на живом бинаре"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.1.6 РЕГРЕССИЯ: реестр немоты по среде (находка №225), ДО всякого замера.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.1.6 (регрессия): немота по среде ---"
_w626_unreach=$(journalctl -u "$W626_SVC" --since "$_w626_jsince" --no-pager 2>/dev/null | grep -o '"msg":"rules: syscall rules with no reachable nr in the kernel allowlist".*' | tail -1)
_w626_unreach_n=$(printf '%s' "$_w626_unreach" | grep -oE '"count":[0-9]+' | cut -d: -f2)
_w626_unreach_ids=$(printf '%s' "$_w626_unreach" | grep -oE '"rule_ids":\[[^]]*\]' | tr -d '"[]' | sed 's/rule_ids://')
_w626_kmod=$(journalctl -u "$W626_SVC" --since "$_w626_jsince" --no-pager 2>/dev/null | grep -c 'cgroup escape collector unavailable')
echo "  недостижимых syscall-правил: ${_w626_unreach_n:-0}"
echo "  поимённо: ${_w626_unreach_ids:-нет}"
echo "  kmod cgroup-escape коллектор недоступен: $([ "${_w626_kmod:-0}" -gt 0 ] && echo да || echo нет) (ядро $(uname -r))"
# №234/открытый вопрос 7: файловые правила, чей op не производит ни один хук
# сборки, теперь печатаются агентом при старте (UnreachableFileOpRules).
# Это немота ПО ПОСТРОЕНИЮ, и реплей обязан читать её так же, как syscall-ось.
_w626_unreach_f=$(journalctl -u "$W626_SVC" --since "$_w626_jsince" --no-pager 2>/dev/null | grep -o '"msg":"rules: file rules whose op condition names no operation any hook produces".*' | tail -1)
echo "  файловых правил с недостижимым op: ${_w626_unreach_f:-строки нет}"

_w626_registry="$W626_SETUP/attacks/silent-rules.txt"
_w626_reg_ids=$(grep -oE '^[A-Za-z0-9_]+ a$' "$_w626_registry" 2>/dev/null | awk '{print $1}' | sort -u)
_w626_reg_n=$(printf '%s\n' "$_w626_reg_ids" | grep -c .)
_w626_jrn_ids=$(printf '%s' "${_w626_unreach_ids:-}" | tr ',' '\n' | sed '/^$/d' | sort -u)
echo "  реестр (silent-rules.txt, категория а): ${_w626_reg_n} правил"
if [ -z "${_w626_unreach_n:-}" ]; then
    die "6.2.1.6 НЕИЗМЕРИМ: строки о недостижимых правилах нет в журнале — немоту по среде нечем отличить от регресса"
elif [ "$_w626_jrn_ids" != "$_w626_reg_ids" ]; then
    die "6.2.1.6 ПРОВАЛЕН: реестр (${_w626_reg_n} правил) разошёлся со стендом (${_w626_unreach_n} правил: ${_w626_unreach_ids:-нет}) — реплеи архивов этой волны читают расхождение как потерю/регресс"
elif [ "${_w626_kmod:-0}" -gt 0 ] && ! grep -q 'cgroup escape collector unavailable' "$_w626_registry" 2>/dev/null; then
    die "6.2.1.6 ПРОВАЛЕН: kmod cgroup-escape коллектор недоступен на этом ядре, но $_w626_registry не документирует этот факт"
else
    pass "6.2.1.6 ДОСТИГНУТО: реестр немоты по среде совпал со стендом (${_w626_unreach_n} правил + kmod)"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.6.0 ПРИБОРНОСТЬ (первая половина: ось пода).
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.6.0: приборность оси пода ---"
_w626_alerts > "$W626_ART/alerts-preflight.json"
_w626_pod_alerts=$(jq '[.[]|select(((.enrichment.pod_name // "") != "") and ((.enrichment.namespace // "") != ""))]|length' "$W626_ART/alerts-preflight.json" 2>/dev/null || echo 0)
_w626_ns_seen=$(jq -r '.[]|select((.enrichment.namespace // "")!="")|.enrichment.namespace' "$W626_ART/alerts-preflight.json" 2>/dev/null | sort -u | tr '\n' ' ')
echo "  алертов с непустыми namespace И pod_name: $_w626_pod_alerts; namespace'ы: ${_w626_ns_seen:-нет}"
W626_INSTRUMENTED=0
if [ "${_w626_pod_alerts:-0}" -lt 1 ]; then
    die "6.2.6.0 ПРОВАЛЕН: ни одного алерта с личностью пода. Дальше контроли оси пода НЕ ЧИТАЮТСЯ — их ноль был бы приборным"
else
    W626_INSTRUMENTED=1
    pass "6.2.6.0 ДОСТИГНУТО (половина «ось пода»): личность пода доезжает до алерта ($_w626_pod_alerts алертов)"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.6.A, ПОЛОВИНА 1 (длина пролога). ВЕРДИКТ НЕ ВЫНОСИТСЯ ЗДЕСЬ (item 7,
# №279): вторая половина (потери за пролог) измерима только ПОСЛЕ снимка
# metrics-window-start.txt, который берётся ниже, у открытия тихого окна —
# обе половины сводятся в ОДИН конъюнктивный вердикт там, а не здесь по
# форме `elif` (память elif-verdict-masks-independent-halves). Здесь только
# вычисляются и печатаются числа половины 1.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.6.A, половина 1/2 (длина пролога): вычисление, вердикт — ниже ---"
_w626_lp=$(echo "$_w626_drift_cfg" | grep -oE 'learning_period:[[:space:]]*[0-9]+' | grep -oE '[0-9]+' | head -1)
_w626_edp=$(echo "$_w626_drift_cfg" | grep -oE 'enforce_deadline_periods:[[:space:]]*[0-9]+' | grep -oE '[0-9]+' | head -1)
_w626_need=$(( ${_w626_lp:-600} * ${_w626_edp:-2} ))
_w626_started=$(systemctl show "$W626_SVC" -p ActiveEnterTimestamp --value 2>/dev/null)
_w626_started_s=$(date -d "$_w626_started" +%s 2>/dev/null || echo 0)
_w626_prologue=$(( $(date +%s) - _w626_started_s ))
echo "  агент поднят: ${_w626_started:-?}; пролог: ${_w626_prologue}s; требуется > ${_w626_need}s"
echo "  на этот момент: профилей $(_w626_metric_sum ebpf_guard_drift_baseline_profiles ""), из них в learning $(_w626_metric_sum ebpf_guard_drift_baseline_learning_workloads "")"
_w626_A_len_ok=0
[ "$_w626_started_s" -ne 0 ] && [ "$_w626_prologue" -gt "$_w626_need" ] && _w626_A_len_ok=1
echo "  половина 1 (длина): $([ "$_w626_A_len_ok" -eq 1 ] && echo ВЗЯТА || echo НЕ_ВЗЯТА)"

# ─────────────────────────────────────────────────────────────────────────────
# ТИХОЕ ОКНО ОБЪЁМА. Вход НЕ подаётся.
#
# №242, часть 2: t0 фиксируется ПОСЛЕДНИМ действием предоткрывающей
# последовательности. Каждый curl/journalctl этой последовательности — сам
# источник алертов (чтение /etc/passwd через NSS, чтение /var/log/journal);
# в 6.2.1 они стояли ПОСЛЕ фиксации t0 и потому падали внутрь окна
# (curl:3 journalctl:3 в вердикте архива). Закрытие окна такого дефекта не
# имело изначально — там t1 берётся первым; здесь открытие сделано
# симметрично закрытию.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.6.1/6.2.6.2/6.2.2.2/6.2.2.3/6.2.6.3/6.2.6.9: тихое окно ${W626_WINDOW}s ---"
_w626_drift_print() {
    echo "  дрейф[$1]: $(awk '/^ebpf_guard_drift_baseline_(profiles|learning_workloads|stuck_learning_workloads|learning_overdue_workloads|saturated_profiles|evictions_total|frozen_workloads|signature_cap_reached_total) /{printf "%s=%s ", $1, $2}' "$2")"
}
# ---- 6.2.6.13, первая половина (№260, item 7 постановки): observer_exclude
#      доказан выключенным ДО открытия окна, а не предполагается ----
# `/var/lib/ebpf-guard/observer-root-pid` — файл, которым волна 5.9a
# вооружает срез дерева измерителя В ЯДРЕ; волна 6.2.3 записала намерением
# «observer_exclude не вооружаем», но стража на это намерение не поставила
# (находка №260) — стоячий файл от прошлой сессии срезал бы дерево молча, и
# 6.2.6.3 показывал бы ноль не потому, что измеритель тих, а потому, что его
# не видно. Печать здесь — ДО ЛЮБОГО измерения, пока причина ещё читаема.
_w626_orpf=/var/lib/ebpf-guard/observer-root-pid
if [ -e "$_w626_orpf" ]; then
    echo "  6.2.6.13 (наблюдение): $_w626_orpf СУЩЕСТВУЕТ, содержимое: $(cat "$_w626_orpf" 2>/dev/null || echo 'нечитаемо')"
else
    echo "  6.2.6.13 (наблюдение): $_w626_orpf отсутствует"
fi
echo "  тишина перед открытием окна: ${W626_QUIET_LEAD}s (шум собственных curl'ов преflight'а уходит за границу t0)"
sleep "$W626_QUIET_LEAD"
_w626_metrics > "$W626_ART/metrics-window-start.txt"
# 6.2.9.F.2 (№295, item 2), симметрично границе закрытия ниже: цена чтения
# печатается на ОБЕИХ границах, а не только на t1 — до t0 ещё не открыт вход,
# так что здесь величина ожидаемо ближе к нулю, но это факт, а не допущение.
# Та же оговорка, что и на t1 (см. комментарий у metrics-window-end-cost.txt
# ниже): дельта — цена ВТОРОГО чтения, а не первого, и переносится на первое
# лишь по допущению равной стоимости; в арифметику НЕ входит.
_w626_metrics > "$W626_ART/metrics-window-start-cost.txt"
_w626_own_cost_start=$(( $(_w626_volume_all "$W626_ART/metrics-window-start-cost.txt") - $(_w626_volume_all "$W626_ART/metrics-window-start.txt") ))
echo "  6.2.9.F.2: цена ВТОРОГО чтения на границе открытия (t0) = ${_w626_own_cost_start} алертов (нижняя оценка цены первого, см. оговорку на границе закрытия)"
# 6.2.6.17 (№265, item 4 волны 6.2.6): ПОИМЁННЫЙ разрез базы дрейфа на
# границе окна. /metrics отдаёт только счётчики состояний, а вопрос «какие
# ИМЕННО 13 нагрузок стоят в stuck» по ним неразрешим — на нём и встал разбор
# архива 6.2.3. /debug/state.drift_baseline.workloads[] несёт (workload, comm,
# state, signatures, samples, saturated) на каждый профиль. Снимок берётся
# ВМЕСТЕ с метриками, до фиксации t0, — тем же curl'ом преflight'а, внутрь
# окна не попадает.
_w626_curl "$W626_API/debug/state" > "$W626_ART/debug-state-window-start.json" 2>/dev/null
_w626_jdrops0=$(_w626_journal_drops)
_w626_drift_print "открытие" "$W626_ART/metrics-window-start.txt"

# ---- 6.2.6.A, ПОЛОВИНА 2 (№257, item 6 постановки волны 6.2.5): потери за
#      ПРОЛОГ — И ФИНАЛЬНЫЙ КОНЪЮНКТИВНЫЙ ВЕРДИКТ (item 7 волны 6.2.6, №279).
#
# `_w626_real_drops` уже читает "потери без path_denylist" на любом файле
# среза; здесь он читается на снимке, который пайплайн взял СРАЗУ после
# старта агента (W626_PROLOGUE_METRICS, ДО 1800-секундного ожидания), а не
# на t0. Архив 6.2.3 потерял 1336 файловых событий именно в этом промежутке.
#
# ДО item 7 ненулевая дельта здесь печаталась как "ограничение полноты", но
# 6.2.6.A всё равно оставался ДОСТИГНУТО по одной лишь длине — архив 6.2.5
# потерял 1014 файловых событий (fileaccess/ringbuf_to_router) и вердикт
# этого не показал (находка №279). Постановка требует ДВЕ половины
# КОНЪЮНКТИВНО: обе половины вычислены НЕЗАВИСИМО (половина 1 — выше, до
# открытия окна; половина 2 — здесь) и печатаются ОБЕ, прежде чем выносится
# один сведённый вердикт — форма `elif`, которая проверяет вторую половину
# только в тени первой и раньше срока прерывает печать, здесь не используется
# (память elif-verdict-masks-independent-halves).
_w626_A_drops_measurable=0
_w626_A_drops_ok=0
_w626_dr_prologue="?"
if [ -n "${W626_PROLOGUE_METRICS:-}" ] && [ -s "${W626_PROLOGUE_METRICS:-}" ]; then
    _w626_A_drops_measurable=1
    _w626_dr_prologue_start=$(_w626_real_drops "$W626_PROLOGUE_METRICS")
    _w626_dr_prologue_end=$(_w626_real_drops "$W626_ART/metrics-window-start.txt")
    _w626_dr_prologue=$(( _w626_dr_prologue_end - _w626_dr_prologue_start ))
    [ "$_w626_dr_prologue" -le 0 ] && _w626_A_drops_ok=1
fi
echo "  половина 2 (потери за пролог [старт агента, t0], метрика без path_denylist): $_w626_dr_prologue — $([ "$_w626_A_drops_measurable" -eq 1 ] && ([ "$_w626_A_drops_ok" -eq 1 ] && echo ВЗЯТА || echo НЕ_ВЗЯТА) || echo НЕИЗМЕРИМА)"
if [ "$_w626_A_drops_measurable" -eq 1 ] && [ "$_w626_dr_prologue" -gt 0 ]; then
    echo "    разбивка потерь пролога по {collector,reason}:"
    w626_drops_by_reason "$W626_PROLOGUE_METRICS" "$W626_ART/metrics-window-start.txt" | sed 's/^/      /'
fi
if [ "$_w626_started_s" -eq 0 ]; then
    die "6.2.6.A НЕИЗМЕРИМ: время старта сервиса не прочитано — половина 1 (длина) недостижима, конъюнкция невозможна"
elif [ "$_w626_A_drops_measurable" -eq 0 ]; then
    die "6.2.6.A НЕИЗМЕРИМ: половина 1 (длина) $([ "$_w626_A_len_ok" -eq 1 ] && echo взята || echo не_взята) (пролог ${_w626_prologue}s, требуется > ${_w626_need}s), но снимок пролога (W626_PROLOGUE_METRICS) не передан пайплайном или пуст — половина 2 (потери) нечем читать, конъюнктивный вердикт по ДВУМ половинам невозможен (сторож №257 не работает)"
elif [ "$_w626_A_len_ok" -eq 1 ] && [ "$_w626_A_drops_ok" -eq 1 ]; then
    pass "6.2.6.A ДОСТИГНУТО: обе половины конъюнктивно — пролог ${_w626_prologue}s > ${_w626_need}s И потери за пролог = 0"
else
    die "6.2.6.A ПРОВАЛЕН: половина 1 (длина) $([ "$_w626_A_len_ok" -eq 1 ] && echo взята — "${_w626_prologue}s > ${_w626_need}s" || echo "не взята — ${_w626_prologue}s не длиннее ${_w626_need}s"); половина 2 (потери) $([ "$_w626_A_drops_ok" -eq 1 ] && echo взята — ноль || echo "не взята — $_w626_dr_prologue событий"). Конъюнкция требует ОБЕ; база дрейфа объявляется НИЖНЕЙ ОЦЕНКОЙ (находка №257/№279)"
fi

# ОСЕДАНИЕ ПЕРЕД ФИКСАЦИЕЙ t0 (открытый вопрос 16, вторая половина). Перенос
# t0 в конец последовательности (правка №242) убирает СЕКУНДЫ выполнения
# curl/journalctl из окна, но не убирает задержку конвейера: событие
# предоткрывающего curl'а проходит ring buffer → корреляцию → стор уже после
# того, как команда вернулась, и его метка времени может лечь ПОСЛЕ t0.
# Смок 06.09.2026 напечатал ровно это (curl:1 внутри окна при верном
# порядке). Пауза даёт конвейеру осесть; величина взята с запасом от
# наблюдённой латентности (91–183 мкс на событие, но стор пишется пачками).
# ---- №242, вторая правка (смок 07.09.2026): АТРИБУЦИЯ измерителя ----
# Список W626_INSTR_COMMS состоит из РОДОВЫХ имён (sh, grep, awk, date…), и
# смок этой волны показал, что по нему в «работу измерителя» попадает фон
# САМОЙ НОДЫ: 6.2.6.3 провалился на `grep /proc/cpuinfo`, который в 19:27:02
# запустил systemd-таймер `motd-news.service` (журнал таймеров сверен), пока
# измеритель спал на ФИФО и не делал ни одного execve. Верный признак «это
# наш процесс» — не имя, а ПРИНАДЛЕЖНОСТЬ ДЕРЕВУ: pid алерта лежит в цепочке
# предков этого скрипта либо среди её потомков. Набор снимается ДО t0 —
# внутри окна измеритель не порождает процессов вовсе (item 8, ФИФО), а
# значит новых своих pid'ов там взяться не может.
_w626_pids_file="$W626_ART/measurer-pids.txt"
{
    _w626_p=$$
    while [ -n "$_w626_p" ] && [ "$_w626_p" != "0" ] && [ "$_w626_p" != "1" ]; do
        echo "$_w626_p"
        _w626_p=$(awk '/^PPid:/{print $2}' "/proc/$_w626_p/status" 2>/dev/null)
    done
    ps -eo pid,ppid --no-headers 2>/dev/null | awk -v s="$$" '$2==s{print $1}'
} 2>/dev/null | sort -un > "$_w626_pids_file"
_w626_pids_json=$(awk '{printf "%s%s", (NR>1?",":"["), $1} END{printf "%s\n", (NR?"]":"[]")}' "$_w626_pids_file" 2>/dev/null)
[ -n "${_w626_pids_json:-}" ] || _w626_pids_json='[]'
# СТОРОЖ ЛОЖНОГО НУЛЯ к этому же правилу (память positive-control-needs-result-sentinel):
# принадлежность дереву не увидит процесс, который измеритель ПОРОДИЛ БЫ
# внутри окна (его pid в наборе отсутствует по определению). Приращение
# cutime+cstime собственной оболочки — прямое доказательство обратного: оно
# растёт только когда шелл пожал реального потомка. Читается встроенным
# `read` из /proc/self/stat — без execve и без форка внутри окна.
# ВАЖНО: значение возвращается ГЛОБАЛЬНОЙ переменной, а не через $( ). В
# подстановке команд шелл форкается, и /proc/self внутри неё — уже потомок,
# у которого cutime обнулён форком: сторож печатал бы 0 всегда.
_w626_reaped() {
    local _st
    _W626_REAPED=0
    read -r _st < /proc/self/stat 2>/dev/null || return 0
    # shellcheck disable=SC2086
    set -- ${_st#*") "}
    _W626_REAPED=$(( ${14:-0} + ${15:-0} ))
}

# ═════════════════════════════════════════════════════════════════════════════
# 6.2.9.F.8 (волна 6.2.9.F.1, 14.09.2026) — СОБЫТИЕ НОДЫ ФОРСИРУЕТСЯ ВНУТРЬ
# ОКНА, А НЕ ЖДЁТСЯ ОТ ФАЗЫ ТАЙМЕРА.
#
# ЗАЧЕМ. Величина куста с 11.09.2026 — цена ОДНОГО события ноды (6.2.9.F.7).
# Снять её можно только если событие в окне было, а оно приходит по таймеру:
# три прогона подряд на одной и той же ноде дали 28, 3 и 0 алертов за окно, и
# последний вынес НЕИЗМЕРИМ не из-за дефекта, а потому что узел молчал все
# 600 с (находка №299). Ждать везения дальше значит платить час стенда за
# треть шанса. Событие вводится в окно НАМЕРЕННО — тогда величина снимается
# ПО ПОСТРОЕНИЮ, и вердикт печатает, что она форсированная.
#
# ПОЧЕМУ ЭТО НЕ ЛОМАЕТ ЕДИНИЦУ. motd-news.service — штатный юнит САМОЙ ноды,
# тот же, чьё срабатывание дало 17-18 алертов на обоих снятых архивах и 0 у
# Falco (репер №298). Форсируется момент, а не содержание: дерево, его глубина
# и состав те же, что у естественного тика.
#
# ПОЧЕМУ ЧЕРЕЗ systemd-run, А НЕ ПРОСТЫМ ВЫЗОВОМ. Прямой `systemctl start`
# внутри окна — это execve ИЗМЕРИТЕЛЯ, и корнем дерева стал бы наш пайплайн:
# предикат «своё» (6.2.9.F.3/6.2.9.F.7) исключил бы всё событие из кандидатов,
# а цена вышла бы нулём — приборный ноль, неотличимый от продуктового.
# Транзиентный таймер ставится ДО t0 (здесь, снаружи окна), срабатывает уже
# внутри него, и порождённое дерево висит на systemd, а не на нас.
#
# МОМЕНТ ВЫБРАН С ЗАПАСОМ С ОБЕИХ СТОРОН: t0 + окно/3. Раньше — событие
# рискует лечь в осадку перед t0; позже — его алерты не успеют доехать до
# стора к моменту снимка на t1 (тот же лаг, что разбирает №295).
_W626_FORCE_UNIT="w626-force-node-event"
_W626_FORCE_TARGET="${W626_FORCE_TARGET:-motd-news.service}"
_W626_FORCE_AT=0
_W626_FORCE_SCHEDULED=0
if [ "${W626_FORCE_NODE_EVENT:-0}" = "1" ]; then
    _w626_force_off=$(( W626_OPEN_SETTLE + W626_WINDOW / 3 ))
    # ПРОГОН 14.09.2026 (19:23Z) ПОТЕРЯЛ НА ЭТОМ ГЛАВНУЮ ВЕЛИЧИНУ ВОЛНЫ.
    # `reset-failed` снимает только СБОЙНОЕ состояние, а транзиентный юнит с
    # RemainAfterExit=yes (сам же №302 его и потребовал) остаётся
    # `active (exited)` и мусорщиком НЕ собирается — вместе с ним живёт и его
    # .timer. Следующий `systemd-run --unit=<то же имя>` отказывает: «Unit
    # w626-force-node-event.timer already exists», и 6.2.9.F.8 выносит
    # НЕИЗМЕРИМ, то есть волна остаётся без форсированного события ноды.
    # Смок этого поймать НЕ МОГ по построению: первый запуск на чистом стенде
    # проходит всегда, отказывает ВТОРОЙ — а смок и был первым. Остаток
    # снимается ЯВНО (stop обоих юнитов) и, если он был, ПЕЧАТАЕТСЯ: молчаливая
    # уборка превратила бы повторение дефекта в невидимое.
    if systemctl cat "${_W626_FORCE_UNIT}.timer" >/dev/null 2>&1 || systemctl cat "${_W626_FORCE_UNIT}.service" >/dev/null 2>&1; then
        echo "  6.2.9.F.8: НАЙДЕН ОСТАТОК прошлого прогона ($_W626_FORCE_UNIT, .service=$(systemctl show -p ActiveState --value "${_W626_FORCE_UNIT}.service" 2>/dev/null) .timer=$(systemctl show -p ActiveState --value "${_W626_FORCE_UNIT}.timer" 2>/dev/null)) — снимается до постановки таймера"
    fi
    systemctl stop "${_W626_FORCE_UNIT}.timer" >/dev/null 2>&1
    systemctl stop "${_W626_FORCE_UNIT}.service" >/dev/null 2>&1
    systemctl reset-failed "${_W626_FORCE_UNIT}.timer" >/dev/null 2>&1
    systemctl reset-failed "${_W626_FORCE_UNIT}.service" >/dev/null 2>&1
    # AccuracySec=1s ОБЯЗАТЕЛЕН, и это не гигиена. У systemd-таймеров точность
    # по умолчанию — 1 МИНУТА: systemd сдвигает срабатывание в пределах окна
    # точности, чтобы группировать пробуждения. Смок 14.09.2026 напечатал ровно
    # это: таймер планировался на t0+20с, а юнит стартовал на t0+36с — при окне
    # 60 с событие едва не выпало наружу. На боевом окне 600 с смещение до
    # минуты безвредно, но оно превращает «событие введено по построению» в
    # «введено, если повезло с округлением» — то есть возвращает зависимость от
    # фазы, ради снятия которой блок и заведён.
    # RemainAfterExit=yes (№302, 14.09.2026). Без него транзиентный юнит
    # собирается мусорщиком сразу после выхода, и на закрытии окна
    # `systemctl show -p ExecMainPID` отдаёт пусто — pid МЕХАНИЗМА ВВЕДЕНИЯ
    # события становится неизвестен, а вместе с ним и его цена, и сторож
    # ложного PASS (победитель по цене не имеет права быть механизмом).
    # Свойство идёт на .service транзиентного запуска (--property), а не на
    # его .timer (--timer-property) — держать надо тот юнит, чей ExecMainPID
    # читается.
    # Отказ systemd-run печатается ПРИЧИНОЙ, а не одним словом: прогон
    # 14.09.2026 сообщил «НЕ поставил таймер» и не назвал, что именно сказал
    # systemd, — диагноз пришлось снимать со стенда руками уже после прогона.
    _w626_force_err=$(systemd-run --quiet --on-active="${_w626_force_off}s" --timer-property=AccuracySec=1s --property=RemainAfterExit=yes --unit="$_W626_FORCE_UNIT" /usr/bin/systemctl start "$_W626_FORCE_TARGET" 2>&1)
    if [ $? -eq 0 ]; then
        _W626_FORCE_SCHEDULED=1
        _W626_FORCE_AT=$(( $(_w626_epoch) + _w626_force_off ))
        # ФАКТ ВЗВЕДЕНИЯ, а не код возврата: `systemd-run` может вернуть 0, а
        # таймер не иметь следующего срабатывания вовсе. Тот же приём, что у
        # самого критерия (сначала ФАКТ, потом цена) и у починки 6.0.14.
        # СВОЙСТВО ИМЕННО МОНОТОННОЕ. `--on-active` ставит МОНОТОННЫЙ таймер, и
        # NextElapseUSecRealtime у него ПУСТ всегда — сторож, читающий его,
        # объявил бы «не взведён» на исправно взведённом таймере и сам снял бы
        # величину волны. Проверено на стенде 14.09.2026 до коммита:
        # Realtime='' при NextElapseUSecMonotonic='6h 7.241891s' и
        # `list-timers`, показывающем срабатывание через 4min 59s.
        _w626_force_next=$(systemctl show -p NextElapseUSecMonotonic --value "${_W626_FORCE_UNIT}.timer" 2>/dev/null)
        [ -z "${_w626_force_next:-}" ] && _w626_force_next=$(systemctl show -p NextElapseUSecRealtime --value "${_W626_FORCE_UNIT}.timer" 2>/dev/null)
        if [ -z "${_w626_force_next:-}" ] || [ "${_w626_force_next}" = "n/a" ]; then
            _W626_FORCE_SCHEDULED=0
            echo "  6.2.9.F.8: таймер поставлен, но следующее срабатывание НЕ ВЗВЕДЕНО (NextElapseUSecRealtime='${_w626_force_next:-пусто}') — событие в окно не вводится (вердикт ниже)"
        else
            echo "  6.2.9.F.8: событие ноды ($_W626_FORCE_TARGET) поставлено на $(_w626_utc "$_W626_FORCE_AT") — через ${_w626_force_off}с, то есть примерно t0 + $(( W626_WINDOW / 3 ))с. Таймер транзиентный ($_W626_FORCE_UNIT), взведён на «${_w626_force_next}», дерево повиснет на systemd, а не на измерителе"
        fi
    else
        echo "  6.2.9.F.8: systemd-run НЕ поставил таймер — событие в окно не вводится, величина снова зависит от фазы (вердикт ниже). Причина от systemd: ${_w626_force_err:-без сообщения}"
    fi
else
    echo "  6.2.9.F.8: форсирование выключено (W626_FORCE_NODE_EVENT не 1) — окно ловит то, что нода даст сама"
fi

sleep "$W626_OPEN_SETTLE"
_w626_t0=$(_w626_epoch)
echo "  окно открыто $(_w626_utc "$_w626_t0") — до закрытия НЕ ПОДАВАТЬ вход (память ebpf-guard-measurement-hygiene, п.2/п.5)"
# №258 (item 8 постановки 6.2.6): внешний `sleep` — это execve, то есть
# собственное событие измерителя внутри окна, которое в архиве 6.2.3 в
# одиночку провалило критерий доли измерителя (comm=sleep, единственный
# алерт измерителя в [t0,t1]). Замена — `read -t` НА ФИФО (W626_QUIET_FIFO,
# создана ДО t0, см. начало файла), а не на /dev/null: `read -t N </dev/null`
# возвращается СРАЗУ (открытие /dev/null на чтение даёт мгновенный EOF),
# проверено эмпирически перед правкой — «read -t с /dev/null», который
# называла сама находка №258 как пример, не ждёт вовсе и превратил бы
# 600-секундное окно в нулевое. ФИФО, открытая read+write на СВОЙ ЖЕ
# дескриптор, не даёт EOF (запись всегда возможна, раз писатель — сам
# процесс), и `read -u` блокируется РОВНО на таймаут — ни одного execve
# внутри окна, 0% CPU, exec/read — синтаксис шелла, не новый процесс.
# Съём сторожа — ВПЛОТНУЮ к ожиданию, ПОСЛЕ всех подстановок команд выше:
# `sleep` осадки и $( ) метки t0 сами суть пожатые потомки, и захват раньше
# приписал бы их тики окну (смок 07.09.2026 напечатал ровно этот ложный +1).
_w626_reaped; _w626_reaped0=$_W626_REAPED
if [ -p "$W626_QUIET_FIFO" ]; then
    exec 8<>"$W626_QUIET_FIFO"
    read -r -t "$W626_WINDOW" -u 8 _w626_qdummy
    exec 8<&-
else
    echo "  ФИФО ожидания недоступна ($W626_QUIET_FIFO не создана заранее) — откат на встроенный таймер SECONDS (по-прежнему без execve, но занимает CPU busy-wait'ом)"
    SECONDS=0
    while [ "$SECONDS" -lt "$W626_WINDOW" ]; do :; done
fi
_w626_reaped; _w626_reaped1=$_W626_REAPED
_w626_t1=$(_w626_epoch)
_w626_metrics > "$W626_ART/metrics-window-end.txt"
# 6.2.9.F.2 (№295, item 2): ЦЕНА ЧТЕНИЯ ИЗМЕРЯЕТСЯ, А НЕ ПРЕДПОЛАГАЕТСЯ.
# Сам curl, снимающий метрику РОВНО на t1, инструментирован тем же агентом —
# его execve/syscalls обрабатываются correlator'ом асинхронно и могут попасть
# В ЭТОТ ЖЕ снимок раньше, чем HTTP-ответ curl сериализован (архив
# collect-6.2.6-run2: 7 алертов curl/awk/cp/sleep за 160мс после t1, разъезд
# метрика↔стор anomaly_detection 9 vs 3).
#
# ЧТО РЕАЛЬНО ИЗМЕРЯЕТ ДЕЛЬТА. Штатный снимок (metrics-window-end.txt, тот,
# который читают ВСЕ остальные контроли и формула (а)) УЖЕ загрязнён СВОИМ
# СОБСТВЕННЫМ чтением к моменту, когда он снят, — и эта порция никак не
# видна в нём самом. Второй снимок берётся сразу вслед за первым; дельта
# между ними — это цена ВТОРОГО чтения (его собственные execve/curl,
# доехавшие до ЕГО снимка), а не цена первого. Перенос этой величины на
# первое чтение — оценка, а не измерение: она верна ТОЛЬКО при допущении, что
# оба чтения (одна и та же форма curl+awk, одно за другим) стоят одинаково.
# Отсюда и «нижняя оценка»: если первое чтение почему-то дороже второго
# (например, часть его контаминации ещё не долетела к моменту его же снимка
# и осела уже во ВТОРОМ), дельта её недооценивает.
#
# ПОЧЕМУ НЕЛЬЗЯ ВЫЧЕСТЬ. Чистого X (величины без какого-либо чтения) не
# существует ни в одном снимке — измерить можно только ЧТЕНИЕМ, а любое
# чтение стоит. Величина печатается (критерий 6.2.9.F.2 ниже), но не
# участвует в арифметике формулы (а): вычитание задним числом было бы той же
# ошибкой, что и подгонка порога под желаемый исход.
_w626_metrics > "$W626_ART/metrics-window-end-cost.txt"
_w626_own_cost_end=$(( $(_w626_volume_all "$W626_ART/metrics-window-end-cost.txt") - $(_w626_volume_all "$W626_ART/metrics-window-end.txt") ))
echo "  6.2.9.F.2: цена ВТОРОГО чтения на границе закрытия (t1) = ${_w626_own_cost_end} алертов — нижняя оценка цены ПЕРВОГО (штатного) снимка, верна лишь при допущении, что оба чтения стоят одинаково; в формулу (а) НЕ входит, только печатается"
_w626_curl "$W626_API/debug/state" > "$W626_ART/debug-state-window-end.json" 2>/dev/null
_w626_jdrops1=$(_w626_journal_drops)
_w626_drift_print "закрытие" "$W626_ART/metrics-window-end.txt"
_w626_alerts > "$W626_ART/alerts-window-end.json"
# №240/открытый вопрос 14: границы окна выносятся наружу файлом-мостом —
# пайплайну нечем иначе проверить, что журнал ПОКРЫВАЕТ окно (критерий
# 6.2.2.4), потому что эпохи считаются здесь и наружу не возвращаются.
printf 't0=%s\nt1=%s\n' "$_w626_t0" "$_w626_t1" > "$W626_ART/window-epoch.txt"

# ═════════════════════════════════════════════════════════════════════════════
# 6.2.6.19 (№281, item 1 приборная половина) — РАЗЪЕЗД МЕТРИКИ И СТОРА
# НАПЕЧАТАН, И `drain` НАЗВАН ЧИСЛОМ.
#
# ЧТО ЛЕЧИТ. Снимок стора берётся РОВНО в t1, но запись алерта в стор
# асинхронна относительно инкремента метрики: часть алертов окна доезжает
# ПОСЛЕ t1 и в снимок не попадает. Прогон 6.2.5 показал разъезд 24 строки
# стора против 25 по метрике — маленький, но он означает, что КАЖДЫЙ сторовый
# контроль читает недописанный стор, и любой его ноль ничего не доказывает,
# пока величина отставания не названа.
#
# КАК ИЗМЕРЯЕТСЯ. `drain` подбирается ЭМПИРИЧЕСКИ, а не назначается: снимки
# повторяются с шагом W626_DRAIN_STEP, пока число строк В ГРАНИЦАХ [t0,t1]
# не перестанет расти два раза подряд. Назначить его числом заранее значило
# бы угадать ровно ту величину, ради которой этот критерий и существует.
#
# ПОЧЕМУ СНИМОК ПОСЛЕ СЛИВА СТАНОВИТСЯ ОСНОВНЫМ. Все сторовые контроли
# фильтруют по [t0,t1] сами, поэтому более поздний снимок для них — строгое
# надмножество: он не добавляет ничего вне окна, а внутри окна добавляет то,
# что раньше терялось. Снимок ровно на t1 сохраняется отдельным файлом —
# без него разъезд нечем было бы предъявить.
#
# ПОРОГ НЕ НАЗНАЧАЕТСЯ (5.9.6). Невозможность назвать drain = НЕИЗМЕРИМ.
# ═════════════════════════════════════════════════════════════════════════════
echo "--- 6.2.6.19: разъезд метрики и стора, drain подбирается снимками (№281) ---"
W626_DRAIN_STEP="${W626_DRAIN_STEP:-$([ "$W626_SMOKE" = "1" ] && echo 5 || echo 10)}"
W626_DRAIN_MAX="${W626_DRAIN_MAX:-$([ "$W626_SMOKE" = "1" ] && echo 20 || echo 60)}"
# НАЙДЕНО №293 (разбор архива collect-6.2.6, 10.09.2026): `sub(...)|
# fromdateiso8601` отрезал дробную часть ДО парсинга, поэтому весь
# промежуток [t1.000, t1.999] читался как «= t1» и проходил `<= t1`.
# На архиве это дало ложное drain=10с — 6 строк, которые «доехали после
# слива», были на деле собственными алертами КОНТРОЛЯ на t1+0,16…0,25с
# (curl/cp/cut/jq читают метрики контроля сразу после открытия окна) и
# были В ОКНЕ уже на снимке РОВНО на t1 при точном сравнении. `w626ts`
# сохраняет дробную часть как float-эпоху, так что `<= $t1` (целое)
# отбрасывает всё, что позже t1 хоть на миллисекунду.
_w626_store_in_window() { # $1=файл снимка стора → число строк в границах [t0,t1]
    jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" \
       'def w626ts: (.timestamp | capture("^(?<i>[^.]+)(\\.(?<f>[0-9]+))?Z$")) as $c
          | ($c.i + "Z" | fromdateiso8601) + (($c.f // "0") | ("0." + .) | tonumber);
        [.[]|select((w626ts >= $t0) and (w626ts <= $t1))]|length' \
       "$1" 2>/dev/null || echo 0
}
cp "$W626_ART/alerts-window-end.json" "$W626_ART/alerts-window-end-t1.json" 2>/dev/null
_w626_drain_n0=$(_w626_store_in_window "$W626_ART/alerts-window-end-t1.json")
_w626_drain=""; _w626_drain_waited=0; _w626_drain_prev=${_w626_drain_n0:-0}; _w626_drain_stable=0
while [ "$_w626_drain_waited" -lt "$W626_DRAIN_MAX" ]; do
    sleep "$W626_DRAIN_STEP"
    _w626_drain_waited=$(( _w626_drain_waited + W626_DRAIN_STEP ))
    # Снимок берётся во ВРЕМЕННЫЙ файл и подменяет рабочий только если он не
    # ХУЖЕ предыдущего. Иначе один неудачный curl (агент перезапущен, таймаут)
    # обнулил бы alerts-window-end.json, все сторовые контроли прочитали бы
    # пустоту, а drain «стабилизировался» бы на нуле — ложный PASS этого
    # критерия ценой всех остальных.
    _w626_alerts > "$W626_ART/alerts-drain.json"
    _w626_drain_now=$(_w626_store_in_window "$W626_ART/alerts-drain.json")
    if [ "${_w626_drain_now:-0}" -lt "${_w626_drain_prev:-0}" ]; then
        echo "    снимок +${_w626_drain_waited}с ОТБРОШЕН: строк в окне ${_w626_drain_now} < предыдущих ${_w626_drain_prev} — стор так не сокращается, снимок битый (агент недоступен?)"
        continue
    fi
    mv -f "$W626_ART/alerts-drain.json" "$W626_ART/alerts-window-end.json"
    echo "    снимок +${_w626_drain_waited}с: строк стора в границах окна = ${_w626_drain_now} (было ${_w626_drain_prev})"
    if [ "${_w626_drain_now:-0}" -eq "${_w626_drain_prev:-0}" ]; then
        _w626_drain_stable=$(( _w626_drain_stable + 1 ))
        # drain — момент, когда рост ПРЕКРАТИЛСЯ, то есть предыдущий шаг.
        [ -z "$_w626_drain" ] && _w626_drain=$(( _w626_drain_waited - W626_DRAIN_STEP ))
        [ "$_w626_drain_stable" -ge 2 ] && break
    else
        _w626_drain_stable=0; _w626_drain=""
    fi
    _w626_drain_prev=$_w626_drain_now
done
_w626_drain_n1=${_w626_drain_prev:-0}
echo "  строк стора в границах окна: на t1 = ${_w626_drain_n0:-0}, после слива = ${_w626_drain_n1}; drain = ${_w626_drain:-НЕ_НАЗВАН}с (шаг ${W626_DRAIN_STEP}с, предел ${W626_DRAIN_MAX}с)"
echo "  дальше ВСЕ сторовые контроли читают снимок ПОСЛЕ слива (alerts-window-end.json); снимок ровно на t1 сохранён как alerts-window-end-t1.json"

# ---- построчный разъезд по rule_id: метрика против стора ----
_w626_store_by_rule=$(jq -r --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" \
    'def w626ts: (.timestamp | capture("^(?<i>[^.]+)(\\.(?<f>[0-9]+))?Z$")) as $c
       | ($c.i + "Z" | fromdateiso8601) + (($c.f // "0") | ("0." + .) | tonumber);
     [.[]|select((w626ts >= $t0) and (w626ts <= $t1))]
     | group_by(.rule_id)|map("\(.[0].rule_id) \(length)")|.[]' "$W626_ART/alerts-window-end.json" 2>/dev/null | sort)
if [ "$W626_LIB_OK" -eq 1 ]; then
    _w626_metric_by_rule=$(w626_volume_by_rule "$W626_ART/metrics-window-start.txt" "$W626_ART/metrics-window-end.txt" | sort)
else
    _w626_metric_by_rule=""
fi
echo "  построчно (rule_id: метрика | стор | разъезд). Знак разъезда осмыслен САМ ПО СЕБЕ:"
echo "    метрика > стора — ТРИ причины, проверяются в этом порядке (№295, item 2 волны 6.2.9.F): (0) метрика включает работу ЧИТАТЕЛЯ — единственная СИСТЕМАТИЧЕСКАЯ причина, curl/jq самого контроля создают алерты внутри собственного снимка; оценка = ${_w626_own_cost_end:-?} алертов (6.2.9.F.2, граница закрытия — цена ВТОРОГО чтения, перенесённая на первое по допущению равной стоимости, только печатается, из разъезда не вычитается); (1) severity ниже store.min_severity (законно); (2) стор всё ещё отстаёт;"
echo "    стор > метрики — строка окна записана агентом ДО открытия окна по метрике (граница снимка), находка."
printf '%s\n' "$_w626_metric_by_rule" > "$W626_ART/w626-metric-by-rule.txt"
printf '%s\n' "$_w626_store_by_rule" > "$W626_ART/w626-store-by-rule.txt"
_w626_split=$(awk '
    FILENAME == ARGV[1] && NF == 2 { m[$1] = $2; seen[$1] = 1 }
    FILENAME == ARGV[2] && NF == 2 { s[$1] = $2; seen[$1] = 1 }
    END { for (r in seen) printf "%s метрика=%d стор=%d разъезд=%+d\n", r, m[r]+0, s[r]+0, (s[r]+0) - (m[r]+0) }
' "$W626_ART/w626-metric-by-rule.txt" "$W626_ART/w626-store-by-rule.txt" | sort)
printf '%s\n' "$_w626_split" | sed 's/^/    /'
printf '%s\n' "$_w626_split" > "$W626_ART/metric-store-split.txt"
_w626_split_sum=$(printf '%s\n' "$_w626_split" | sed 's/.*разъезд=//' | awk '{s+=($1<0?-$1:$1)} END{printf "%d", s+0}')

if [ -z "${_w626_drain:-}" ]; then
    die "6.2.6.19 НЕИЗМЕРИМ (№281): за ${W626_DRAIN_MAX}с стор НЕ ПЕРЕСТАЛ приносить новые строки за окно (${_w626_drain_n0:-0} → ${_w626_drain_n1}) — drain назвать нечем, и ноль ЛЮБОГО сторового контроля этого прогона ничего не доказывает: он прочитан на недописанном сторе"
else
    pass "6.2.6.19 ИЗМЕРЕНО (№281, порог не назначается): drain = ${_w626_drain}с (снимок на t1 недосчитывал $(( _w626_drain_n1 - ${_w626_drain_n0:-0} )) строк окна из ${_w626_drain_n1}); суммарный модуль разъезда метрика↔стор по всем rule_id = ${_w626_split_sum}, построчно выше и в metric-store-split.txt"
fi

# ═════════════════════════════════════════════════════════════════════════════
# 6.2.9.F.2 (№295, item 2 волны 6.2.9.F) — ГЕЙТ НЕИЗМЕРИМ, ЕСЛИ ЦЕНА ЧТЕНИЯ
# СРАВНИМА С ЗАПАСОМ. Печатается ТРЕТЬЕЙ величиной подряд рядом с ценой ноды:
# 90/ч при пороге 100/ч и цене чтения 6 не есть «взят» — снимок, который сам
# добавляет к измеряемой величине, не вправе решать, взят ли гейт, если его
# собственная добавка сопоставима с оставшимся запасом до порога.
#
# ЧТО ЗДЕСЬ ИМЕННО СРАВНИВАЕТСЯ. `_w626_own_cost_end` — цена ВТОРОГО чтения
# (см. комментарий у его вычисления выше), перенесённая на ПЕРВОЕ (штатное)
# чтение по допущению, что оба чтения стоят одинаково. Это ОЦЕНКА, не
# измерение первого чтения впрямую — измерить его нечем, кроме как ещё одним
# чтением, которое стоит ту же цену. Отсюда критерий сравнивает НЕИЗМЕРИМОСТЬ
# по оценке, а не по факту, и остаётся строго ПЕЧАТЬЮ величины: она нигде не
# вычитается из формулы (а) (см. `_w626_vol`/`_w626_vol_hour` — оба считаются
# только по дельте штатных снимков, без участия `_w626_own_cost_*`), и не
# войдёт в неё, пока item 3 (атрибуция по дереву) не даст способ отличить
# алерты измерителя от алертов ноды напрямую, а не оценкой по симметрии.
# ═════════════════════════════════════════════════════════════════════════════
echo "--- 6.2.9.F.2: цена чтения против запаса гейта (№295) ---"
_w626_margin_abs=$(awk -v m="$W626_GATE_MARGIN" -v w="$W626_WINDOW" 'BEGIN{printf "%d", m*w/3600.0}')
echo "  цена чтения (оценка по допущению равной стоимости обоих чтений): открытие=${_w626_own_cost_start:-0}, закрытие=${_w626_own_cost_end:-0} алертов; запас до порога = ${_w626_margin_abs} алертов за окно ${W626_WINDOW}с"
if [ "${_w626_own_cost_end:-0}" -ge "$_w626_margin_abs" ]; then
    die "6.2.9.F.2 НЕИЗМЕРИМ (№295): оценка цены снятия величины на границе закрытия (${_w626_own_cost_end:-0}) сравнима с запасом гейта (${_w626_margin_abs}) или превосходит его — вердикт объёма тихого окна (метка критерия объёма, см. строку выше) не вправе объявляться взятым или проваленным на этом снимке, пока item 3 (атрибуция по дереву) не разделил чужую работу и работу ноды. Величина ТОЛЬКО печатается и нигде не вычитается из формулы (а)"
else
    pass "6.2.9.F.2 ИЗМЕРЕНО (№295, порог величине не назначается): оценка цены чтения (${_w626_own_cost_end:-0}) меньше запаса гейта (${_w626_margin_abs}) — сама по себе не делает вердикт объёма тихого окна неизмеримым, но остаётся систематической нижней оценкой (не нулём) и оценкой (не измерением: перенесена со второго чтения на первое по допущению равной стоимости). Величина ТОЛЬКО печатается и нигде не вычитается из формулы (а)"
fi

# ---- 6.2.6.13, вторая половина (№260): серия печатается ЯВНЫМ ЧИСЛОМ на
#      обеих границах окна, а не пропускается ----
# `ebpf_guard_events_excluded_total{reason="observer_tree"}` теперь
# пре-регистрируется движком безусловно (internal/correlator/engine.go,
# item 7 офлайн-правки волны 6.2.6) — серия читается как 0, если и правда
# ничего не исключалось, а не отсутствует. Отсутствие серии в снимке при
# этом ОСТАЁТСЯ отдельным сигналом: значит агент собран без этой правки.
_w626_obs_metric() { # $1=файл среза
    awk '/^ebpf_guard_events_excluded_total\{.*reason="observer_tree"/{print $NF; f=1} END{if(!f) print ""}' "$1" 2>/dev/null
}
_w626_obs0=$(_w626_obs_metric "$W626_ART/metrics-window-start.txt")
_w626_obs1=$(_w626_obs_metric "$W626_ART/metrics-window-end.txt")
echo "  6.2.6.13: ebpf_guard_events_excluded_total{reason=\"observer_tree\"} открытие=${_w626_obs0:-ОТСУТСТВУЕТ} закрытие=${_w626_obs1:-ОТСУТСТВУЕТ}"
if [ -z "${_w626_obs0:-}" ] || [ -z "${_w626_obs1:-}" ]; then
    die "6.2.6.13 НЕИЗМЕРИМ: серия observer_tree отсутствует хотя бы на одной границе окна — агент собран без пре-регистрации (item 7 правки не задеплоены), отсутствие среза дерева измерителя доказать нечем"
else
    _w626_obs_delta=$(( _w626_obs1 - _w626_obs0 ))
    if [ "$_w626_obs_delta" -gt 0 ]; then
        die "6.2.6.13 ПРОВАЛЕН: observer_tree исключил $_w626_obs_delta событий за окно — дерево измерителя резалось В ЯДРЕ, прогон НЕИЗМЕРИМ (часть величины 6.2.6.1 уехала вместе с исключением, находка №260)"
    else
        pass "6.2.6.13 ДОСТИГНУТО: observer_tree за окно = 0 — фильтр либо выключен, либо не резал ничего, и это доказано числом, а не отсутствием серии"
    fi
fi

# ---- 6.2.6.0, вторая половина: потери событий за окно (№222) ----
_w626_dr0=$(_w626_real_drops "$W626_ART/metrics-window-start.txt")
_w626_dr1=$(_w626_real_drops "$W626_ART/metrics-window-end.txt")
_w626_dr=$(( _w626_dr1 - _w626_dr0 ))
_w626_jdr=$(( ${_w626_jdrops1:-0} - ${_w626_jdrops0:-0} ))
echo "  потери событий за окно: метрика (без path_denylist) = $_w626_dr; журнал bulk_dropped = $_w626_jdr"
if [ "$_w626_dr" -gt 0 ] || [ "$_w626_jdr" -gt 0 ]; then
    die "6.2.6.0 ПРОВАЛЕН (половина «потери»): за окно потеряно событий — метрика $_w626_dr, журнал $_w626_jdr. Величина 6.2.6.1 срезана ПОТЕРЕЙ, а не только лимитером (находка №222). Окно НЕИЗМЕРИМО"
elif [ "$_w626_jdr" -eq 0 ] && [ "$_w626_dr" -eq 0 ]; then
    pass "6.2.6.0 ДОСТИГНУТО (половина «потери»): за окно ни метрика, ни журнал не показали потерь"
fi
if { [ "$_w626_jdr" -gt 0 ] && [ "$_w626_dr" -eq 0 ]; } || { [ "$_w626_dr" -gt 0 ] && [ "$_w626_jdr" -eq 0 ]; }; then
    die "6.2.6.0 ПРОВАЛЕН (сверка прибора): журнал говорит $_w626_jdr потерь, метрика — $_w626_dr. Потеря видимости молчалива в метриках (второй слой находки №222)"
fi

# ---- 6.2.6.1: объём ПРЯМОЙ ДЕЛЬТОЙ ДВУХ МЕТРИК, обе формулы (№227/№232),
#      плюс ВСЕ ЧЕТЫРЕ СЛОЯ и величина (в) — решение 1, №248 ----
_w626_alerts_total_d=$(_w626_metric_sum ebpf_guard_alerts_total "" "$W626_ART/metrics-window-end.txt")
_w626_alerts_total_s=$(_w626_metric_sum ebpf_guard_alerts_total "" "$W626_ART/metrics-window-start.txt")
_w626_filtered_d=$(_w626_metric_sum ebpf_guard_alerts_filtered_total "" "$W626_ART/metrics-window-end.txt")
_w626_filtered_s=$(_w626_metric_sum ebpf_guard_alerts_filtered_total "" "$W626_ART/metrics-window-start.txt")
_w626_layer_total=$(( _w626_alerts_total_d - _w626_alerts_total_s ))
_w626_layer_filtered=$(( _w626_filtered_d - _w626_filtered_s ))
_w626_vol_all=$(( $(_w626_volume_all "$W626_ART/metrics-window-end.txt") - $(_w626_volume_all "$W626_ART/metrics-window-start.txt") ))
_w626_vol_ni=$(( $(_w626_volume_noinfo "$W626_ART/metrics-window-end.txt") - $(_w626_volume_noinfo "$W626_ART/metrics-window-start.txt") ))
_w626_rl0=$(_w626_ratelimited "" "$W626_ART/metrics-window-start.txt")
_w626_rl1=$(_w626_ratelimited "" "$W626_ART/metrics-window-end.txt")
_w626_rl=$(( _w626_rl1 - _w626_rl0 ))
# Четвёртый слой (решение 3): дедуп остаётся механизмом ДОСТАВКИ, в величину
# гейта (а) не входит, но обязателен в (в) — числа №248 показали, что это
# самая устойчивая величина всего прогона (5702/5696 на двух окнах).
_w626_dd0=$(_w626_metric_sum ebpf_guard_alerts_dedup_dropped_total "" "$W626_ART/metrics-window-start.txt")
_w626_dd1=$(_w626_metric_sum ebpf_guard_alerts_dedup_dropped_total "" "$W626_ART/metrics-window-end.txt")
_w626_dd=$(( _w626_dd1 - _w626_dd0 ))
_w626_hour() { awk -v n="$1" -v w="$W626_WINDOW" 'BEGIN{printf "%.0f", n*3600.0/w}'; }
_w626_all_hour=$(_w626_hour "$_w626_vol_all")
_w626_ni_hour=$(_w626_hour "$_w626_vol_ni")
echo "  слой 1 alerts_total (Δ):             $_w626_layer_total"
echo "  слой 2 alerts_filtered_total (Δ):    $_w626_layer_filtered"
echo "  слой 3 alerts_ratelimited_by_rule (Δ): $_w626_rl"
echo "  слой 4 alerts_dedup_dropped (Δ):     $_w626_dd"
echo "  объём ВСЁ, формула (а) = слой1+слой2:        $_w626_vol_all → $_w626_all_hour/ч"
echo "  объём БЕЗ info, формула (б, ОТВЕРГНУТА реш.1): $_w626_vol_ni → $_w626_ni_hour/ч"
echo "  цена решения №232 числом:      $(( _w626_vol_all - _w626_vol_ni )) алертов severity=info за окно"
if [ "$W626_GATE_FORMULA" = "noinfo" ]; then
    _w626_vol=$_w626_vol_ni; _w626_vol_hour=$_w626_ni_hour
else
    _w626_vol=$_w626_vol_all; _w626_vol_hour=$_w626_all_hour
fi
_w626_true_hour=$(_w626_hour "$(( _w626_vol + _w626_rl ))")
# Величина (в) — решение 1: сумма ВСЕХ четырёх слоёв, порог НЕ назначается
# (правило 5.9.6 — впервые измеренной величине порог не даётся). Печатается
# ОБЯЗАТЕЛЬНО и всегда, вне зависимости от того, взят ли критерий 6.2.6.1.
_w626_v_total=$(( _w626_layer_total + _w626_layer_filtered + _w626_rl + _w626_dd ))
_w626_v_hour=$(_w626_hour "$_w626_v_total")
echo "  ← ВЕЛИЧИНА КРИТЕРИЯ 6.2.6.1 (формула $W626_GATE_FORMULA): $_w626_vol_hour/ч при гейте ${W626_GATE}/ч"
echo "  срез лимитера за окно (alerts_ratelimited_by_rule_total): $_w626_rl"
echo "  нижняя оценка РЕАЛЬНОГО числа срабатываний (а+срез лимитера): $(( _w626_vol + _w626_rl )) → $_w626_true_hour/ч"
echo "  ← ВЕЛИЧИНА (в) [решение 1, №248, БЕЗ ПОРОГА]: слой1+слой2+слой3+слой4 = $_w626_v_total → ${_w626_v_hour}/ч"

# ---- 6.2.2.2: список срезанных правил ПО МЕТРИКЕ (№238) ----
echo "--- 6.2.2.2: правила со срезом лимитера за окно (по метрике, не по стору) ---"
_w626_rl_list=""
if [ "$W626_LIB_OK" -eq 1 ]; then
    _w626_rl_list=$(w626_ratelimited_by_rule "$W626_ART/metrics-window-start.txt" "$W626_ART/metrics-window-end.txt")
    printf '%s\n' "${_w626_rl_list:-  (ни одно правило не срезано)}" | sed 's/^/    /'
    printf '%s\n' "$_w626_rl_list" > "$W626_ART/ratelimited-by-rule.txt"
fi
_w626_rl_n=$(printf '%s' "$_w626_rl_list" | grep -c . )
if [ "$W626_LIB_OK" -ne 1 ]; then
    die "6.2.2.2 НЕИЗМЕРИМ: библиотека не подключилась (см. преflight)"
elif [ "$_w626_rl" -gt 0 ] && [ "${_w626_rl_n:-0}" -eq 0 ]; then
    die "6.2.2.2 ПРОВАЛЕН (дефект ИЗМЕРИТЕЛЯ, не продукта): сумма среза лимитера за окно = $_w626_rl, а поимённый список ПУСТ. Это ровно находка №238: «нет срезанных» при ненулевом срезе означает, что цикл не видел правил, а не что их нет"
elif [ "$_w626_rl" -eq 0 ] && [ "${_w626_rl_n:-0}" -eq 0 ]; then
    pass "6.2.2.2 ДОСТИГНУТО: срез лимитера за окно нулевой, и поимённый список пуст согласованно (сумма 0 = список пуст)"
else
    pass "6.2.2.2 ДОСТИГНУТО: $_w626_rl_n правил со срезом напечатаны поимённо при сумме среза $_w626_rl (6.2.1 печатала «нет» при срезе +530)"
fi

# ---- 6.2.2.3: разбивка величины покрывает её саму (№239) ----
echo "--- 6.2.2.3: разбивка величины по правилам (по метрике) ---"
if [ "$W626_LIB_OK" -eq 1 ]; then
    w626_volume_by_rule "$W626_ART/metrics-window-start.txt" "$W626_ART/metrics-window-end.txt" > "$W626_ART/volume-by-rule.txt"
    head -20 "$W626_ART/volume-by-rule.txt" | sed 's/^/    /'
    _w626_sum=$(awk '{s+=$2} END{printf "%d", s+0}' "$W626_ART/volume-by-rule.txt")
    echo "  прямая дельта объёма (формула all): $_w626_vol_all; сумма разбивки: $_w626_sum"
    if [ "$_w626_vol_all" -le 0 ]; then
        die "6.2.2.3 НЕИЗМЕРИМ: прямая дельта объёма за окно не положительна ($_w626_vol_all) — покрытие считать не от чего"
    else
        _w626_cov=$(awk -v s="$_w626_sum" -v v="$_w626_vol_all" 'BEGIN{printf "%.1f", 100.0*s/v}')
        echo "  покрытие разбивки: ${_w626_cov}% (требуется ≥ 95%; версия 6.2.1 давала 4.3%)"
        if awk -v s="$_w626_sum" -v v="$_w626_vol_all" 'BEGIN{exit !(s >= 0.95*v)}'; then
            pass "6.2.2.3 ДОСТИГНУТО: разбивка покрывает ${_w626_cov}% величины — это законный вход для сужения"
        else
            die "6.2.2.3 ПРОВАЛЕН: разбивка покрывает лишь ${_w626_cov}% величины ($_w626_sum из $_w626_vol_all). Сужение по такой разбивке — работа вслепую (находка №239), правки на её основании запрещены"
        fi
    fi
else
    die "6.2.2.3 НЕИЗМЕРИМ: библиотека не подключилась"
fi

# Сторовая разбивка по comm — СПРАВОЧНО. Ни у alerts_total, ни у
# alerts_filtered_total нет лейбла comm, метрикой эту ось не восстановить.
_w626_new=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" --arg actors "$W626_NODE_ACTORS" '
    [ .[] | select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t0) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $t1))
      | select(((.enrichment.namespace // "") != "") or ((.comm) as $c | ($actors|split(" "))|index($c))) ]
    ' "$W626_ART/alerts-window-end.json" 2>/dev/null)
echo "  (справочно, сторовый счёт нодовых алертов окна: $(echo "${_w626_new:-[]}" | jq 'length' 2>/dev/null) — вердикта не выносит, находки №227/№239)"
# ПРАВКА item 1 (№282). Прежняя редакция этой строки говорила «метрикой эта
# ось не восстановима» — до волны 6.2.6 так и было, и потому единственным
# источником comm оставался стор, слепой к severity=info и отстающий от
# метрики ([[narrowing-input-must-be-metric-not-store]]). Счётчик
# alert_volume_by_source_total{rule_id, comm} снял это ограничение: сторовая
# разбивка остаётся справочной, метрическая — вход сужения.
echo "  разбивка по comm (СТОР, справочно — слеп к severity=info по построению):"
echo "${_w626_new:-[]}" | jq -r 'group_by(.comm)|map({c:.[0].comm,n:length})|sort_by(-.n)[]|"    \(.c): \(.n)"' 2>/dev/null | head -15

# ---------------------------------------------------------------------------
# 6.2.6.2: РАЗБИВКА РАНЖИРУЕТ ПО (в), А НЕ ПО ОСТАТКУ ПОСЛЕ ЛИМИТЕРА (№248).
#
# 6.2.2.3 выше ранжирует то, что ДОЕХАЛО до alerts_total/alerts_filtered_total
# (формула (а)) — и это подменяет собой настоящую верхушку шума, потому что
# правила, упёршиеся в лимитер (10/60с) и дедуп, показывают в (а) только
# ОСТАТОК. w626_value_v_by_rule (wave6.2.6-metrics-lib.sh) складывает ТРИ
# компонента на каждый rule_id — (а)-разбивку, срез лимитера, срез дедупа —
# и ранжирует по их сумме. Офлайн-сторож (--self-test на ОБОИХ архивах
# 6.2.2) проверяет, что первыми встают sigma_failed_login_syscall_daemon и
# rootkit_pam_module_added_daemon, а не c2_periodic_beacon_pattern.
# ---------------------------------------------------------------------------
echo "--- 6.2.6.2: разбивка по (в) — полная сумма совпадений правил (№248) ---"
if [ "$W626_LIB_OK" -eq 1 ]; then
    w626_value_v_by_rule "$W626_ART/metrics-window-start.txt" "$W626_ART/metrics-window-end.txt" > "$W626_ART/value-v-by-rule.txt"
    head -20 "$W626_ART/value-v-by-rule.txt" | sed 's/^/    /'
    _w626_v_sum=$(awk '{s+=$2} END{printf "%d", s+0}' "$W626_ART/value-v-by-rule.txt")
    _w626_v_top=$(head -1 "$W626_ART/value-v-by-rule.txt" | awk '{print $1}')
    echo "  прямая величина (в) за окно: $_w626_v_total; сумма разбивки по (в): $_w626_v_sum; вершина: ${_w626_v_top:-нет}"
    if [ "$_w626_v_total" -le 0 ]; then
        die "6.2.6.2 НЕИЗМЕРИМ: величина (в) за окно не положительна ($_w626_v_total) — ранжировать нечего"
    else
        _w626_v_cov=$(awk -v s="$_w626_v_sum" -v v="$_w626_v_total" 'BEGIN{printf "%.1f", 100.0*s/v}')
        echo "  покрытие разбивки по (в): ${_w626_v_cov}% (требуется ≥ 95%)"
        # ---- ОСЬ comm ПО МЕТРИКЕ (item 1, №282) — вторая половина критерия ----
        # Постановка: «Пустая ось comm при непустой разбивке = item 1 не
        # задеплоен = волна НЕИЗМЕРИМА в своей главной части». Именно поэтому
        # пустота здесь судится, а не печатается справочно: без оси comm
        # остаток гейта сужать нечем, и весь item 6 остаётся догадкой по
        # прологовым именам (открытый вопрос 13).
        echo "  разбивка по {rule_id, comm} ПО МЕТРИКЕ (item 1, оба яруса severity — стор к info слеп):"
        w626_volume_by_source "$W626_ART/metrics-window-start.txt" "$W626_ART/metrics-window-end.txt" > "$W626_ART/volume-by-source.txt"
        head -20 "$W626_ART/volume-by-source.txt" | sed 's/^/    /'
        _w626_vbs_rows=$(grep -c . "$W626_ART/volume-by-source.txt" || true)
        # Переполнение лимитера кардинальности — открытый вопрос 1: число
        # 10000 скопировано с alertsCardinalityLimiter и на реальной
        # кардинальности стенда не проверялось. Ненулевой счётчик означает,
        # что часть оси схлопнута в comm="other" и разбивка НЕ поимённа.
        _w626_vbs_ovf=$(( $(_w626_metric_sum ebpf_guard_alert_volume_by_source_overflow_total "" "$W626_ART/metrics-window-end.txt") \
                        - $(_w626_metric_sum ebpf_guard_alert_volume_by_source_overflow_total "" "$W626_ART/metrics-window-start.txt") ))
        echo "  строк оси comm: ${_w626_vbs_rows}; переполнений лимитера кардинальности за окно: ${_w626_vbs_ovf} (открытый вопрос 1: ненулевое = предел 10000 мал, часть оси ушла в comm=\"other\")"
        # НАЗВАННЫЙ ОСТАТОК (открытый вопрос 14). Два info-правила устроены как
        # список comm + nr==59: ось сужения СОВПАДАЕТ с условием, исключение по
        # ней есть немой обход ([[comm-not-in-is-a-mute-bypass]]), понижение
        # severity объём только переименовывает ([[info-twin-renames-volume]]),
        # а proc.exe_path под execve указывает на сам `ls` и у фона с атакующим
        # одинаков. Осью могла бы стать родословная, но её значения для ЭТИХ
        # правил не измерены ни в одном архиве куста, а per-alert предков стор
        # не отдаёт и для info-яруса не отдаст по построению
        # ([[alerts-api-has-no-process-chain]], store.min_severity=warning).
        # Поэтому остаток здесь не сужается, а ПЕЧАТАЕТСЯ поимённо: он
        # остаётся названной частью величины, а не забытой. Вход волны 7.
        echo "  названный остаток (открытый вопрос 14, сужением куста не берётся) — два info-правила по оси comm:"
        w626_volume_by_source "$W626_ART/metrics-window-start.txt" "$W626_ART/metrics-window-end.txt" \
            "recon_security_tools_enum recon_process_enum" | sed 's/^/    /'
        echo "    (база 6.2.5: 3 + 1 = 4 алерта/окно = 24/ч из величины (а); порога у остатка нет — при гейте 100/ч он не блокирующий, и объявлять его блокирующим без замера было бы назначением порога суждением, что волна 5.9.6 себе запретила)"
        if [ "${_w626_vbs_rows:-0}" -eq 0 ]; then
            die "6.2.6.2 НЕИЗМЕРИМ (№282): разбивка по (в) непуста (${_w626_v_sum}), а ось {rule_id, comm} ПУСТА — item 1 не задеплоен либо exporter.volume_by_source выключен. Волна неизмерима в своей ГЛАВНОЙ части: остаток гейта сужать нечем, и item 6 остаётся сужением по прологовым именам"
        elif awk -v s="$_w626_v_sum" -v v="$_w626_v_total" 'BEGIN{exit !(s >= 0.95*v)}'; then
            pass "6.2.6.2 ДОСТИГНУТО: разбивка по (в) покрывает ${_w626_v_cov}% величины (вершина: ${_w626_v_top:-нет}), ось {rule_id, comm} снята метрикой — ${_w626_vbs_rows} строк, переполнений ${_w626_vbs_ovf}. Это законный вход для сужения верхушки шума"
        else
            die "6.2.6.2 ПРОВАЛЕН: разбивка по (в) покрывает лишь ${_w626_v_cov}% величины ($_w626_v_sum из $_w626_v_total)"
        fi
    fi
else
    die "6.2.6.2 НЕИЗМЕРИМ: библиотека не подключилась"
fi

# ---- 6.2.6.3: доля измерителя в окне = 0 (№242) ----
echo "--- 6.2.6.3: доля измерителя внутри окна (ВЕРДИКТ, а не поправка) ---"
_w626_instr=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" --argjson comms "$W626_INSTR_COMMS" '
    [ .[] | select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t0) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $t1))
      | select((.comm) as $c | ($comms|index($c))) ]
    | group_by(.comm)|map({c:.[0].comm,n:length})|sort_by(-.n)' "$W626_ART/alerts-window-end.json" 2>/dev/null)
_w626_instr_n=$(echo "${_w626_instr:-[]}" | jq '[.[].n]|add // 0' 2>/dev/null)
# Вторая половина критерия: алерты НА ПУТИ артефактов контроля. Файл
# metrics-window-start.txt создаётся в каталоге, за которым следит
# drift_new_file_dir_sensitive; правка №242 переносит запись ДО t0, но
# остаточная гонка (задержка ring buffer) аналитически не закрывается —
# открытый вопрос 16 требует проверить это ЖИВЫМ прогоном, здесь и сейчас.
_w626_artpath=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" --arg art "$W626_ART" '
    [ .[] | select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t0) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $t1))
      | select((.details["file.path"] // "") | startswith($art)) ] | length' "$W626_ART/alerts-window-end.json" 2>/dev/null)
echo "  алертов от comm измерителя внутри [t0,t1]: ${_w626_instr_n:-0} $(echo "${_w626_instr:-[]}" | jq -r 'map("\(.c):\(.n)")|join(" ")' 2>/dev/null)"
# АТРИБУЦИЯ (№242, вторая правка). Из тех же алертов выделяются те, чей pid
# принадлежит ДЕРЕВУ ИЗМЕРИТЕЛЯ, снятому до t0. Только они — работа
# измерителя; остальное с родовым comm есть фон ноды (смок 07.09.2026:
# `grep /proc/cpuinfo` от systemd-таймера motd-news.service).
_w626_instr_own=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" --argjson comms "$W626_INSTR_COMMS" --argjson pids "${_w626_pids_json:-[]}" '
    [ .[] | select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t0) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $t1))
      | select((.pid) as $p | ($pids|index($p))) ]' "$W626_ART/alerts-window-end.json" 2>/dev/null)
_w626_instr_own_n=$(echo "${_w626_instr_own:-[]}" | jq 'length' 2>/dev/null)
echo "  из них pid принадлежит дереву измерителя: ${_w626_instr_own_n:-0} $(echo "${_w626_instr_own:-[]}" | jq -r 'map("\(.comm):\(.rule_id)")|join(" ")' 2>/dev/null)"
echo "  остальные — фон ноды с родовым comm (не измеритель): $(( ${_w626_instr_n:-0} - ${_w626_instr_own_n:-0} ))"
_w626_reap_delta=$(( ${_w626_reaped1:-0} - ${_w626_reaped0:-0} ))
echo "  сторож ложного нуля: приращение cutime+cstime оболочки контроля за окно = ${_w626_reap_delta} тиков (>0 ⇒ измеритель ПОРОДИЛ процесс внутри окна, и pid-набор его не увидел бы)"
echo "  алертов на пути артефактов ($W626_ART) внутри [t0,t1]: ${_w626_artpath:-0}"
# РАЗЛИЧИТЕЛЬ ИСТОЧНИКА (смок 06.09.2026, ДО прогона). Список comm измерителя
# состоит из РОДОВЫХ имён (sh, bash, awk, grep, date, cut, …), и ровно те же
# имена порождает ЛЮБОЙ интерактивный вход по ssh: pam запускает
# /etc/update-motd.d/* — run-parts → 00-header → uname, landscape-sysin, grep
# /proc/cpuinfo, date, pgrep. То есть чужой вход внутрь окна печатается этим
# критерием как «доля измерителя», хотя измеритель спал. Смок этой волны упал
# ровно так: 7 алертов sh/awk/bash/date/grep/pgrep — это была цепочка MOTD
# оператора, зашедшего посмотреть прогресс (нарушение п.2/п.5 памяти
# ebpf-guard-measurement-hygiene, а не дефект контроля).
# Вердикт от этого НЕ смягчается: алерты входа — часть измеренной величины
# 6.2.6.1 и окно испорчено в любом случае. Но причина обязана быть НАЗВАНА,
# иначе следующий читатель полдня ищет несуществующую работу измерителя.
_w626_login_in_win=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" '
    [ .[] | select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t0) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $t1))
      | select((.comm) as $c | (["sshd","run-parts","landscape-sysin","00-header","91-release-upgr","50-motd-news","login"]|index($c))) ] | length' \
    "$W626_ART/alerts-window-end.json" 2>/dev/null)
echo "  различитель источника: алертов входа/MOTD (sshd, run-parts, landscape-sysin, 00-header, …) внутри окна: ${_w626_login_in_win:-0}"
# MOTD-цепочку порождает не только вход: `motd-news.timer` дёргает
# /etc/update-motd.d/50-motd-news по расписанию, БЕЗ всякого ssh (смок
# 07.09.2026: таймер сработал в 19:27:02 ровно внутри окна). Поэтому
# «вход» отделяется от «таймера» по наличию sshd/login: иначе штатный фон
# ноды объявляется нарушением гигиены и следующий читатель ищет
# несуществующее подключение.
_w626_login_ssh=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" '
    [ .[] | select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t0) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $t1))
      | select((.comm) as $c | (["sshd","login"]|index($c))) ] | length' \
    "$W626_ART/alerts-window-end.json" 2>/dev/null)
if [ "${_w626_login_ssh:-0}" -gt 0 ]; then
    echo "  ВНИМАНИЕ: внутрь окна попал ИНТЕРАКТИВНЫЙ ВХОД (алертов sshd/login: ${_w626_login_ssh}). Родовые comm (sh/bash/awk/grep/date/pgrep) принадлежат его цепочке MOTD, а не работе измерителя — окно испорчено посторонним подключением (п.2/п.5 гигиены), и величина 6.2.6.1 этого прогона завышена на его вклад"
elif [ "${_w626_login_in_win:-0}" -gt 0 ]; then
    echo "  примечание: MOTD-цепочка внутри окна есть, а sshd/login нет — это systemd-таймер ноды (motd-news.timer и соседи), штатный фон, а не чужой вход и не измеритель"
fi
if [ "${_w626_instr_own_n:-0}" -eq 0 ] && [ "${_w626_artpath:-0}" -eq 0 ] && [ "${_w626_reap_delta:-0}" -le 0 ]; then
    pass "6.2.6.3 ДОСТИГНУТО: измеритель внутри окна не работал — ни одного алерта из его дерева, ни одного алерта на пути его артефактов, ни одного пожатого потомка (родовых comm фона ноды внутри окна: ${_w626_instr_n:-0} — это не он, см. атрибуцию выше)"
else
    die "6.2.6.3 ПРОВАЛЕН: внутри окна ${_w626_instr_own_n:-0} алертов ИЗ ДЕРЕВА измерителя (родовых comm всего ${_w626_instr_n:-0}), ${_w626_artpath:-0} на пути его артефактов, приращение потомков ${_w626_reap_delta:-0} тиков. Это ЧАСТЬ измеренной величины 6.2.6.1, а не поправка к её чтению: контроль обязан не работать внутри окна вовсе (находка №242). Если ненулевая половина — путь артефактов, починка не в порядке операций, а в переносе снимков ВНЕ поддерева, за которым следит drift_new_file_dir_sensitive (открытый вопрос 16)"
fi

# ---- 6.2.9.F.3 (№293, item 3 волны 6.2.9.F): атрибуция ПО ДЕРЕВУ, а не по
# статическому набору pid ----
# 6.2.6.3 выше атрибутирует по членству `.pid` в measurer-pids.txt — наборе,
# снятом ДО t0 (комментарий у _w626_pids_file). Это слепо к собственным
# потомкам измерителя, порождённым НЕ во время сна на ФИФО, а на ГРАНИЦАХ
# окна: item 2 (№295) прямым чтением архива `collect-6.2.6-run2` показал
# семь curl/awk/cp/sleep, порождённых ЧТЕНИЕМ МЕТРИКИ ровно на t1 — их pid
# не мог попасть в снимок, снятый раньше. Правка item 3 —
# internal/store/sqlite.go: новая колонка `process_tree`, без неё
# /api/v1/alerts всегда отдавал пустое дерево (память
# alerts-api-has-no-process-chain) и атрибуция по дереву была структурно
# недоступна. Предикат — принадлежит ли pid ЭТОГО скрипта ($$) цепочке
# ПРЕДКОВ алерта (движок уже строит её в LineageTracker на каждое событие),
# а не совпадает ли pid алерта с заранее собранным списком: он не зависит от
# МОМЕНТА порождения потомка внутри прогона.
echo "--- 6.2.9.F.3: атрибуция по дереву (№293) ---"
# ГРАНИЦА ОКНА ТОЧНАЯ, С ДРОБНОЙ ЧАСТЬЮ (`w626ts`, правка №291). Соседние
# блоки этого файла сравнивают время через `sub("\\.[0-9]+Z$";"Z")`, то есть
# усекают отметку до секунды, и `<= t1` втягивает в окно ВСЁ, что случилось в
# [t1, t1+1) — ровно те семь curl/awk/cp/sleep, которыми №295 и доказала
# протечку верхней границы. Здесь это недопустимо вдвойне: блок как раз и
# существует, чтобы отличить работу измерителя от работы ноды, и усечение
# приписало бы окну собственную работу читателя, а потом честно назвало бы её
# «измеритель» — атрибуция верная, окно неверное.
#
# ПРЕДИКАТ — ПРИНАДЛЕЖНОСТЬ $$ ЦЕПОЧКЕ, ПО pid ЛИБО ПО ppid. Одного `.pid ==
# $self` мало: LineageTracker строит цепочку из НАБЛЮДЁННЫХ exec'ов, и bash
# самого контроля стартовал ДО агента (или выпал по TTL/MaxDepth) — тогда в
# дереве останется только потомок, зато его `.ppid` по-прежнему указывает на
# $$. Сравнение по ppid не может дать ложного «своего»: чужой процесс с
# ppid == $$ есть по определению потомок этого скрипта.
_w626_self_pid=$$
# СТОРОЖ ПРЕДИКАТА (найден при реплее правки исхода А, 11.09.2026). Предикат
# «своё» включает `.ppid == $self`, и при $$ == 1 он совпадает с КАЖДЫМ корнем
# дерева — у корня ppid равен 1 по построению. Тогда вся величина окна была бы
# объявлена работой измерителя, а цена события ноды — нулём: приборный ноль,
# неотличимый от продуктового. Скрипт может оказаться PID 1 буквально (запуск
# пайплайна как единственного процесса контейнера), поэтому случай не
# гипотетический и закрывается явной неизмеримостью, а не молчанием.
_W626_TREE_SELF_OK=1
[ "${_w626_self_pid:-1}" -le 1 ] && _W626_TREE_SELF_OK=0
_w626_tree_q='def w626ts: (.timestamp | capture("^(?<i>[^.]+)(\\.(?<f>[0-9]+))?Z$")) as $c
       | ($c.i + "Z" | fromdateiso8601) + (($c.f // "0") | ("0." + .) | tonumber);
     def own: (.process_tree // []) | any(.pid == $self or .ppid == $self);'
_w626_alerts_json="$W626_ART/alerts-window-end.json"
if [ ! -s "$_w626_alerts_json" ]; then
    die "6.2.9.F.3 НЕИЗМЕРИМ (№293): среза алертов на границе закрытия окна нет или он пуст ($_w626_alerts_json) — атрибуцию считать не по чему, и ноль здесь был бы приборным"
else
_w626_window_total_n=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" --argjson self "$_w626_self_pid" \
    "$_w626_tree_q"' [.[]|select((w626ts >= $t0) and (w626ts <= $t1))]|length' "$_w626_alerts_json" 2>/dev/null)
_w626_tree_own_n=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" --argjson self "$_w626_self_pid" \
    "$_w626_tree_q"' [.[]|select((w626ts >= $t0) and (w626ts <= $t1))|select(own)]|length' "$_w626_alerts_json" 2>/dev/null)
_w626_tree_unattr_n=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" --argjson self "$_w626_self_pid" \
    "$_w626_tree_q"' [.[]|select((w626ts >= $t0) and (w626ts <= $t1))|select(((.process_tree // [])|length) == 0)]|length' "$_w626_alerts_json" 2>/dev/null)
# ПРЯМОЕ ЧИСЛО ПРОТЕЧКИ ВЕРХНЕЙ ГРАНИЦЫ (№295), которое item 2 снять не мог:
# алерты ПОСЛЕ t1, опознанные как свои ПО ДЕРЕВУ, а не по догадке о comm.
_w626_tree_leak_n=$(jq --argjson t1 "$_w626_t1" --argjson self "$_w626_self_pid" \
    "$_w626_tree_q"' [.[]|select((w626ts > $t1) and (w626ts <= ($t1 + 2)))|select(own)]|length' "$_w626_alerts_json" 2>/dev/null)
_w626_tree_own_n=${_w626_tree_own_n:-0}; _w626_tree_unattr_n=${_w626_tree_unattr_n:-0}
_w626_window_total_n=${_w626_window_total_n:-0}; _w626_tree_leak_n=${_w626_tree_leak_n:-0}
_w626_tree_node_n=$(( _w626_window_total_n - _w626_tree_own_n - _w626_tree_unattr_n ))
echo "  всего алертов в окне [t0,t1] (точная граница, дробная часть не усечена): ${_w626_window_total_n}"
echo "  по дереву — нода: ${_w626_tree_node_n}, измеритель: ${_w626_tree_own_n}, НЕАТРИБУТИРУЕМО (пустой process_tree): ${_w626_tree_unattr_n}"
echo "  для сверки: та же доля по СТАТИЧЕСКОМУ набору pid (вход соседнего критерия, снят ДО t0) = ${_w626_instr_own_n:-0} — расхождение с ${_w626_tree_own_n} и есть цена слепоты статического набора к потомкам, порождённым на границах окна (№293)"
echo "  протечка верхней границы (№295), снятая ПО ДЕРЕВУ, а не оценкой: ${_w626_tree_leak_n} алертов измерителя в (t1, t1+2с] — в величину окна НЕ входят и из неё не вычитаются, печатаются как размер эффекта"
if [ "$_W626_TREE_SELF_OK" -eq 0 ]; then
    die "6.2.9.F.3 НЕИЗМЕРИМ (№293): pid измерителя = ${_w626_self_pid} — предикат «своё» по ppid совпал бы с КАЖДЫМ корнем дерева (у корня ppid = 1), и вся величина окна была бы приписана работе замера. Атрибуция по дереву в этом окружении (скрипт исполняется как PID 1) недоступна, и ноль здесь был бы приборным"
elif [ "$_w626_window_total_n" -eq 0 ]; then
    die "6.2.9.F.3 НЕИЗМЕРИМ (№293): в срезе нет НИ ОДНОГО алерта с отметкой внутри [t0,t1] — либо срез снят не тем окном, либо агент молчал всё окно; атрибуция тривиальна только на вид, и ноль здесь приборный, а не вердикт"
elif [ "$_w626_tree_unattr_n" -eq "$_w626_window_total_n" ]; then
    die "6.2.9.F.3 НЕИЗМЕРИМ (№293): ни один алерт окна не несёт process_tree — либо profiler.lineage.enabled=false, либо на стенде не задеплоена правка стора (internal/store/sqlite.go: колонка process_tree; требует make build + рестарт юнита), либо LineageTracker не успел построить цепочку ни для одного pid окна; атрибуция по дереву недоступна, item 3 этим прогоном не подтверждён"
else
    pass "6.2.9.F.3 ИЗМЕРЕНО (№293, порог величине не назначается): величина окна разделена ПО ДЕРЕВУ ПРЕДКОВ (pid скрипта = ${_w626_self_pid}), а не по имени процесса — нода ${_w626_tree_node_n}, измеритель ${_w626_tree_own_n}, неатрибутируемый остаток ${_w626_tree_unattr_n} напечатан явно и входит в величину как её неизмеримая часть"
fi
fi

# ---- 6.2.9.F.7 (item 6(а) волны 6.2.9.F): АДРЕСАТ каждой величины и ЕДИНИЦА,
# в которой она напечатана (находка №297) ----
# Постановка требует: «у каждой напечатанной величины названа её природа
# (инженерная / диагностическая / консольная) — вердикт без указания адресата
# не засчитывается». Четыре слоя печатаются с 6.2.2 голыми числами, и из них
# невозможно понять, кому какая величина адресована: слой 2
# (alerts_filtered_total) — это severity=info, который НЕ доезжает ни до
# консоли дежурного, ни до Alertmanager, а слой 3/слой 4 — вовсе счётчики
# механизма доставки. Гейт же судится по сумме слой1+слой2, то есть по
# величине со СМЕШАННЫМ адресатом: половина её — то, что человек увидит,
# половина — то, чего он не увидит никогда. Это печатается явно.
#
# ВТОРАЯ ПОЛОВИНА БЛОКА — ЕДИНИЦА (находка №297). Величина гейта получается
# домножением оконного счёта на 3600/окно, и это законно ТОЛЬКО для потока.
# Потока нет: на обоих снятых архивах алерты окна лежат в 2–3 секундах из 600,
# а остальные 597–598 узел молчит. Тогда «N алертов/ч» значит не скорость, а
# «попал ли в окно тик периодической задачи», и вердикт объёма без строки о
# концентрации — дезинформация, а не измерение. Поэтому рядом с величиной
# печатается её СОСТАВ ПО КОРНЮ ДЕРЕВА (кто её породил) и её РАСПРЕДЕЛЕНИЕ ПО
# СЕКУНДАМ (сколько секунд окна вообще непусты и каков максимум в одной).
# Величина при этом НЕ пересчитывается и НЕ корректируется — блок ничего не
# вычитает, он называет природу напечатанного.
echo "--- 6.2.9.F.7: адресат каждой величины и единица, в которой она напечатана (№297) ---"
echo "  слой 1 alerts_total       = ${_w626_layer_total}: ИНЖЕНЕРНАЯ — доезжает до Alertmanager/уведомлений, её видит человек"
echo "  слой 2 alerts_filtered_total = ${_w626_layer_filtered}: ДИАГНОСТИЧЕСКАЯ — severity=info, до консоли дежурного НЕ доезжает вовсе"
echo "  слой 3 alerts_ratelimited_by_rule = ${_w626_rl}: ДИАГНОСТИЧЕСКАЯ — счётчик подавления, наружу не выходит ни одним алертом"
echo "  слой 4 alerts_dedup_dropped = ${_w626_dd}: ДИАГНОСТИЧЕСКАЯ — механизм ДОСТАВКИ (решение 3), не событие продукта"
echo "  величина гейта (формула $W626_GATE_FORMULA) = ${_w626_vol} за окно: адресат СМЕШАННЫЙ (слой1 инженерный + слой2 диагностический) — порог 100/ч назначался ей целиком, а человеку из неё адресована только часть слоя 1"
echo "  величина (в) = ${_w626_v_total} за окно: ДИАГНОСТИЧЕСКАЯ целиком — три из четырёх её слоёв наружу не выходят"
_w626_f7_console=""
_w626_f7_secs=""; _w626_f7_max=""; _w626_f7_roots=""
if [ -s "${_w626_alerts_json:-}" ] && [ "${_w626_window_total_n:-0}" -gt 0 ]; then
    _w626_f7_q='def w626ts: (.timestamp | capture("^(?<i>[^.]+)(\\.(?<f>[0-9]+))?Z$")) as $c
           | ($c.i + "Z" | fromdateiso8601) + (($c.f // "0") | ("0." + .) | tonumber);
         def win: [.[]|select((w626ts >= $t0) and (w626ts <= $t1))];
         def root: ((.process_tree // []) | if length > 0 then .[0].comm else "(нет дерева)" end);'
    # КОНСОЛЬНАЯ величина — та, ради которой продукт существует: что увидит
    # дежурный после ВСЕХ четырёх слоёв подавления. Считается по стору, а не
    # по метрике: у alerts_filtered_total нет разреза severity, и метрикой
    # «что осталось человеку» не восстанавливается (память
    # narrowing-input-must-be-metric-not-store действует в обратную сторону —
    # там вход СУЖЕНИЯ, здесь адресат ВЕРДИКТА).
    _w626_f7_console=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" \
        "$_w626_f7_q"' win | map(select(.severity != "info")) | length' "$_w626_alerts_json" 2>/dev/null)
    # СТОРОЖ ТОЖДЕСТВЕННОГО ФИЛЬТРА. На обоих снятых архивах в срезе НЕТ НИ
    # ОДНОГО алерта severity=info — стор их не хранит вовсе, и `select(.severity
    # != "info")` не отбрасывает ничего. Тогда «консольная величина» равна
    # оконному счёту стора, и называть её «после всех четырёх слоёв» без этой
    # оговорки значило бы приписать фильтру работу, которой он не делал
    # (класс №269 — молчаливый пропуск). Число info печатается рядом, чтобы
    # тождественность фильтра была видна из архива, а не предполагалась.
    _w626_f7_info=$(jq "$_w626_f7_q"' [.[]|select(.severity == "info")] | length' "$_w626_alerts_json" 2>/dev/null)
    _w626_f7_secs=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" \
        "$_w626_f7_q"' win | map(w626ts|floor) | unique | length' "$_w626_alerts_json" 2>/dev/null)
    _w626_f7_max=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" \
        "$_w626_f7_q"' win | group_by(w626ts|floor) | map(length) | max // 0' "$_w626_alerts_json" 2>/dev/null)
    _w626_f7_roots=$(jq -r --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" \
        "$_w626_f7_q"' win | group_by(root) | map({r: (.[0]|root), n: length}) | sort_by(-.n)[] | "    \(.n)\t\(.r)"' "$_w626_alerts_json" 2>/dev/null)
    # ЦЕНА ОДНОГО СОБЫТИЯ НОДЫ — величина, которой решением 11.09.2026 (исход А
    # item 6) заменена «алертов/ч». Берётся как САМЫЙ ДОРОГОЙ корень дерева за
    # окно: один корень = одно событие ноды (срабатывание таймера, цикл
    # переписывания правил, тик cron), и число алертов под ним не зависит ни от
    # длины окна, ни от того, попало ли событие в окно вообще. Из кандидатов
    # исключены ДВА класса, и оба по причине, а не для красоты:
    #   • дерево ИЗМЕРИТЕЛЯ (предикат own, тот же, что в 6.2.9.F.3) — это цена
    #     самого замера, а не ноды; печатается отдельной строкой;
    #   • алерты без process_tree — корень неизвестен, и приписать их событию
    #     значило бы назвать ценой то, что не атрибутировано (№293).
    # ЕДИНИЦА ВЕЛИЧИНЫ — «ОДНО ДЕРЕВО × ОДНА СЕКУНДА». Две предыдущие попытки
    # сняты смоком на стенде 11.09.2026, обе по одной причине — под ключом
    # слипались РАЗНЫЕ события:
    #   • по comm корня: «29 алертов на событие sshd» — это были десятки
    #     отдельных ssh-подключений брутфорса (стенд под постоянным сканом,
    #     память ebaka2-test-stand), а не одно событие;
    #   • по pid корня: «28 на sshd (pid 2642344)» — корнем всех подключений
    #     оказался ДОЛГОЖИВУЩИЙ мастер-sshd, и они слиплись снова.
    # Ключ (корневой pid, секунда) разводит и этот случай: событие ноды
    # приходит взрывом (находка №297 — 17-18 алертов в ОДНУ секунду), а
    # подключения демона размазаны по разным секундам и дают по 1-2.
    # На архиве 6.2.9.F величина = 18 (motd-news, одна секунда), у демонов
    # k3s-server/containerd остаются пачки по 2-5.
    #
    # ЧЕГО ЕДИНИЦА НЕ ДЕЛАЕТ: событие, растянутое больше чем на секунду,
    # она разрежет и даст НИЖНЮЮ оценку. Это осознанный размен: слипание
    # завышало величину в разы и молча, разрез занижает её предсказуемо и
    # виден рядом напечатанной суммой по тому же дереву за всё окно.
    # СЧЁТ ЖИВЁТ В БИБЛИОТЕКЕ (w626_window_top_tree, №302): у неё есть
    # офлайн-сторож на архиве collect-6.2.9.F.1, где ОБА дерева известны
    # поимённо — победитель 16764 (50-motd-news, 17) и механизм введения
    # 16763 (systemctl транзиентного юнита, 7). Прежде тот же jq стоял здесь
    # копией и ни разу не проверялся офлайн. Третьим полем строки теперь
    # идёт pid победителя — он нужен сторожу ложного PASS ниже.
    _w626_f7_price_line=$(w626_window_top_tree "$_w626_alerts_json" "$_w626_t0" "$_w626_t1" "$_w626_self_pid")
    # РАЗОВАЯ ЗАДАЧА ИЛИ ДЕМОН — признак, отличающий «цену одного события» от
    # «самой дорогой секунды демона». Первая попытка считала РАЗНЫЕ ВЕТВИ
    # второго уровня и была ложной: одно срабатывание motd-news даёт 8 ветвей
    # (mktemp, uname, dpkg-query, wget, grep…), то есть диагностика объявляла
    # одно событие восемью. Верный признак — СКОЛЬКО СЕКУНД окна корень вообще
    # активен: короткоживущая задача укладывается в одну-две (весь её шум и
    # есть одно событие), а демон (мастер-sshd, k3s-server, containerd) сыпет
    # пачки в разных секундах всё окно, и одна его пачка — не «событие», а
    # срез. Печатается число пачек у корня-победителя.
    _w626_f7_packs=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" --argjson self "$_w626_self_pid" \
        "$_w626_f7_q"' def own: (.process_tree // []) | any(.pid == $self or .ppid == $self);
           def rpid: ((.process_tree // []) | if length > 0 then .[0].pid else null end);
           (win | map(select((own | not) and (rpid != null)))) as $w
           | ($w | group_by([rpid, (w626ts | floor)]) | sort_by(-length)) as $packs
           | if ($packs | length) > 0
             then ($packs[0][0] | rpid) as $top
                  | ($w | map(select(rpid == $top)) | group_by(w626ts | floor) | length)
             else 0 end' \
        "$_w626_alerts_json" 2>/dev/null)
    _w626_f7_own_n=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" --argjson self "$_w626_self_pid" \
        "$_w626_f7_q"' def own: (.process_tree // []) | any(.pid == $self or .ppid == $self);
           win | map(select(own)) | length' "$_w626_alerts_json" 2>/dev/null)
fi
_W626_EVENT_PRICE=$(printf '%s' "${_w626_f7_price_line:-0}" | cut -f1)
_W626_EVENT_ROOT=$(printf '%s' "${_w626_f7_price_line:-}" | cut -f2)
_W626_EVENT_PID=$(printf '%s' "${_w626_f7_price_line:-}" | cut -f3)
_W626_EVENT_PRICE=${_W626_EVENT_PRICE:-0}
_W626_EVENT_ROOT=${_W626_EVENT_ROOT:-(не определён)}
_W626_EVENT_PID=${_W626_EVENT_PID:-0}
# ЦЕНА МЕХАНИЗМА ВВЕДЕНИЯ СОБЫТИЯ (№302). Транзиентный юнит, которым замер
# форсирует тик ноды, предикатом «своё» НЕ ловится по построению: дерево
# висит на systemd, в чём и был смысл item 1. На этом прогоне он стоил 7
# алертов против 17 у события и в цену не вошёл лишь потому, что оказался
# дешевле. Величина печатается ТРЕТЬЕЙ строкой рядом с ценой события и ценой
# самого замера — иначе она невидима, а на более тихом событии стала бы
# «ценой события ноды» молча.
_W626_FORCE_MECH_PID=0
_W626_FORCE_MECH_PRICE=0
if [ "${_W626_FORCE_SCHEDULED:-0}" -eq 1 ]; then
    _W626_FORCE_MECH_PID=$(systemctl show -p ExecMainPID --value "${_W626_FORCE_UNIT}.service" 2>/dev/null)
    _W626_FORCE_MECH_PID=${_W626_FORCE_MECH_PID:-0}
    case "$_W626_FORCE_MECH_PID" in ''|*[!0-9]*) _W626_FORCE_MECH_PID=0 ;; esac
    if [ "$_W626_FORCE_MECH_PID" -gt 0 ] && [ -s "${_w626_alerts_json:-}" ]; then
        _W626_FORCE_MECH_PRICE=$(w626_tree_price_for_pid "$_w626_alerts_json" "$_w626_t0" "$_w626_t1" "$_W626_FORCE_MECH_PID")
        _W626_FORCE_MECH_PRICE=${_W626_FORCE_MECH_PRICE:-0}
    fi
fi
# РАЗЪЕЗД «МЕТРИКА ПРОТИВ СТОРА» НА ГРАНИЦАХ (№295, прогон 11.09.2026).
# На прогоне collect-6.2.9.F-A метрика дала 22 алерта за окно, а стор внутри
# ТОЧНЫХ границ — ноль: узел молчал все 600 с, и вся величина метрики была
# сложена из работы измерителя на закрытии окна (curl/cp/tail/mv/sleep с
# корнем run-6.2.6-pipel, 11 штук в первые 11 секунд ПОСЛЕ t1). Понять это по
# архиву удалось только руками, поэтому разъезд печатается сам: сколько
# алертов дерева измерителя пришло в (t1, t1+30с] — окно шире двухсекундного
# счётчика протечки выше, потому что запись в стор и сериализация ответа curl
# отстают от отметки t1 на секунды, а не на миллисекунды.
_w626_f7_after=0
if [ -s "${_w626_alerts_json:-}" ]; then
    _w626_f7_after=$(jq --argjson t1 "$_w626_t1" --argjson self "$_w626_self_pid" \
        'def w626ts: (.timestamp | capture("^(?<i>[^.]+)(\\.(?<f>[0-9]+))?Z$")) as $c
           | ($c.i + "Z" | fromdateiso8601) + (($c.f // "0") | ("0." + .) | tonumber);
         def own: (.process_tree // []) | any(.pid == $self or .ppid == $self);
         [.[]|select((w626ts > $t1) and (w626ts <= ($t1 + 30)))|select(own)] | length' \
        "$_w626_alerts_json" 2>/dev/null)
fi
_w626_f7_after=${_w626_f7_after:-0}
# ПЕЧАТАЕТСЯ И ПО ПРЕДИКАТУ, И ПО КОРНЯМ. Предикат «своё» может промахнуться
# (цепочка не построена, потомок пережил родителя), и тогда одинокий ноль
# читался бы как «измеритель тут ни при чём» — ровно ложный вывод, который
# этот блок и заводится опровергать. Разбивка по корням от предиката не
# зависит: по ней видно, чьи это алерты, даже когда own дал ноль.
_w626_f7_after_roots=""
if [ -s "${_w626_alerts_json:-}" ]; then
    _w626_f7_after_roots=$(jq -r --argjson t1 "$_w626_t1" \
        'def w626ts: (.timestamp | capture("^(?<i>[^.]+)(\\.(?<f>[0-9]+))?Z$")) as $c
           | ($c.i + "Z" | fromdateiso8601) + (($c.f // "0") | ("0." + .) | tonumber);
         def root: ((.process_tree // []) | if length > 0 then .[0].comm else "(нет дерева)" end);
         [.[]|select((w626ts > $t1) and (w626ts <= ($t1 + 30)))]
         | group_by(root) | map({r: (.[0]|root), n: length}) | sort_by(-.n) | .[0:3]
         | map("\(.n)×\(.r)") | join(", ")' "$_w626_alerts_json" 2>/dev/null)
fi
echo "  работа ПОСЛЕ закрытия окна, (t1, t1+30с]: ${_w626_f7_after} алертов дерева измерителя по предикату; по корням — ${_w626_f7_after_roots:-(пусто)}. В величину окна не входят, но в МЕТРИЧЕСКИЙ снимок на t1 попасть могли (№295: запись в стор и сериализация ответа curl отстают от отметки t1 на секунды)"
if [ "${_w626_window_total_n:-0}" -eq 0 ] && [ "${_w626_vol_all:-0}" -gt 0 ]; then
    echo "  ⚠ РАЗЪЕЗД: метрика насчитала ${_w626_vol_all} алертов за окно, а стор внутри ТОЧНЫХ границ — НОЛЬ. Узел молчал всё окно, и величина (а) на этом прогоне сложена НЕ из работы ноды: её источник — либо severity=info (стор его не хранит), либо работа на границах, опознанная строкой выше. Судить продукт по такой величине нельзя ни в какую сторону"
fi
_w626_f7_console=${_w626_f7_console:-0}; _w626_f7_secs=${_w626_f7_secs:-0}; _w626_f7_max=${_w626_f7_max:-0}
_w626_f7_info=${_w626_f7_info:-0}
echo "  КОНСОЛЬНАЯ величина (то, что доехало до стора и может быть показано человеку): ${_w626_f7_console} за окно → $(_w626_hour "$_w626_f7_console")/ч"
if [ "$_w626_f7_info" -eq 0 ]; then
    echo "    оговорка: severity=info в срезе стора ${_w626_f7_info} — фильтр по severity ТОЖДЕСТВЕННЫЙ, стор диагностический слой не хранит вовсе. Величина выше есть «доехавшее до стора», а не «оставшееся после четвёртого слоя»: разницу между ними этим прибором не снять"
fi
echo "  состав величины окна ПО КОРНЮ ДЕРЕВА (кто её породил, а не чей comm у листа):"
printf '%s\n' "${_w626_f7_roots:-    (состав не снят — нет среза алертов)}"
echo "  распределение по секундам: непустых секунд ${_w626_f7_secs} из ${W626_WINDOW}, максимум в одной секунде ${_w626_f7_max} алертов"
# №301 (волна 6.2.9.F.1): КОРНИ ВИДА «(имя)». systemd ставит форкнутому
# потомку скобочный comm между fork() и execve (буфер 11 байт, держится ХВОСТ
# имени: «(50-motd-news)» приходит как «(otd-news)»). Это НЕ дефект нашего
# событийного пути — но ключ дерева есть comm КОРНЯ, и один процесс попадает
# в состав величины двумя строками. Печатается ЧИСЛО таких корней И счётчик
# попыток нормализации: «ноль скобочных корней» обязано отличаться от
# «нормализация не вызывалась» (память drift-stuck-is-lazily-evaluated).
_w626_f7_prov=0
if [ -s "${_w626_alerts_json:-}" ]; then
    _w626_f7_prov=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" \
        "$_w626_f7_q"' win | map(select(((.process_tree // []) | length > 0) and (root | test("^\\(.*\\)$")))) | length' "$_w626_alerts_json" 2>/dev/null)
    _w626_f7_prov=${_w626_f7_prov:-0}
fi
if grep -q '^ebpf_guard_lineage_provisional_comm_total' "$W626_ART/metrics-window-end.txt" 2>/dev/null; then
    echo "  корней вида «(имя)» в составе окна (№301): ${_w626_f7_prov}; нормализация по метрике — seen=$(_w626_metric_sum ebpf_guard_lineage_provisional_comm_total seen "$W626_ART/metrics-window-end.txt") renormalized=$(_w626_metric_sum ebpf_guard_lineage_provisional_comm_total renormalized "$W626_ART/metrics-window-end.txt") unresolved=$(_w626_metric_sum ebpf_guard_lineage_provisional_comm_total unresolved "$W626_ART/metrics-window-end.txt")"
else
    echo "  корней вида «(имя)» в составе окна (№301): ${_w626_f7_prov}; серии ebpf_guard_lineage_provisional_comm_total НЕТ — нормализация на стенде не задеплоена, и ноль выше (если он ноль) означает «скобочных имён не было», а не «они исправлены»"
fi
if [ "$_W626_TREE_SELF_OK" -eq 0 ]; then
    # Печатать здесь число нельзя: при сломанном предикате оно получено
    # разделением, которое сторож ниже объявляет недействительным, и строка
    # «цена события = 1» осталась бы в архиве рядом с вердиктом НЕИЗМЕРИМ.
    echo "  ← ЦЕНА ОДНОГО СОБЫТИЯ НОДЫ: НЕ СНИМАЕТСЯ (предикат «своё» недействителен при pid измерителя ${_w626_self_pid}, см. вердикт ниже)"
else
    echo "  ← ЦЕНА ОДНОГО СОБЫТИЯ НОДЫ (величина куста с 11.09.2026, порог НЕ назначен): ${_W626_EVENT_PRICE} алертов на самое дорогое ДЕРЕВО окна — «${_W626_EVENT_ROOT}»; цена самого замера (дерево измерителя) — ${_w626_f7_own_n:-0} алертов, в цену события не входит. Единица — одно ДЕРЕВО за одну СЕКУНДУ: событие ноды приходит взрывом, а подключения демона размазаны по секундам и в одну пачку не слипаются. Событие длиннее секунды эта единица разрежет — тогда величина НИЖНЯЯ оценка"
    if [ "${_W626_FORCE_SCHEDULED:-0}" -eq 1 ]; then
        if [ "${_W626_FORCE_MECH_PID:-0}" -gt 0 ]; then
            echo "    цена МЕХАНИЗМА ВВЕДЕНИЯ события (pid ${_W626_FORCE_MECH_PID}, транзиентный юнит ${_W626_FORCE_UNIT}): ${_W626_FORCE_MECH_PRICE} алертов — в цену события ноды НЕ входит и предикатом «своё» не ловится (дерево висит на systemd, №302)"
        else
            echo "    цена МЕХАНИЗМА ВВЕДЕНИЯ события: НЕ СНЯТА — ExecMainPID юнита ${_W626_FORCE_UNIT}.service пуст (юнит собран мусорщиком: RemainAfterExit не применился). Сторож ложного PASS ниже без этого pid'а работать не может"
        fi
    fi
    _w626_f7_packs=${_w626_f7_packs:-0}
    if [ "$_w626_f7_packs" -le 2 ]; then
        echo "    корень-победитель активен в ${_w626_f7_packs} секундах окна — это РАЗОВАЯ задача, и величина выше есть цена ОДНОГО её события"
    else
        echo "    корень-победитель активен в ${_w626_f7_packs} разных секундах окна — это ДЕМОН, и величина выше есть его самая дорогая секунда, а не цена одного события. Цену события у демона эта единица не снимает: у него один pid на все события окна"
    fi
fi
# ITEM 2 ВОЛНЫ 6.2.9.F.2 (№305). «Победитель — демон» обязан входить в
# условие 1 критерия выхода 6.2.6.21, а не оставаться справочной строкой
# здесь: прежде условие 1 читало только цену/6.2.6.1/6.2.9.F.7 и на прогоне,
# где корень-победитель — демон (k3s-server/containerd, пачки в разных
# секундах), печатало ВЗЯТО той же ценой, что и на разовой задаче — хотя сама
# единица («одна секунда демона») по определению НЕ есть «цена одного
# события» (см. строку выше). Флаг живёт здесь же, рядом с расчётом packs, а
# не пересчитывается заново у 6.2.6.21 — вторая копия того же условия
# разошлась бы с первой молча.
_W626_EVENT_IS_DAEMON=0
[ "$_W626_TREE_SELF_OK" -eq 1 ] && [ "${_w626_f7_packs:-0}" -gt 2 ] && _W626_EVENT_IS_DAEMON=1
if [ "$_W626_TREE_SELF_OK" -eq 0 ]; then
    die "6.2.9.F.7 НЕИЗМЕРИМ (№297 + сторож предиката): pid измерителя = ${_w626_self_pid}, атрибуция по дереву недоступна (вердикт блока атрибуции выше) — цена одного события ноды, ставшая величиной куста решением 11.09.2026, этим прогоном не снимается. Адресат величин назван, единица — нет"
elif [ "${_w626_window_total_n:-0}" -le 0 ] || [ "$_w626_f7_secs" -le 0 ]; then
    die "6.2.9.F.7 НЕИЗМЕРИМ (№297): состав и концентрация величины не сняты — среза алертов окна нет либо в нём ноль отметок внутри границ. Адресат величин назван, но природа единицы («в час» против «за тик задачи») этим прогоном не проверена"
elif [ "$_w626_f7_secs" -le 10 ]; then
    pass "6.2.9.F.7 ИЗМЕРЕНО (№297, порог величине не назначается): адресат каждой величины назван выше; ЕДИНИЦА же опровергнута прогоном — весь оконный счёт лежит в ${_w626_f7_secs} секундах из ${W626_WINDOW} (максимум ${_w626_f7_max} в одной), остальные узел молчит. Непрерывного фона нет, домножение на 3600/окно предполагает поток, которого не существует: «алертов/ч» здесь означает «попал ли в окно тик периодической задачи», а не скорость. Сравнимая величина, устойчивая к фазе, — цена ОДНОГО события ноды в алертах (см. состав по корню выше)"
else
    pass "6.2.9.F.7 ИЗМЕРЕНО (№297, порог величине не назначается): адресат каждой величины назван выше; счёт распределён по ${_w626_f7_secs} секундам окна из ${W626_WINDOW} (максимум ${_w626_f7_max} в одной) — на ЭТОМ прогоне фон похож на поток, и пересчёт в «алертов/ч» на нём защитим. Состав по корню дерева напечатан выше и остаётся входом для сужения"
fi

# ═════════════════════════════════════════════════════════════════════════════
# 6.2.9.F.8 — ВЕРДИКТ ФОРСИРОВАННОГО СОБЫТИЯ: сначала ФАКТ, потом цена.
#
# Контроль обязан утверждать факт измеряемого ДЕЙСТВИЯ, а не счётчик алертов
# (образец приёма — починка 6.0.14, находка №215). Здесь действие — что юнит
# ноды РЕАЛЬНО стартовал внутри [t0,t1]. Без этой половины ноль алертов под
# ним читался бы как «продукт события не заметил», хотя события не было:
# ровно тот ложный ноль, которым 11.09.2026 закончился прошлый прогон.
_w626_f8_ran=0
_w626_f8_start_e=0
_w626_f8_res="(не снят)"
_w626_f8_alerts=0
_w626_f8_roots="(пусто)"
if [ "${_W626_FORCE_SCHEDULED:-0}" -eq 1 ]; then
    _w626_f8_ts=$(systemctl show "$_W626_FORCE_TARGET" -p ExecMainStartTimestamp --value 2>/dev/null)
    [ -n "${_w626_f8_ts:-}" ] && _w626_f8_start_e=$(date -d "$_w626_f8_ts" +%s 2>/dev/null)
    _w626_f8_start_e=${_w626_f8_start_e:-0}
    _w626_f8_res=$(systemctl show "$_W626_FORCE_TARGET" -p Result --value 2>/dev/null)
    _w626_f8_res=${_w626_f8_res:-"(не снят)"}
    if [ "$_w626_f8_start_e" -ge "$_w626_t0" ] && [ "$_w626_f8_start_e" -le "$_w626_t1" ]; then
        _w626_f8_ran=1
    fi
    echo "  6.2.9.F.8 факт: $_W626_FORCE_TARGET стартовал $([ "$_w626_f8_start_e" -gt 0 ] && _w626_utc "$_w626_f8_start_e" || echo "НЕ СТАРТОВАЛ (ExecMainStartTimestamp пуст)"), Result=$_w626_f8_res; окно [$(_w626_utc "$_w626_t0"), $(_w626_utc "$_w626_t1")]; планировалось на $(_w626_utc "${_W626_FORCE_AT:-0}")"
    # Цена ИМЕННО этого события: алерты окна, у которых корень дерева —
    # потомок форсированного юнита. Ключ — comm корня по маске, а не pid:
    # pid транзиентного запуска заранее неизвестен, а comm у motd-news
    # устойчив (`50-motd-news` на обоих снятых архивах).
    if [ -s "${_w626_alerts_json:-}" ]; then
        _w626_f8_alerts=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" \
            'def w626ts: (.timestamp | capture("^(?<i>[^.]+)(\\.(?<f>[0-9]+))?Z$")) as $c
               | ($c.i + "Z" | fromdateiso8601) + (($c.f // "0") | ("0." + .) | tonumber);
             def root: ((.process_tree // []) | if length > 0 then .[0].comm else "" end);
             [.[]|select((w626ts >= $t0) and (w626ts <= $t1))|select(root | test("motd"))] | length' \
            "$_w626_alerts_json" 2>/dev/null)
        _w626_f8_alerts=${_w626_f8_alerts:-0}
    fi
    echo "  6.2.9.F.8 цена: ${_w626_f8_alerts} алертов окна под корнем, чей comm содержит «motd» (цена самого дорогого дерева окна по 6.2.9.F.7 — ${_W626_EVENT_PRICE} на «${_W626_EVENT_ROOT}»)"
fi
if [ "${_W626_FORCE_SCHEDULED:-0}" -ne 1 ]; then
    die "6.2.9.F.8 НЕИЗМЕРИМ: событие ноды в окно НЕ вводилось (форсирование выключено либо systemd-run не поставил таймер) — величина куста снова зависит от фазы таймеров ноды, и пустое окно на этом прогоне означает отсутствие события, а не свойство продукта (№299)"
elif [ "${_W626_FORCE_AT:-0}" -lt "$_w626_t0" ] || [ "${_W626_FORCE_AT:-0}" -gt "$_w626_t1" ]; then
    die "6.2.9.F.8 НЕИЗМЕРИМ: таймер поставлен на $(_w626_utc "${_W626_FORCE_AT:-0}"), что ВНЕ окна [$(_w626_utc "$_w626_t0"), $(_w626_utc "$_w626_t1")] — форсированное событие в измеряемую величину не попало. Смещение считается от постановки таймера, и осадка/пролог его сдвинули"
elif [ "$_w626_f8_ran" -ne 1 ]; then
    die "6.2.9.F.8 ПРОВАЛЕН: таймер сработал, но $_W626_FORCE_TARGET внутри окна НЕ стартовал (ExecMainStartTimestamp $([ "$_w626_f8_start_e" -gt 0 ] && _w626_utc "$_w626_f8_start_e" || echo пуст), Result=$_w626_f8_res) — ФАКТА события нет, и ноль алертов под ним НЕЛЬЗЯ читать как продуктовый. Проверить, что юнит существует и не замаскирован"
elif [ "${_W626_FORCE_MECH_PID:-0}" -le 0 ]; then
    die "6.2.9.F.8 НЕИЗМЕРИМ (№302): pid МЕХАНИЗМА ВВЕДЕНИЯ события не снят (ExecMainPID юнита ${_W626_FORCE_UNIT}.service пуст) — проверить, что цена события принадлежит НОДЕ, а не нашему способу его вызвать, нечем. Предикат «своё» механизм не ловит по построению: его дерево висит на systemd, в чём и был смысл item 1. Цена печатается строкой выше, но вердиктом она в таком виде не является"
elif w626_force_mechanism_is_winner "${_W626_EVENT_PID:-0}" "${_W626_FORCE_MECH_PID:-0}"; then
    die "6.2.9.F.8 НЕИЗМЕРИМ (№302, сторож ложного PASS на оси подачи): самое дорогое дерево окна (pid ${_W626_EVENT_PID}) ЕСТЬ дерево механизма введения события (${_W626_FORCE_UNIT}.service, ExecMainPID ${_W626_FORCE_MECH_PID}, ${_W626_FORCE_MECH_PRICE} алертов) — величина куста сложена из работы ЗАМЕРА, а не ноды, и печатать её ценой события ноды нельзя (память gate-value-can-be-entirely-measurer). Событие ноды стоило меньше, чем способ его вызвать: разбирать надо цену механизма, а не подпирать вердикт"
elif [ "$_w626_f8_alerts" -le 0 ]; then
    pass "6.2.9.F.8 ИЗМЕРЕНО: $_W626_FORCE_TARGET ФАКТИЧЕСКИ стартовал внутри окна ($(_w626_utc "$_w626_f8_start_e"), Result=$_w626_f8_res), и цена этого события = 0 алертов. Ноль ПРОДУКТОВЫЙ, а не приборный: факт действия снят независимо от счётчика алертов. Число сравнимо с репером Falco (№298: то же событие стоило Falco 0, нам 17) и требует разбора — событие ноды перестало детектироваться"
else
    pass "6.2.9.F.8 ИЗМЕРЕНО: событие ноды введено в окно НАМЕРЕННО — $_W626_FORCE_TARGET стартовал $(_w626_utc "$_w626_f8_start_e") (Result=$_w626_f8_res), цена = ${_w626_f8_alerts} алертов. Величина снята ПО ПОСТРОЕНИЮ, а не по фазе таймера: прошлые три прогона на этой ноде дали 28, 3 и 0 (№299). В межпрогонных сравнениях помечать как ФОРСИРОВАННУЮ — естественный тик может стоить иначе"
fi

# ---------------------------------------------------------------------------
# ITEM 5 (№268): ТРИ ПОДПУНКТА 6.2.6.1, ПОТЕРЯННЫЕ В 6.2.4.
#
# Постановка требует печатать (1) сторож нуля на четырёх правилах-двойниках
# №253, (2) ненулевой rule_exceptions_total по КАЖДОМУ из четырёх rule_id —
# доказательство, что объём ПЕРЕЕХАЛ в исключение, а не исчез, (3)
# exe_path_lookups_total{result} обеими границами. Без этого из вердикта
# 6.2.6.1 невозможно отличить «исключение задеплоено и работает» от
# «исключение не задеплоено вовсе» — ровно дефект №268.
# ---------------------------------------------------------------------------
echo "--- 6.2.6.1 подпункт (1)/(2), №268: сторож нуля + rule_exceptions_total на четырёх двойниках №253 ---"
if [ "$W626_LIB_OK" -eq 1 ]; then
    _w626_twin_out=$(w626_daemon_twin_exceptions "$W626_ART/metrics-window-start.txt" "$W626_ART/metrics-window-end.txt")
    printf '%s\n' "$_w626_twin_out" | sed 's/^/    /'
    printf '%s\n' "$_w626_twin_out" > "$W626_ART/daemon-twin-exceptions.txt"
    _w626_twin_zero=$(printf '%s\n' "$_w626_twin_out" | awk '$NF ~ /total=0$/' | grep -c . || true)
    if [ "${_w626_twin_zero:-0}" -gt 0 ]; then
        die "6.2.6.1 подпункт (1)/(2) ПРОВАЛЕН (№268): хотя бы один из четырёх двойников №253 дал НУЛЕВОЙ срез по ОБОИМ исключениям (verified-daemon-image + verified-daemon-lineage) за окно — исключение на нём выключено или не задеплоено, объём НЕ переехал, а исчез бесследно"
    else
        pass "6.2.6.1 подпункт (1)/(2) ДОСТИГНУТО (№268): все четыре двойника №253 дали ненулевой срез rule_exceptions_total за окно — объём переехал в исключение, а не пропал"
    fi
else
    die "6.2.6.1 подпункт (1)/(2) НЕИЗМЕРИМ: библиотека не подключилась"
fi

echo "--- 6.2.6.1 подпункт (3), №268: exe_path_lookups_total{result} обеими границами ---"
# ФОРМА СТРОКИ ПОСЛЕ ITEM 3. Метрика получила второй лейбл (field), и
# client_golang печатает лейблы ПО АЛФАВИТУ:
#   ebpf_guard_exe_path_lookups_total{field="exe_path",result="resolved"} N
# Прежний якорь `{result="resolved"}` (форма ДО item 3) не совпал бы с ней ни
# разу — подпункт объявил бы себя НЕИЗМЕРИМЫМ на каждом прогоне с
# задеплоенным item 3, то есть ровно тогда, когда он и должен измерять.
# Поэтому суммируется ЛЮБАЯ строка метрики с нужным result, независимо от
# наличия и порядка прочих лейблов; разрез по осям делает 6.2.6.15 ниже.
_w626_exe_sum() { # $1=файл среза $2=resolved|unresolved
    awk -v res="$2" '
        $0 ~ /^ebpf_guard_exe_path_lookups_total[{ ]/ && index($0, "result=\"" res "\"") { s += $NF; f = 1 }
        END { if (f) printf "%d", s+0; else printf "" }' "$1" 2>/dev/null
}
_w626_exe_res0=$(_w626_exe_sum "$W626_ART/metrics-window-start.txt" resolved)
_w626_exe_res1=$(_w626_exe_sum "$W626_ART/metrics-window-end.txt" resolved)
_w626_exe_unres0=$(_w626_exe_sum "$W626_ART/metrics-window-start.txt" unresolved)
_w626_exe_unres1=$(_w626_exe_sum "$W626_ART/metrics-window-end.txt" unresolved)
echo "  открытие: resolved=${_w626_exe_res0:-ОТСУТСТВУЕТ} unresolved=${_w626_exe_unres0:-ОТСУТСТВУЕТ}"
echo "  закрытие: resolved=${_w626_exe_res1:-ОТСУТСТВУЕТ} unresolved=${_w626_exe_unres1:-ОТСУТСТВУЕТ}"
if [ -z "${_w626_exe_res0:-}" ] || [ -z "${_w626_exe_res1:-}" ] || [ -z "${_w626_exe_unres0:-}" ] || [ -z "${_w626_exe_unres1:-}" ]; then
    die "6.2.6.1 подпункт (3) НЕИЗМЕРИМ (№268): серия ebpf_guard_exe_path_lookups_total{result} отсутствует хотя бы на одной границе окна"
else
    pass "6.2.6.1 подпункт (3) ДОСТИГНУТО (№268): exe_path_lookups_total{result} напечатан обеими границами окна"
fi

# ---------------------------------------------------------------------------
# ITEM 6 (№282, открытый вопрос 13) — подпункт (4) критерия 6.2.6.1: СТОРОЖ
# НА НОЛЬ ПО КАЖДОМУ ИЗ ВОСЬМИ НОВЫХ ИМЁН ИСКЛЮЧЕНИЙ.
#
# Item 6 сузил четыре file-правила восемью exceptions по идиоме
# node-host-daemon, но имена взяты из ПРОЛОГА архива 6.2.5: внутри границ
# окна стор не дал по этим правилам НИ ОДНОЙ строки (0 из 8). Отсюда два
# исхода, которые прогон обязан развести и которые НЕ различимы по величине
# 6.2.6.1:
#   • счётчик по имени НЕНУЛЕВОЙ — сужение адресно, объём переехал;
#   • счётчик по имени НУЛЕВОЙ — сужение не тронуло окно. Это провал
#     АДРЕСНОСТИ правки, а не самой правки (оконные алерты подняли другие
#     comm), и потому здесь НЕТ порога и НЕТ die: восемь нулей — законный
#     исход честного прогона, восемь молчаний прибора — нет.
# Вердикт подпункта — ИЗМЕРЕНО с поимённой печатью, ровно как требует
# [[positive-control-needs-result-sentinel]]: ноль обязан быть напечатан
# рядом с именем, а не выведен из отсутствия строки.
# ---------------------------------------------------------------------------
echo "--- 6.2.6.1 подпункт (4), №282/item 6: восемь новых исключений поимённо ---"
if [ "$W626_LIB_OK" -eq 1 ]; then
    _w626_i6=$(w626_item6_exceptions "$W626_ART/metrics-window-start.txt" "$W626_ART/metrics-window-end.txt")
    printf '%s\n' "$_w626_i6" | sed 's/^/    /'
    printf '%s\n' "$_w626_i6" > "$W626_ART/item6-exceptions.txt"
    _w626_i6_hit=$(printf '%s\n' "$_w626_i6" | awk '$NF != "delta=0"' | grep -c . || true)
    _w626_i6_sum=$(printf '%s\n' "$_w626_i6" | sed 's/.*delta=//' | awk '{s+=$1} END{printf "%d", s+0}')
    pass "6.2.6.1 подпункт (4) ИЗМЕРЕНО (№282, порог не назначается): ${_w626_i6_hit} из 8 имён item 6 сработали за окно, суммарно ${_w626_i6_sum} подавлений. Ноль по имени = сужение не тронуло окно (провал АДРЕСНОСТИ, оконные алерты подняли другие comm), а не выключенная правка — различить эти два исхода можно только этой поимённой печатью"
else
    die "6.2.6.1 подпункт (4) НЕИЗМЕРИМ (№282): библиотека не подключилась — восемь имён исключений item 6 не сняты, и адресность сужения по этому прогону не проверяется ничем"
fi

# ---------------------------------------------------------------------------
# ITEM 3/5 (№261/№277/№286, критерий 6.2.6.15). Доля величины на
# нерезолвленном образе — ПО ТРЁМ ОСЯМ РАЗДЕЛЬНО, порог не назначается (5.9.6).
#
# До item 3 счётчик не нёс лейбла поля, и «unresolved=375» архива 6.2.5 было
# СМЕСЬЮ двух разных гонок (№277). Постановка критерия требует трёх осей:
# exe_path, parent_exe_path, ancestor_exe_path.
#
# ДВА ОТСУТСТВИЯ ЧИТАЮТСЯ ПО-РАЗНОМУ, и это главное свойство блока:
#   • нет лейбла field вовсе        → item 3 НЕ задеплоен → критерий НЕИЗМЕРИМ;
#   • нет оси ancestor_exe_path     → item 5 НЕ задеплоен → критерий НЕИЗМЕРИМ;
#   • ось parent_exe_path НУЛЕВАЯ   → ШТАТНЫЙ исход (открытый вопрос 12): после
#     №286 все пять исключений verified-daemon-lineage читают ось предка, и
#     ноль по оси родителя означает «ось больше никем не используется», а не
#     поломку прибора. Печатается явно — иначе первый же разбор прочтёт его
#     как потерю.
# Оси НЕ складываются между собой: один и тот же алерт может дать по обращению
# на каждой, и «сумма unresolved» не была бы величиной ни для чего.
# ---------------------------------------------------------------------------
echo "--- 6.2.6.15: доля нерезолвленного образа ПО ТРЁМ ОСЯМ (№277 + №286) ---"
_w626_exe_frac=""
_w626_axes_ok=0
_w626_anc_axis=0
if [ "$W626_LIB_OK" -eq 1 ]; then
    _w626_exe_frac=$(w626_exe_path_lookup_fraction "$W626_ART/metrics-window-start.txt" "$W626_ART/metrics-window-end.txt")
    printf '%s\n' "$_w626_exe_frac" | sed 's/^/    /'
    printf '%s\n' "$_w626_exe_frac" > "$W626_ART/exe-path-axes.txt"
    printf '%s' "$_w626_exe_frac" | grep -q 'field=НЕТ_ЛЕЙБЛА' || _w626_axes_ok=1
    printf '%s' "$_w626_exe_frac" | grep -q '^field=ancestor_exe_path resolved=' && _w626_anc_axis=1
    _w626_par_line=$(printf '%s' "$_w626_exe_frac" | grep '^field=parent_exe_path ' || true)
    case "$_w626_par_line" in
        *"total=0"*) echo "    ↑ ось parent_exe_path нулевая — ШТАТНЫЙ исход (открытый вопрос 12): после №286 все verified-daemon-lineage читают ось предка, ось родителя осталась в контракте правил, но не используется. Это НЕ потеря прибора" ;;
    esac
else
    echo "  НЕИЗМЕРИМ: библиотека не подключилась"
fi
# Поимённый список comm тех алертов окна, чьё правило несёт исключение на
# exe_path/lineage (четыре двойника №253) — если он ПУСТ при ненулевой доле
# unresolved выше, ось применяется всюду, где нужна (постановка 6.2.6.15).
_w626_exe_exc_comms=$(jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" --argjson rules "$(printf '%s\n' $W626_TWIN_RULES | jq -R . | jq -s .)" '
    [ .[] | select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t0) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $t1))
      | select((.rule_id) as $r | ($rules|index($r))) ]
    | group_by(.comm)|map({c:.[0].comm,n:length})|sort_by(-.n)' "$W626_ART/alerts-window-end.json" 2>/dev/null)
echo "  алерты окна от правил с exe_path/lineage-исключением, поимённо по comm:"
echo "${_w626_exe_exc_comms:-[]}" | jq -r 'map("\(.c): \(.n)")|join(", ")' 2>/dev/null | sed 's/^/    /'
if [ "$(echo "${_w626_exe_exc_comms:-[]}" | jq 'length' 2>/dev/null)" = "0" ]; then
    # ПРАВКА №286. Прежняя редакция этой строки называла закрывающей осью
    # «parent_exe_path/lineage» — после №286 это утверждение ЛОЖНО: пять
    # исключений verified-daemon-lineage переведены на ось ПРЕДКА
    # (proc.ancestor_exe_path), а ось родителя больше не читается ни одним
    # правилом. Диагностика, называющая механизм, которого нет, — тот же
    # класс дефекта, что [[agent-logs-json-not-logfmt]], поэтому она теперь
    # называет ось по факту: по разбивке обходов (6.2.6.22, ниже).
    echo "  диагностика: список пуст — при ненулевой доле unresolved по оси exe_path выше это значит, что ось ПРЕДКА (proc.ancestor_exe_path, №286) закрывает то, что теряет гонку ось самого процесса. КАКИМ ИМЕННО хопом закрыла — печатает разбивка исходов обхода в 6.2.6.22 ниже (parent против ancestor), здесь это не выводится из нуля"
fi
if [ "$W626_LIB_OK" -ne 1 ]; then
    die "6.2.6.15 НЕИЗМЕРИМ: библиотека не подключилась — доли unresolved по осям и список правил-исключений не сняты"
elif [ "$_w626_axes_ok" -ne 1 ]; then
    die "6.2.6.15 НЕИЗМЕРИМ (№277): метрика exe_path_lookups_total пришла БЕЗ лейбла field — item 3 не задеплоен на стенде. Доля unresolved остаётся смесью двух гонок с разными причинами, ровно как на архиве 6.2.5 (375/6351 = 5,90%), и развилка №261 по ней закрывается гаданием"
elif [ "$_w626_anc_axis" -ne 1 ]; then
    die "6.2.6.15 НЕИЗМЕРИМ (№286): лейбл field есть, но оси ancestor_exe_path в срезе НЕТ — item 5 не задеплоен. Третья ось не измерена, и 6.2.6.22 по этому прогону не читается"
else
    pass "6.2.6.15 ИЗМЕРЕНО (диагностика гонки №261/№277/№286, порог не назначается, 5.9.6; оси НЕ складываются): $(printf '%s' "$_w626_exe_frac" | tr '\n' '; ')"
fi

# ---- Вердикт 6.2.6.1 (после решения 11.09.2026 — см. рамку ниже). Запас 1,5×
#      печатается СПРАВОЧНО: он был подпунктом порога в снятой единице и вместе
#      с ней перестал быть условием вердикта. Строка оставлена, чтобы реплеи
#      прошлых волн находили привычное число на привычном месте. ----
_w626_margin_abs=$(awk -v m="$W626_GATE_MARGIN" -v w="$W626_WINDOW" 'BEGIN{printf "%d", m*w/3600.0}')
echo "  запас гейта (справочно, единица снята): требовался ≤ ${W626_GATE_MARGIN}/ч (${_w626_margin_abs} алертов за окно $W626_WINDOW с), фактически ${_w626_vol_hour}/ч (${_w626_vol} за окно)"
# ─────────────────────────────────────────────────────────────────────────────
# РЕШЕНИЕ 11.09.2026 (item 6 волны 6.2.9.F, исход А): ЕДИНИЦА «АЛЕРТОВ/Ч» СНЯТА.
#
# Находка №297: величина получалась домножением оконного счёта на 3600/окно, а
# поток, который такое домножение предполагает, у ноды отсутствует — на обоих
# снятых архивах весь счёт лежал в 2-3 непустых секундах из 600. Сравнение
# такой величины с порогом судило расписание задач ноды и длину окна, а не
# продукт. Репер Falco (№298) добавил второе доказательство с другой стороны:
# сравнимой отраслевой величины в этой единице не существует вовсе, зато
# «сколько алертов стоит ОДНО рутинное действие ноды» сравнивается дословно —
# 0 у Falco против 17 у нас на одном и том же срабатывании motd-news.
#
# Что делает эта правка и чего НЕ делает:
#   • порог 100/ч НЕ понижается и НЕ повышается — постановка 6.2.9.F.7
#     запрещает двигать его под чужой замер. Он снимается как ЕДИНИЦА.
#   • величина (а) в алертах/ч по-прежнему СЧИТАЕТСЯ И ПЕЧАТАЕТСЯ — все реплеи
#     прошлых волн продолжают сверяться с ней;
#   • вердиктом 6.2.6.1 становится ИЗМЕРЕНО, а величиной куста — цена одного
#     события ноды (6.2.9.F.7). Порог новой величине в этой волне НЕ
#     назначается: правило 5.9.6 — впервые измеренной величине порог не даётся.
# ─────────────────────────────────────────────────────────────────────────────
_w626_gate_rel="в пределах снятого порога"
[ "$_w626_vol_hour" -gt "$W626_GATE" ] && _w626_gate_rel="ВЫШЕ снятого порога"
echo "  справочно (единица СНЯТА решением 11.09.2026, вердикт по ней НЕ выносится): величина (а) ${_w626_vol_hour}/ч — ${_w626_gate_rel} ${W626_GATE}/ч"
if [ "${_W626_TREE_SELF_OK:-1}" -eq 0 ] || [ "${_W626_EVENT_PRICE:-0}" -le 0 ]; then
    die "6.2.6.1 НЕИЗМЕРИМ (решение 11.09.2026): величиной куста стала цена ОДНОГО события ноды, а она на этом прогоне не снята (вердикт блока атрибуции по дереву выше) — нет среза алертов с деревом либо предикат «своё» недействителен. Величина (а) напечатана справочно (${_w626_vol_hour}/ч), но вердикта по ней больше не выносится: её единица снята находкой №297"
elif [ "$_w626_rl_n" -gt 0 ]; then
    pass "6.2.6.1 ИЗМЕРЕНО (порог новой величине не назначен, правило 5.9.6) — НИЖНЯЯ ОЦЕНКА: одно событие ноды «${_W626_EVENT_ROOT}» стоит ${_W626_EVENT_PRICE} алертов, но ${_w626_rl_n} правил имеют ненулевой срез лимитера за окно (список выше) — прибор упёрся, и настоящая цена события не меньше напечатанной. Внешний репер того же события (№298, Falco 0.44.1, 25 правил maturity_stable): 0 алертов. Величина (а) справочно ${_w626_vol_hour}/ч, величина (в) ${_w626_v_hour}/ч"
else
    pass "6.2.6.1 ИЗМЕРЕНО (порог новой величине не назначен, правило 5.9.6): одно событие ноды «${_W626_EVENT_ROOT}» стоит ${_W626_EVENT_PRICE} алертов, срез лимитера за окно нулевой — величина не упёрлась в потолок прибора. Внешний репер того же события (№298, Falco 0.44.1, 25 правил maturity_stable): 0 алертов. Величина (а) справочно ${_w626_vol_hour}/ч, величина (в) ${_w626_v_hour}/ч"
fi

# ═════════════════════════════════════════════════════════════════════════════
# 6.2.6.22 (№286, item 5) — ОСЬ ПРЕДКА СРАБОТАЛА И УТЕЧКА comm=cron НАЗВАНА
# ЧИСЛОМ. ТРИ ПОЛОВИНЫ, КОНЪЮНКТИВНО, КАЖДАЯ СО СВОЕЙ СТРОКОЙ.
#
# ЗАЧЕМ ОТДЕЛЬНАЯ МЕТКА. Ось proc.ancestor_exe_path во ВСЕХ исходах, кроме
# одного, ведёт себя ровно как старый parent_exe_path: хоп 1 берётся
# безусловно и совпадает с родителем. Отличить «правка задеплоена и работает»
# от «правка задеплоена и не сработала» можно РОВНО ОДНОЙ величиной —
# outcome="ancestor" (разрешение на хопе ≥2). Ноль по ней при ненулевых
# прочих исходах означает, что item 5 не дал того, ради чего сделан, и тогда
# 6.2.6.1 обязан объявить, что не понизился ИМЕННО по этой причине.
#
# ФОРМА ЗАПРЕЩЕНА elif ([[elif-verdict-masks-independent-halves]]): половины
# независимы, и провал (а) не имеет права погасить печать (б)/(в).
# ═════════════════════════════════════════════════════════════════════════════
echo "--- 6.2.6.22: ось предка сработала и утечка comm=cron названа числом (№286) ---"
_w626_t22_fails=""; _w626_t22_unmeas=""
_w626_anc_out=""
if [ "$W626_LIB_OK" -eq 1 ]; then
    _w626_anc_out=$(w626_ancestor_walk_by_outcome "$W626_ART/metrics-window-start.txt" "$W626_ART/metrics-window-end.txt")
    printf '%s\n' "$_w626_anc_out" | sed 's/^/    /'
    printf '%s\n' "$_w626_anc_out" > "$W626_ART/ancestor-walk-outcomes.txt"
fi
_w626_anc_val() { printf '%s\n' "${_w626_anc_out:-}" | awk -v o="$1" '$1 == "outcome=" o {for(i=1;i<=NF;i++) if($i ~ /^delta=/){sub("delta=","",$i); print $i; exit}}'; }
_w626_anc_a=$(_w626_anc_val ancestor)
_w626_anc_p=$(_w626_anc_val parent)
_w626_anc_nl=$(_w626_anc_val no_lineage)
_w626_anc_cb=$(_w626_anc_val comm_break)
_w626_anc_ex=$(_w626_anc_val exhausted)
_w626_anc_other=$(( ${_w626_anc_p:-0} + ${_w626_anc_nl:-0} + ${_w626_anc_cb:-0} + ${_w626_anc_ex:-0} ))

# ---- половина (а): единственная величина, отличающая работу от деплоя ----
if [ "$W626_LIB_OK" -ne 1 ]; then
    _w626_t22_unmeas="$_w626_t22_unmeas (а)"
    echo "  (а) ancestor за окно: НЕИЗМЕРИМА — библиотека не подключилась"
elif [ -z "${_w626_anc_a:-}" ]; then
    _w626_t22_unmeas="$_w626_t22_unmeas (а)"
    echo "  (а) ancestor за окно: НЕИЗМЕРИМА — серии ebpf_guard_exe_path_ancestor_walk_total нет в срезе, item 5 НЕ ЗАДЕПЛОЕН (это отличается от «ноль»: не задеплоено ≠ не сработало)"
elif [ "${_w626_anc_a:-0}" -gt 0 ]; then
    echo "  (а) ancestor за окно = ${_w626_anc_a} > 0 — ось предка разрешала образ на хопе ≥2, то есть делала то, чего parent_exe_path не умеет"
else
    _w626_t22_fails="$_w626_t22_fails (а)"
    echo "  (а) ПРОВАЛ: ancestor за окно = 0 при ${_w626_anc_other} обходах прочих исходов — ось задеплоена и НЕ СРАБОТАЛА ни разу; во всех этих исходах она неотличима от старого parent_exe_path, и величина 6.2.6.1 не понизилась ИМЕННО по этой причине"
fi

# ---- половина (б): полная разбивка, форма без порога ----
if [ -n "${_w626_anc_out:-}" ]; then
    echo "  (б) разбивка пяти исходов напечатана обеими границами (выше). comm_break=${_w626_anc_cb:-?} — доказательство, что антиспуф-условие ЖИВО и кого-то не пустило; no_lineage=${_w626_anc_nl:-?} — сколько раз трекер не знал pid (ненулевой при profiler.lineage.enabled=false, открытый вопрос 10(б)); exhausted=${_w626_anc_ex:-?} — сколько раз глубина 4 не хватило (открытый вопрос 10(в))"
else
    _w626_t22_unmeas="$_w626_t22_unmeas (б)"
    echo "  (б) НЕИЗМЕРИМА: разбивка исходов не снята"
fi

# ---- половина (в): утечка двойников с comm=cron, ПРЯМОЙ ДЕЛЬТОЙ ДВУХ МЕТРИК ----
# База 6.2.5 = 10 алертов за окно. Вход — метрика item 1 с осью comm, а НЕ
# стор ([[narrowing-input-must-be-metric-not-store]]: стор слеп к info и
# отстаёт от метрики; [[f6b-table-indexed-by-limiter-cut]]: строка таблицы
# индексирована срезом лимитера, поэтому её отсутствие ≠ ноль).
_w626_cron_leak=""
if [ "$W626_LIB_OK" -eq 1 ]; then
    _w626_cron_leak=$(w626_volume_by_source "$W626_ART/metrics-window-start.txt" "$W626_ART/metrics-window-end.txt" "$W626_TWIN_RULES" cron)
fi
_w626_cron_leak_n=$(printf '%s\n' "${_w626_cron_leak:-}" | awk '{s+=$3} END{printf "%d", s+0}')
_w626_vbs_any=$(awk '/^ebpf_guard_alert_volume_by_source_total\{/{f=1} END{print f+0}' "$W626_ART/metrics-window-end.txt" 2>/dev/null)
if [ "${_w626_vbs_any:-0}" -ne 1 ]; then
    _w626_t22_unmeas="$_w626_t22_unmeas (в)"
    echo "  (в) НЕИЗМЕРИМА: серии ebpf_guard_alert_volume_by_source_total нет — ось comm (item 1) не задеплоена или флаг exporter.volume_by_source выключен. Утечку нечем считать МЕТРИКОЙ, а сторовый счёт здесь запрещён по букве критерия"
elif [ "${_w626_cron_leak_n:-0}" -eq 0 ]; then
    echo "  (в) утечка двойников с comm=cron за окно = 0 против базы 6.2.5 = 10 — снята полностью, прямой дельтой двух метрик"
else
    _w626_t22_fails="$_w626_t22_fails (в)"
    echo "  (в) ПРОВАЛ: утечка двойников с comm=cron за окно = ${_w626_cron_leak_n} (база 6.2.5 = 10). После №286 ОСТАТОК ОЗНАЧАЕТ УЖЕ ДРУГУЮ ПРИЧИНУ, чем назвал разбор — поимённо:"
    printf '%s\n' "$_w626_cron_leak" | sed 's/^/      /'
    # Кортежи pid/ppid/comm по остатку — из стора, СПРАВОЧНО (величина уже
    # снята метрикой выше): без них следующий разбор снова начнётся с нуля.
    jq --argjson t0 "$_w626_t0" --argjson t1 "$_w626_t1" --argjson rules "$(printf '%s\n' $W626_TWIN_RULES | jq -R . | jq -s .)" -r '
        [ .[] | select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t0) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $t1))
          | select((.rule_id) as $r | ($rules|index($r))) | select(.comm == "cron")
          | "      \(.timestamp) rule=\(.rule_id) pid=\(.pid) ppid=\(.ppid // "?") comm=\(.comm)" ] | .[]' \
        "$W626_ART/alerts-window-end.json" 2>/dev/null | head -20
fi

if [ -n "${_w626_t22_fails:-}" ]; then
    die "6.2.6.22 ПРОВАЛЕН, половины:$_w626_t22_fails${_w626_t22_unmeas:+ НЕИЗМЕРИМЫ:$_w626_t22_unmeas} (см. строки выше — каждая половина судится сама, форма elif запрещена)"
elif [ -n "${_w626_t22_unmeas:-}" ]; then
    die "6.2.6.22 НЕИЗМЕРИМ, половины:$_w626_t22_unmeas"
else
    pass "6.2.6.22 ДОСТИГНУТО: (а) ancestor=${_w626_anc_a} > 0 — ось предка сработала на хопе ≥2; (б) все пять исходов напечатаны обеими границами (comm_break=${_w626_anc_cb}, no_lineage=${_w626_anc_nl}, exhausted=${_w626_anc_ex}); (в) утечка двойников comm=cron за окно = 0 против базы 6.2.5 = 10, прямой дельтой двух метрик"
fi

# ---- 6.2.6.9: потолок ресурсов против лимита чарта (№244) ----
echo "--- 6.2.6.9: ресурсы агента на открытии и закрытии окна против лимита чарта ---"
_w626_values="$W626_REPO/deploy/helm/ebpf-guard/values.yaml"
# Берётся limits.memory ПЕРВОГО блока resources (сам агент), а не limits
# сайдкаров/тестовых подов ниже по файлу.
_w626_limit_h=$(awk '
    /^resources:/ { inres=1; next }
    inres && /^[A-Za-z#]/ { exit }                      # блок кончился — дальше чужие resources
    inres && /^[[:space:]]+limits:/ { inlim=1; next }
    inres && inlim && /^[[:space:]]+[a-z]+:[[:space:]]*$/ { exit }   # начался requests:
    inres && inlim && /memory:/ { print $2; exit }' "$_w626_values" 2>/dev/null)
_w626_limit_b=$(awk -v v="${_w626_limit_h:-}" 'BEGIN{
    if (v ~ /Mi$/) { sub(/Mi$/,"",v); printf "%d", v*1024*1024 }
    else if (v ~ /Gi$/) { sub(/Gi$/,"",v); printf "%d", v*1024*1024*1024 }
    else if (v ~ /M$/) { sub(/M$/,"",v); printf "%d", v*1000*1000 }
    else printf "0" }')
_w626_res_print() { # $1=метка $2=файл среза
    echo "  ресурсы[$1]: RSS=$(awk -v b="$(_w626_metric_raw process_resident_memory_bytes "$2")" 'BEGIN{printf "%.1f МиБ", b/1048576}')" \
         "heap=$(awk -v b="$(_w626_metric_raw go_memstats_heap_alloc_bytes "$2")" 'BEGIN{printf "%.1f МиБ", b/1048576}')" \
         "goroutines=$(_w626_metric_raw go_goroutines "$2")" \
         "cpu_total=$(_w626_metric_raw process_cpu_seconds_total "$2")s"
}
_w626_res_print "открытие" "$W626_ART/metrics-window-start.txt"
_w626_res_print "закрытие" "$W626_ART/metrics-window-end.txt"
_w626_rss1=$(_w626_metric_raw process_resident_memory_bytes "$W626_ART/metrics-window-end.txt")
_w626_rss0=$(_w626_metric_raw process_resident_memory_bytes "$W626_ART/metrics-window-start.txt")
_w626_lat_sum0=$(awk '$1=="ebpf_guard_correlation_latency_seconds_sum"{printf "%.6f", $2+0}' "$W626_ART/metrics-window-start.txt")
_w626_lat_cnt0=$(awk '$1=="ebpf_guard_correlation_latency_seconds_count"{printf "%.0f", $2+0}' "$W626_ART/metrics-window-start.txt")
_w626_lat_sum1=$(awk '$1=="ebpf_guard_correlation_latency_seconds_sum"{printf "%.6f", $2+0}' "$W626_ART/metrics-window-end.txt")
_w626_lat_cnt1=$(awk '$1=="ebpf_guard_correlation_latency_seconds_count"{printf "%.0f", $2+0}' "$W626_ART/metrics-window-end.txt")
echo "  латентность корреляции ЗА ОКНО: $(awk -v s0="${_w626_lat_sum0:-0}" -v s1="${_w626_lat_sum1:-0}" -v c0="${_w626_lat_cnt0:-0}" -v c1="${_w626_lat_cnt1:-0}" 'BEGIN{d=c1-c0; if(d>0) printf "%.1f мкс/событие (Δsum=%.3fs ÷ Δcount=%d)", (s1-s0)/d*1e6, s1-s0, d; else printf "НЕИЗМЕРИМА (Δcount=%d)", d}')"
echo "  распределение по бакетам (накопительно, закрытие окна):"
awk '/^ebpf_guard_correlation_latency_seconds_bucket/{gsub(/.*le="/,"");gsub(/"}/," ");printf "    le=%s\n", $0}' "$W626_ART/metrics-window-end.txt" | head -12
echo "  лимит чарта (deploy/helm/ebpf-guard/values.yaml, resources.limits.memory): ${_w626_limit_h:-НЕ ПРОЧИТАН}"
if [ -z "${_w626_rss1:-}" ] || [ "${_w626_limit_b:-0}" -le 0 ]; then
    die "6.2.6.9 НЕИЗМЕРИМ: RSS=${_w626_rss1:-нет} или лимит чарта=${_w626_limit_h:-нет} не прочитаны — «запас до лимита» считать не от чего"
else
    echo "  запас до лимита на закрытии: $(awk -v l="$_w626_limit_b" -v r="$_w626_rss1" 'BEGIN{printf "%.1f МиБ (%.1f%%)", (l-r)/1048576, 100.0*(l-r)/l}')"
    echo "  рост RSS за окно: $(awk -v a="${_w626_rss0:-0}" -v b="$_w626_rss1" 'BEGIN{printf "%+.1f МиБ", (b-a)/1048576}')"
    if [ "${_w626_rss1:-0}" -gt "${_w626_limit_b:-0}" ]; then
        die "6.2.6.9 ПРОВАЛЕН: RSS $(awk -v r="$_w626_rss1" 'BEGIN{printf "%.1f", r/1048576}') МиБ ВЫШЕ лимита чарта ${_w626_limit_h}. В DaemonSet это OOM-kill, а не «чуть больше»"
    else
        pass "6.2.6.9 ДОСТИГНУТО: RSS $(awk -v r="$_w626_rss1" 'BEGIN{printf "%.1f", r/1048576}') МиБ ниже лимита чарта ${_w626_limit_h}; порог не назначается (запрет 5.9.6), величина печатается"
    fi
fi

# ---- 6.2.6.11, пассивная половина: приращение счётчика заморозки (№237) ----
echo "--- 6.2.6.11 (наблюдение): потолки базы дрейфа за окно ---"
_w626_maxw=$(echo "$_w626_drift_cfg" | grep -oE 'max_workloads:[[:space:]]*[0-9]+' | grep -oE '[0-9]+' | head -1)
_w626_maxsig=$(echo "$_w626_drift_cfg" | grep -oE 'max_signatures_per_workload:[[:space:]]*[0-9]+' | grep -oE '[0-9]+' | head -1)
_w626_prof=$(_w626_metric_sum ebpf_guard_drift_baseline_profiles "" "$W626_ART/metrics-window-end.txt")
_w626_evict=$(_w626_metric_sum ebpf_guard_drift_baseline_evictions_total "" "$W626_ART/metrics-window-end.txt")
# №237, дефект 2: вердикт по РАЗНОСТИ ДВУХ СНИМКОВ, а не по наличию имени
# метрики в выдаче (Prometheus печатает нулевые счётчики всегда).
_w626_cap0=$(_w626_metric_sum ebpf_guard_drift_baseline_signature_cap_reached_total "" "$W626_ART/metrics-window-start.txt")
_w626_cap1=$(_w626_metric_sum ebpf_guard_drift_baseline_signature_cap_reached_total "" "$W626_ART/metrics-window-end.txt")
# №237, дефект 1: журнал ограничен ОКНОМ, а не всей историей юнита.
_w626_frozen_j=$(journalctl -u "$W626_SVC" --since "@$_w626_t0" --until "@$_w626_t1" --no-pager 2>/dev/null | grep -c 'workload signature cap reached')
echo "  профилей=$_w626_prof при max_workloads=${_w626_maxw:-?}; вытеснений=$_w626_evict"
echo "  max_signatures_per_workload=${_w626_maxsig:-?}; приращение signature_cap_reached_total ЗА ОКНО: $(( _w626_cap1 - _w626_cap0 )) (накопительно $_w626_cap1)"
echo "  строк «signature cap reached» в журнале ЗА ОКНО: $_w626_frozen_j"
echo "  6.2.6.11 (пассивная половина): наблюдение без порога — при max_signatures=${_w626_maxsig:-?} кап в тихом окне достигаться и не обязан. Вердикт выносит позитивный подконтроль в конце прогона"

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.6.17 (№265, item 4 постановки) — `stuck`/`overdue` РАЗБИРАЮТСЯ ПОИМЁННО.
#
# Что чинится. Прогон 6.2.3 напечатал «13 нагрузок в stuck» и разобрать их
# поимённо было НЕЧЕМ: /metrics отдаёт три счётчика состояний, и «сколько» без
# «кто» не отличает слепое пятно продукта от нагрузки, которая просто ещё
# учится (память drift-baseline-has-no-per-workload-observability). Здесь
# читаются ОБЕ границы окна из /debug/state (боковой разрез существует с
# волны 6.0b) плюс ЖУРНАЛ: item 4 этой волны добавил в продукт строку на
# КАЖДЫЙ переход в stuck с именем нагрузки (logNewlyStuckWorkloads,
# internal/profiler/driftbaseline.go) — раньше переход был чистой функцией
# времени и не отмечался ничем (память drift-stuck-is-lazily-evaluated), из-за
# чего «0 → 2 за десять тихих минут» нельзя было привязать к нагрузкам.
#
# ПОРОГ НЕ НАЗНАЧАЕТСЯ (5.9.6): критерий требует НАЗВАТЬ нагрузки, а не
# уложиться в число. Невозможность назвать = НЕИЗМЕРИМ.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.6.17: stuck/overdue поимённо на обеих границах окна (№265) ---"
_w626_drift_names() { # $1=файл снимка /debug/state $2=состояние
    jq -r --arg st "$2" '[.drift_baseline.workloads[]? | select(.state==$st)
        | "\(.comm)(sig=\(.signatures),smp=\(.samples))"] | sort | join(" ")' "$1" 2>/dev/null
}
_w626_drift_rows() { # $1=файл снимка — сколько строк вообще пришло
    jq -r '[.drift_baseline.workloads[]?] | length' "$1" 2>/dev/null
}
_w626_ds0="$W626_ART/debug-state-window-start.json"
_w626_ds1="$W626_ART/debug-state-window-end.json"
_w626_ds_rows0=$(_w626_drift_rows "$_w626_ds0"); _w626_ds_rows1=$(_w626_drift_rows "$_w626_ds1")
if [ -z "${_w626_ds_rows0:-}" ] || [ -z "${_w626_ds_rows1:-}" ] || [ "${_w626_ds_rows0:-0}" -lt 1 ] || [ "${_w626_ds_rows1:-0}" -lt 1 ]; then
    die "6.2.6.17 НЕИЗМЕРИМ: /debug/state не отдал разрез drift_baseline.workloads хотя бы на одной границе окна (строк: открытие=${_w626_ds_rows0:-нет}, закрытие=${_w626_ds_rows1:-нет}) — назвать нагрузки в stuck/overdue нечем, а счётчик без имён этот критерий не закрывает (server.enable_debug выключен либо profiler.drift_baseline отключён)"
else
    for _w626_st in learning stuck overdue enforcing; do
        echo "  [$_w626_st] открытие: $(_w626_drift_names "$_w626_ds0" "$_w626_st" | cut -c1-400)"
        echo "  [$_w626_st] закрытие: $(_w626_drift_names "$_w626_ds1" "$_w626_st" | cut -c1-400)"
    done
    # Переходы ВНУТРИ тихого окна — из журнала, поимённо (item 4).
    #
    # ПРОГОН 6.2.6 (08.09.2026): здесь разбор искал LOGFMT (`workload=cron`), а
    # агент пишет JSON (`"workload":"cron"`), и критерий объявил РАБОТАЮЩУЮ
    # правку item 4 «не задеплоенной». В журнале прогона при этом лежало 47
    # именных переходов, из них РОВНО 6 внутри окна — в точности тот рост, о
    # котором вердикт сказал «не разбирается поимённо». Ноль был приборным,
    # а причина в вердикте — выдуманной. Разбор понимает обе формы: JSON —
    # рабочая, logfmt — на случай смены хендлера логгера.
    _w626_stuck_j=$(journalctl -u "$W626_SVC" --since "@$_w626_t0" --until "@$_w626_t1" --no-pager 2>/dev/null \
        | grep 'entering stuck (blind spot)' \
        | grep -oE '"workload":"[^"]+"|workload=[^ ,}]+' \
        | sed 's/^"workload":"//; s/"$//; s/^workload=//' | sort | uniq -c | awk '{printf "%s×%s ", $1, $2}')
    _w626_stuck_m0=$(_w626_metric_sum ebpf_guard_drift_baseline_stuck_learning_workloads "" "$W626_ART/metrics-window-start.txt")
    _w626_stuck_m1=$(_w626_metric_sum ebpf_guard_drift_baseline_stuck_learning_workloads "" "$W626_ART/metrics-window-end.txt")
    echo "  переходы в stuck ВНУТРИ окна (журнал, поимённо): ${_w626_stuck_j:-нет}"
    echo "  сверка с метрикой: stuck_learning_workloads открытие=$_w626_stuck_m0 закрытие=$_w626_stuck_m1 (дельта $(( _w626_stuck_m1 - _w626_stuck_m0 )))"
    _w626_stuck_n1=$(jq -r '[.drift_baseline.workloads[]? | select(.state=="stuck")] | length' "$_w626_ds1" 2>/dev/null)
    if [ "${_w626_stuck_m1:-0}" -gt 0 ] && [ "${_w626_stuck_n1:-0}" -eq 0 ]; then
        die "6.2.6.17 НЕИЗМЕРИМ: метрика показывает ${_w626_stuck_m1} нагрузок в stuck на закрытии окна, а поимённый разрез /debug/state — ни одной. Прибор расходится сам с собой, и «кто» по-прежнему неизвестно"
    elif [ "$(( _w626_stuck_m1 - _w626_stuck_m0 ))" -gt 0 ] && [ -z "${_w626_stuck_j:-}" ]; then
        die "6.2.6.17 НЕИЗМЕРИМ: stuck вырос на $(( _w626_stuck_m1 - _w626_stuck_m0 )) внутри окна, а ни один ИМЕННОЙ переход в журнале не напечатан — правка item 4 (logNewlyStuckWorkloads) не задеплоена, и рост снова не разбирается поимённо (ровно форма находки №265)"
    else
        pass "6.2.6.17 ИЗМЕРЕНО (порог не назначается, 5.9.6): на закрытии окна в stuck ${_w626_stuck_n1:-0} нагрузок поимённо, переходы внутри окна: ${_w626_stuck_j:-нет}"
    fi
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.4.12 (долг 6.2.4, метка сохранена) — ВРЕМЯ ДО ЗАМОРОЗКИ НА БОЕВОМ КАПЕ.
#
# Наблюдение без порога (5.9.6). Позитивный подконтроль 6.2.6.11 в конце
# прогона ПОНИЖАЕТ max_signatures_per_workload до 3 и доказывает, что
# счётчик движется; этот критерий — о другом: на БОЕВОМ капе (256) —
# сколько времени проходит от старта агента до первой заморозки и КАКИЕ
# нагрузки замерзают. Читается ДО подконтроля, иначе величина принадлежала
# бы капу 3, а не боевому.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.4.12: время до заморозки на боевом капе max_signatures=${_w626_maxsig:-?} (без порога) ---"
_w626_agent_epoch=$(cat /root/agent-start-6.2.6.epoch 2>/dev/null)
_w626_cap_first=$(journalctl -u "$W626_SVC" --since "$(_w626_journal_since)" --no-pager -o short-unix 2>/dev/null \
    | grep -m1 'workload signature cap reached' | awk '{printf "%d", $1}')
_w626_cap_names=$(journalctl -u "$W626_SVC" --since "$(_w626_journal_since)" --no-pager 2>/dev/null \
    | grep 'workload signature cap reached' \
    | grep -oE '"workload":"[^"]+"|workload=[^ ,}]+' \
    | sed 's/^"workload":"//; s/"$//; s/^workload=//' | sort -u | tr '\n' ' ')
_w626_cap_metric=$(awk '/^ebpf_guard_drift_baseline_signature_cap_reached_total\{/{
        if (match($0, /comm="[^"]*"/)) printf "%s=%s ", substr($0, RSTART+6, RLENGTH-7), $NF }' \
    "$W626_ART/metrics-window-end.txt" 2>/dev/null)
_w626_sat_names=$(jq -r '[.drift_baseline.workloads[]? | select(.saturated==true) | .comm] | sort | join(" ")' "$_w626_ds1" 2>/dev/null)
echo "  замороженные нагрузки по метрике (comm=приращений): ${_w626_cap_metric:-нет}"
echo "  замороженные нагрузки по /debug/state на закрытии окна (saturated=true): ${_w626_sat_names:-нет}"
echo "  имена из журнала за прогон: ${_w626_cap_names:-нет}"
if [ -z "${_w626_maxsig:-}" ]; then
    die "6.2.4.12 НЕИЗМЕРИМ: max_signatures_per_workload не прочитан из $_w626_cfg — «боевой кап» назвать нечем, и величина принадлежала бы неизвестному потолку"
elif [ -z "${_w626_cap_first:-}" ]; then
    pass "6.2.4.12 ИЗМЕРЕНО (порог не назначается, 5.9.6): при боевом капе ${_w626_maxsig} за прогон (пролог+окно) НИ ОДНА нагрузка не заморозилась — время до заморозки больше длины прогона. Это величина, а не провал: порог этому критерию не назначен"
else
    pass "6.2.4.12 ИЗМЕРЕНО (порог не назначается, 5.9.6): при боевом капе ${_w626_maxsig} первая заморозка через $(( _w626_cap_first - ${_w626_agent_epoch:-_w626_cap_first} ))s после старта агента; замороженные нагрузки: ${_w626_cap_names:-нет}"
fi

# ---- 6.2.2.6, живая половина «фон молчит» ----
echo "--- 6.2.2.6 (живая половина 1/2): три правки условий на РЕАЛЬНОМ фоне ноды ---"
for _r in c2_periodic_beacon_pattern beacon_fixed_interval sigma_iptables_flush sigma_log_deletion; do
    _a0=$(_w626_metric_sum ebpf_guard_alerts_total "$_r" "$W626_ART/metrics-window-start.txt")
    _a1=$(_w626_metric_sum ebpf_guard_alerts_total "$_r" "$W626_ART/metrics-window-end.txt")
    _f0=$(_w626_metric_sum ebpf_guard_alerts_filtered_total "$_r" "$W626_ART/metrics-window-start.txt")
    _f1=$(_w626_metric_sum ebpf_guard_alerts_filtered_total "$_r" "$W626_ART/metrics-window-end.txt")
    _rl0=$(_w626_ratelimited "$_r" "$W626_ART/metrics-window-start.txt")
    _rl1=$(_w626_ratelimited "$_r" "$W626_ART/metrics-window-end.txt")
    echo "    $_r: за окно всего $(( (_a1 - _a0) + (_f1 - _f0) )) (экспортировано $(( _a1 - _a0 )), срезано min_severity $(( _f1 - _f0 )), срез лимитера $(( _rl1 - _rl0 )))"
done
echo "    (на окне 6.2.1 c2_periodic_beacon_pattern дал 602 — 71% всей величины прогона)"

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.6.8 ОКНО ПРОФИЛЯ (№244). ОТДЕЛЬНОЕ окно, сразу ПОСЛЕ окна объёма:
# `curl /debug/pprof/profile?seconds=30` — действие измерителя, и внутри окна
# объёма оно нарушило бы 6.2.6.3.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.6.8: окно профиля ${W626_PROFILE_SECS}s (ОТДЕЛЬНОЕ, после окна объёма) ---"
mkdir -p "$W626_ART/profile" 2>/dev/null
_w626_pcpu0=$(_w626_metric_raw process_cpu_seconds_total "$W626_ART/metrics-window-end.txt")
_w626_pt0=$(_w626_epoch)
# СОБСТВЕННЫЙ ТАЙМАУТ, а не общий. `_w626_curl` несёт --max-time 30, и запрос
# профиля на 30 с в него НЕ УКЛАДЫВАЕТСЯ по построению: сервер держит
# соединение ровно PROFILE_SECS и только потом отдаёт тело. Прогон 06.09.2026
# привёз из-за этого cpu.pprof НУЛЕВОГО РАЗМЕРА при исправном pprof (смок на
# 5 с проходил — дефект виден только на боевой длине окна).
curl -s --max-time "$(( W626_PROFILE_SECS + 60 ))" -H "Authorization: Bearer $W626_TOKEN" \
    "$W626_API/debug/pprof/profile?seconds=$W626_PROFILE_SECS" > "$W626_ART/profile/cpu.pprof" 2>/dev/null
_w626_curl "$W626_API/debug/pprof/heap" > "$W626_ART/profile/heap.pprof" 2>/dev/null
_w626_curl "$W626_API/debug/pprof/goroutine?debug=1" > "$W626_ART/profile/goroutine.txt" 2>/dev/null
_w626_metrics > "$W626_ART/profile/metrics-profile-end.txt"
_w626_pt1=$(_w626_epoch)
_w626_pcpu1=$(_w626_metric_raw process_cpu_seconds_total "$W626_ART/profile/metrics-profile-end.txt")
_w626_psize=$(wc -c < "$W626_ART/profile/cpu.pprof" 2>/dev/null | tr -d ' ')
echo "  профиль снят: cpu.pprof ${_w626_psize:-0} байт, heap.pprof $(wc -c < "$W626_ART/profile/heap.pprof" 2>/dev/null | tr -d ' ') байт"
echo "  дельта process_cpu_seconds_total за окно профиля: $(awk -v a="${_w626_pcpu0:-0}" -v b="${_w626_pcpu1:-0}" -v t="$(( _w626_pt1 - _w626_pt0 ))" 'BEGIN{if(t>0) printf "%.2f с за %d с = %.1f%% ядра", b-a, t, 100.0*(b-a)/t; else printf "НЕИЗМЕРИМА"}')"
if [ "${_w626_psize:-0}" -lt 1000 ]; then
    die "6.2.6.8 ПРОВАЛЕН: профиль не снят (cpu.pprof ${_w626_psize:-0} байт). «34% ядра» без разбора — не величина, а незнание (находка №244); отсутствие профиля в архиве есть провал критерия, а не оговорка"
else
    echo "  top-10 функций по CPU:"
    if [ -x "$W626_GO" ]; then
        "$W626_GO" tool pprof -top -nodecount=10 "$W626_REPO/build/ebpf-guard" "$W626_ART/profile/cpu.pprof" 2>/dev/null \
            | tee "$W626_ART/profile/top10.txt" | sed 's/^/    /'
    fi
    if [ -s "$W626_ART/profile/top10.txt" ]; then
        pass "6.2.6.8 ДОСТИГНУТО: профиль снят в отдельном окне и разобран top-10 (порог не назначается — запрет 5.9.6)"
    else
        die "6.2.6.8 ПРОВАЛЕН (половина «разбор»): профиль снят (${_w626_psize} байт), но top-10 не построен — go tool pprof недоступен ($W626_GO) или бинарь $W626_REPO/build/ebpf-guard не совпал с профилем. Профиль без разбора вердикта не даёт"
    fi
fi

# ─────────────────────────────────────────────────────────────────────────────
# ВХОД ПОДАЁТСЯ ЗДЕСЬ, ПОСЛЕ ОБОИХ ОКОН (память
# control-after-attacks-hits-filled-limiter).
#
# №251, ГРАНИЦА ФАЗЫ АТАК (начало). Все позитивные контроли и инъекции ниже —
# до самого критерия 6.2.3.7 — есть штатное поведение ЭТОГО прогона
# (host-token-read, pod-token-probe, churn, инъекции 6.2.2.6), а не атака.
# Инцидент инцидентного слоя, чей корень — нодовый актор или сам измеритель
# и чьё время попадает в [attack_phase_start, attack_phase_end], есть
# ОЖИДАЕМЫЙ true positive; вне этого интервала — засчитывается как ложь.
# ─────────────────────────────────────────────────────────────────────────────
_w626_attack_phase_start=$(_w626_epoch)
echo "--- 6.2.1.2 (регрессия): сторож слепоты лимитера (хостовое чтение токена пода) ---"
W626_HOSTCAT_PODDED=0
if [ "$W626_INSTRUMENTED" -eq 1 ]; then
    _w626_target=$(find /var/lib/kubelet/pods -maxdepth 6 -type f -name token 2>/dev/null | head -1)
    [ -z "$_w626_target" ] && _w626_target=$(find /var/lib/kubelet/pods -maxdepth 4 -type f 2>/dev/null | head -1)
    if [ -z "$_w626_target" ]; then
        die "6.2.1.2 НЕИЗМЕРИМ: под /var/lib/kubelet/pods нет ни одного файла — хостовую половину нечем подать, ноль был бы приборным"
    else
        _w626_hrl0=$(_w626_ratelimited "$W626_HOST_RULES")
        cp /bin/cat /usr/local/bin/w626hostcat 2>/dev/null
        _w626_tn=$(_w626_epoch)
        _w626_bytes=$(/usr/local/bin/w626hostcat "$_w626_target" 2>/dev/null | wc -c)
        _w626_hits=0; _w626_waited=0
        while [ "$_w626_waited" -lt "$W626_POS_TIMEOUT" ]; do
            sleep "$W626_SETTLE"; _w626_waited=$(( _w626_waited + W626_SETTLE ))
            _w626_hits=$(_w626_alerts | jq --argjson t "$_w626_tn" --arg ids "$W626_HOST_RULES" \
                '[.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.comm=="w626hostcat") and (.rule_id as $r|($ids|split(" "))|index($r)))]|length' 2>/dev/null || echo 0)
            [ "${_w626_hits:-0}" -gt 0 ] && break
        done
        _w626_hrl1=$(_w626_ratelimited "$W626_HOST_RULES")
        _w626_all=$(_w626_alerts | jq --argjson t "$_w626_tn" '[.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.comm=="w626hostcat"))]|length' 2>/dev/null || echo 0)
        _w626_rules=$(_w626_alerts | jq -r --argjson t "$_w626_tn" '.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.comm=="w626hostcat"))|.rule_id' 2>/dev/null | sort -u | tr '\n' ' ')
        echo "  сторож результата: прочитано байт = $_w626_bytes (цель $_w626_target)"
        echo "  алертов от comm=w626hostcat: всего $_w626_all (правила: ${_w626_rules:-нет}); из них обязательных: $_w626_hits"
        echo "  срез лимитера обязательных правил за время контроля: $(( _w626_hrl1 - _w626_hrl0 ))"
        if [ "${_w626_bytes:-0}" -lt 1 ]; then
            die "6.2.1.2 НЕИЗМЕРИМ: хостовой читатель ничего не прочитал (байт=$_w626_bytes) — ноль приборный (память positive-control-needs-result-sentinel)"
        elif [ "${_w626_hits:-0}" -lt 1 ] && [ "$(( _w626_hrl1 - _w626_hrl0 ))" -gt 0 ]; then
            die "6.2.1.2 ПРОВАЛЕН (шум→слепота, регресс находки №221): хост прочитал токен ($_w626_bytes байт), обязательные правила не поднялись, И их лимитер срезал $(( _w626_hrl1 - _w626_hrl0 )) срабатываний"
        elif [ "${_w626_hits:-0}" -lt 1 ]; then
            die "6.2.1.2 ПРОВАЛЕН (детекта нет): хост прочитал токен пода ($_w626_bytes байт), обязательные правила не поднялись, лимитер их НЕ срезал"
        else
            pass "6.2.1.2 ДОСТИГНУТО: хостовое чтение токена пода подняло $_w626_hits обязательных алертов (${_w626_rules})"
        fi
        W626_HOSTCAT_PODDED=$(_w626_alerts | jq --argjson t "$_w626_tn" '[.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.comm=="w626hostcat") and ((.enrichment.pod_name // "")!=""))]|length' 2>/dev/null || echo 0)
        rm -f /usr/local/bin/w626hostcat 2>/dev/null
    fi
else
    echo "  ПРОПУЩЕН: 6.2.6.0 не взят"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.1.3 (регрессия) НЕГАТИВНЫЙ КОНТРОЛЬ НА ПОЛНОМ ОБЪЁМЕ (находка №227).
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.1.3 (регрессия): негативный контроль на полном объёме ---"
if [ "$W626_INSTRUMENTED" -eq 1 ]; then
    _w626_alerts > "$W626_ART/alerts-negative.json"
    echo "  comm, у которых ХОТЬ ОДИН алерт несёт pod_name (это обязаны быть только поды):"
    jq -r '[.[]|select((.enrichment.pod_name // "")!="")]|group_by(.comm)|map({c:.[0].comm,n:length})|sort_by(-.n)[]|"    \(.c): \(.n)"' "$W626_ART/alerts-negative.json" 2>/dev/null | head -20
    _w626_bad=$(jq -r '[.[]|select(((.enrichment.pod_name // "")!="") and ((.enrichment.container_id // "")==""))]|length' "$W626_ART/alerts-negative.json" 2>/dev/null || echo 0)
    _w626_hostpodded=$(jq -r --arg h "k3s-server iptables ip6tables systemd sshd cron kubectl systemd-logind" \
        '[.[]|select(((.enrichment.pod_name // "")!="") and ((.comm) as $c|($h|split(" "))|index($c)))]|length' "$W626_ART/alerts-negative.json" 2>/dev/null || echo 0)
    echo "  алертов с pod_name БЕЗ container_id: $_w626_bad"
    echo "  алертов с pod_name у заведомо хостовых comm: $_w626_hostpodded"
    echo "  алертов с pod_name у контрольного хостового читателя: ${W626_HOSTCAT_PODDED:-0}"
    if [ "${_w626_hostpodded:-0}" -gt 0 ] || [ "${W626_HOSTCAT_PODDED:-0}" -gt 0 ] || [ "${_w626_bad:-0}" -gt 0 ]; then
        die "6.2.1.3 ПРОВАЛЕН: хостовые процессы получили ЧУЖУЮ личность пода (хостовые comm: $_w626_hostpodded, без container_id: $_w626_bad, контрольный читатель: ${W626_HOSTCAT_PODDED:-0})"
    else
        pass "6.2.1.3 ДОСТИГНУТО: ни один хостовой процесс не получил личность пода"
    fi
else
    echo "  ПРОПУЩЕН: 6.2.6.0 не взят"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.1.2b (регрессия) ПОЗИТИВНЫЙ КОНТРОЛЬ ОСИ ПОДА.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.1.2b (регрессия): под читает свой SA-токен ---"
if [ "$W626_INSTRUMENTED" -eq 1 ]; then
    "$W626_KUBECTL" create namespace "$W626_NS" --dry-run=client -o yaml 2>/dev/null | "$W626_KUBECTL" apply -f - >/dev/null 2>&1
    "$W626_KUBECTL" -n "$W626_NS" delete pod w626-token-probe --ignore-not-found --wait=true >/dev/null 2>&1
    cat > "$W626_ART/w626-token-probe.yaml" <<'YAML'
apiVersion: v1
kind: Pod
metadata:
  name: w626-token-probe
  labels:
    app: w626-token-probe
spec:
  restartPolicy: Never
  containers:
  - name: probe
    image: busybox:1.36
    command: ["sh","-c"]
    args:
      - |
        i=0
        while [ $i -lt 30 ]; do
          read t < /run/secrets/kubernetes.io/serviceaccount/token
          echo "W624-SENTINEL opener_comm=$(cat /proc/$$/comm) token_head=$(echo "$t" | cut -c1-12) token_len=${#t}"
          i=$((i+1)); sleep 2
        done
    volumeMounts:
    - name: satoken
      mountPath: /run/secrets/kubernetes.io/serviceaccount
      readOnly: true
  volumes:
  - name: satoken
    projected:
      sources:
      - serviceAccountToken:
          path: token
YAML
    _w626_tp=$(_w626_epoch)
    "$W626_KUBECTL" -n "$W626_NS" apply -f "$W626_ART/w626-token-probe.yaml" >/dev/null 2>&1
    "$W626_KUBECTL" -n "$W626_NS" wait --for=condition=Ready pod/w626-token-probe --timeout=90s >/dev/null 2>&1
    _w626_pdelta=0; _w626_waited=0
    while [ "$_w626_waited" -lt "$W626_POS_TIMEOUT" ]; do
        sleep "$W626_SETTLE"; _w626_waited=$(( _w626_waited + W626_SETTLE ))
        _w626_pdelta=$(_w626_alerts | jq --arg ids "$W626_K8S_RULES" --argjson t "$_w626_tp" \
            '[.[]|select((.rule_id as $r|($ids|split(" "))|index($r)) and ((.enrichment.pod_name // "")=="w626-token-probe") and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t))]|length' 2>/dev/null || echo 0)
        [ "${_w626_pdelta:-0}" -gt 0 ] && break
    done
    _w626_sent=$("$W626_KUBECTL" -n "$W626_NS" logs w626-token-probe 2>/dev/null | grep -m1 'W624-SENTINEL')
    _w626_phit=$(_w626_alerts | jq -r --arg ids "$W626_K8S_RULES" --argjson t "$_w626_tp" \
        '.[]|select((.rule_id as $r|($ids|split(" "))|index($r)) and ((.enrichment.pod_name // "")=="w626-token-probe") and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t))|.rule_id' 2>/dev/null | sort -u | tr '\n' ' ')
    echo "  ожидание записи в стор: ${_w626_waited}s"
    echo "  сторож результата: ${_w626_sent:-НЕ НАПЕЧАТАН}"
    echo "  алертов с pod_name=w626-token-probe: $_w626_pdelta (правила: ${_w626_phit:-нет})"
    _w626_len=$(printf '%s' "${_w626_sent:-}" | grep -oE 'token_len=[0-9]+' | cut -d= -f2)
    if [ -z "${_w626_len:-}" ] || [ "${_w626_len:-0}" -lt 100 ]; then
        die "6.2.1.2b НЕИЗМЕРИМ: сторож результата не напечатал прочитанный токен (token_len=${_w626_len:-нет}) — ноль правил приборный"
    elif [ "$_w626_pdelta" -lt 1 ]; then
        die "6.2.1.2b ПРОВАЛЕН: под прочитал токен (token_len=$_w626_len), а правила ${W626_K8S_RULES} не поднялись с его именем"
    else
        pass "6.2.1.2b ДОСТИГНУТО: чтение SA-токена подом подтверждено сторожем (token_len=$_w626_len) и подняло $_w626_pdelta алертов С ИМЕНЕМ ПОДА (${_w626_phit})"
    fi
else
    echo "  ПРОПУЩЕН: 6.2.6.0 не взят"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.6.10 ЦЕНА СТАРТА ПОДА — С ПОРОГОМ (№236).
# Порог 45/под = ceil(36 × 1.25): 36 измерено прогоном 6.2.1 (108 алертов на
# 3 оборота), 25% запаса на то, что величина снята ОДНИМ прогоном.
# Бюджет ОТДЕЛЬНЫЙ от 6.2.6.1: окна физически не пересекаются (churn идёт
# после тихого окна). Вопрос «как боевой часовой гейт учитывает непрерывный
# churn» этим порогом НЕ закрыт и остаётся открытым (пункт 10 plan.md).
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.6.10: цена одного старта пода, порог ${W626_CHURN_BUDGET}/под ---"
if [ "$W626_INSTRUMENTED" -eq 1 ]; then
    _w626_tc=$(_w626_epoch)
    # ITEM 3 (№263): фаза стартов подов ЭТОГО контроля объявляется ТРЕТЬИМ
    # именованным окном, рядом с [t0,t1] (тихое окно объёма) и
    # [attack_phase_start, attack_phase_end] (окно позитивных контролей).
    # Постановка 6.2.4.6 требует «ноль инцидентов с корнем нодового актора ЗА
    # ПРОГОН ЦЕЛИКОМ», а контроль 6.2.6.10 обязан подать 3 старта пода — то
    # есть по построению произвести containerd-shim/runc-инциденты, которых
    # 6.2.4.6 не имеет права прощать фазой атак (в этом и отличие от старого
    # 6.2.3.7). Противоречие снимается вычитанием ИМЕННО этого окна:
    # инцидент внутри него печатается ОТДЕЛЬНОЙ строкой и в вердикт не идёт,
    # тот же корень вне его — засчитывается.
    _w626_pod_start_phase_start=$_w626_tc
    _w626_metrics > "$W626_ART/metrics-podstart-start.txt"
    for i in $(seq 1 "$W626_CHURN"); do
        "$W626_KUBECTL" -n "$W626_NS" run "w626-churn-$i" --image=busybox:1.36 --restart=Never --command -- sleep 15 >/dev/null 2>&1
    done
    sleep 45
    for i in $(seq 1 "$W626_CHURN"); do "$W626_KUBECTL" -n "$W626_NS" delete pod "w626-churn-$i" --ignore-not-found --wait=false >/dev/null 2>&1; done
    sleep $(( W626_SETTLE * 3 ))
    _w626_pod_start_phase_end=$(_w626_epoch)
    _w626_metrics > "$W626_ART/metrics-podstart-end.txt"
    _w626_alerts > "$W626_ART/alerts-churn-end.json"
    _w626_churn=$(jq --argjson t "$_w626_tc" '[.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.comm|test("^(runc|containerd|conmon|crun|dockerd|pause)")))]' "$W626_ART/alerts-churn-end.json" 2>/dev/null)
    _w626_cn=$(echo "${_w626_churn:-[]}" | jq 'length' 2>/dev/null); _w626_cn=${_w626_cn:-0}
    _w626_per=$(awk -v n="$_w626_cn" -v p="$W626_CHURN" 'BEGIN{printf "%.1f", (p>0? n/p : 0)}')
    echo "  запущено и снято подов: $W626_CHURN; алертов от рантайм-comm: $_w626_cn → $_w626_per на под (порог ${W626_CHURN_BUDGET})"
    echo "${_w626_churn:-[]}" | jq -r 'group_by(.rule_id)|map({r:.[0].rule_id,n:length})|sort_by(-.n)[]|"    \(.r): \(.n)"' 2>/dev/null | head -25
    _w626_submission_loss_guard "старты подов" "$W626_ART/metrics-podstart-start.txt" "$W626_ART/metrics-podstart-end.txt"
    _w626_podstart_loss_suffix=""
    [ "${_W626_LOSS_NONZERO:-0}" -eq 1 ] && _w626_podstart_loss_suffix=" — НИЖНЯЯ ОЦЕНКА (6.2.9.F.4, №294): потери внутри окна подачи = ${_W626_LOSS_LAST} событий, разбивка выше"
    if awk -v v="$_w626_per" -v b="$W626_CHURN_BUDGET" 'BEGIN{exit !(v > b)}'; then
        die "6.2.6.10 ПРОВАЛЕН: старт пода стоит $_w626_per алертов при бюджете ${W626_CHURN_BUDGET}/под (36 × 1.25, №236). Глушить по comm=runc нельзя — это ровно те правила, что обязаны ловить контейнерный побег; чинится сужением условий, а не исключением${_w626_podstart_loss_suffix}"
    else
        pass "6.2.6.10 ДОСТИГНУТО: старт пода стоит $_w626_per алертов ≤ ${W626_CHURN_BUDGET}/под${_w626_podstart_loss_suffix}"
    fi
else
    echo "  ПРОПУЩЕН: 6.2.6.0 не взят"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.1.8 (регрессия) СЛОЙ 2: КЛЮЧ ИСКЛЮЧЕНИЯ, КОТОРЫЙ ПРОЦЕСС СЕБЕ НЕ НАЗНАЧАЕТ.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.1.8 (регрессия): образ процесса как ключ исключения ---"
if [ "$W626_INSTRUMENTED" -eq 1 ]; then
    W626_EXE_PREFIXES="/usr/ /bin/ /sbin/ /opt/ /var/lib/rancher/"
    _w626_exe_bad=""
    for _c in k3s-server containerd kubelet coredns; do
        _p=$(pgrep -x "$_c" 2>/dev/null | head -1)
        if [ -z "$_p" ]; then
            echo "  $_c: процесса нет на этой ноде (исключение для него на этом прогоне не проверяется)"
            continue
        fi
        _e=$(readlink "/proc/$_p/exe" 2>/dev/null)
        echo "  $_c: pid=$_p exe=${_e:-<не читается>}"
        [ "$_c" = "coredns" ] && continue
        _ok=0
        for _pre in $W626_EXE_PREFIXES; do
            case "${_e:-}" in "$_pre"*) _ok=1 ;; esac
        done
        [ "$_ok" -eq 1 ] || _w626_exe_bad="$_w626_exe_bad $_c(${_e:-<пусто>})"
    done
    echo "  обращений к /proc за образом (ebpf_guard_exe_path_lookups_total, накопительно): $(_w626_metric_sum ebpf_guard_exe_path_lookups_total "" 2>/dev/null)"
    if [ -n "$_w626_exe_bad" ]; then
        die "6.2.1.8 ПРОВАЛЕН (половина «покрытие»): образ демона(ов)$_w626_exe_bad не попадает ни под один префикс правил ($W626_EXE_PREFIXES) — исключения фона ноды для них НЕ ПРИМЕНЯЮТСЯ"
    else
        pass "6.2.1.8 ДОСТИГНУТО (половина «покрытие»): образы всех найденных хостовых демонов попадают под префиксы исключений"
    fi

    _w626_target8=$(find /var/lib/kubelet/pods -maxdepth 6 -type f -name token 2>/dev/null | head -1)
    [ -z "$_w626_target8" ] && _w626_target8=$(find /var/lib/kubelet/pods -maxdepth 4 -type f 2>/dev/null | head -1)
    if [ -z "$_w626_target8" ]; then
        die "6.2.1.8 НЕИЗМЕРИМ (половина «отказ обхода»): под /var/lib/kubelet/pods нет ни одного файла — подделке нечего читать"
    else
        # ИМЯ КОПИИ — РОВНО ИМЯ ДЕМОНА: comm ядро берёт из базового имени
        # образа в execve, `exec -a` подменяет только argv[0] (память
        # exec-a-argv0-spoof-kills-proc-args). Иначе исключение
        # node-host-daemon не применилось бы В ЛЮБОМ СЛУЧАЕ и контроль
        # проверял бы не слой 2.
        rm -rf /tmp/w626-bypass 2>/dev/null
        mkdir -p /tmp/w626-bypass 2>/dev/null
        cp /bin/cat /tmp/w626-bypass/k3s-server 2>/dev/null
        chmod 0755 /tmp/w626-bypass/k3s-server 2>/dev/null
        _w626_t8=$(_w626_epoch)
        ( exec -a k3s-server /tmp/w626-bypass/k3s-server "$_w626_target8" ) > /tmp/w626-bypass/out 2>/dev/null &
        _w626_p8=$!
        wait "$_w626_p8" 2>/dev/null
        _w626_b8=$(wc -c < /tmp/w626-bypass/out 2>/dev/null | tr -d ' ')
        _w626_h8=0; _w626_w8=0
        while [ "$_w626_w8" -lt "$W626_POS_TIMEOUT" ]; do
            sleep "$W626_SETTLE"; _w626_w8=$(( _w626_w8 + W626_SETTLE ))
            _w626_h8=$(_w626_alerts | jq --argjson t "$_w626_t8" --argjson p "${_w626_p8:-0}" --arg ids "$W626_HOST_RULES" \
                '[.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.pid == $p) and (.rule_id as $r|($ids|split(" "))|index($r)))]|length' 2>/dev/null || echo 0)
            [ "${_w626_h8:-0}" -gt 0 ] && break
        done
        _w626_c8=$(_w626_alerts | jq -r --argjson p "${_w626_p8:-0}" '[.[]|select(.pid == $p)][0].comm // "нет алертов от этого pid"' 2>/dev/null)
        echo "  сторож результата подделки: прочитано байт = $_w626_b8 (цель $_w626_target8)"
        echo "  подделка: pid=$_w626_p8, образ /tmp/w626-bypass/k3s-server, comm в сторе=$_w626_c8"
        echo "  алертов от подделки (по её pid): $_w626_h8 из обязательных ($W626_HOST_RULES)"
        if [ "${_w626_b8:-0}" -lt 1 ]; then
            die "6.2.1.8 НЕИЗМЕРИМ (половина «отказ обхода»): подделка не прочитала ни байта — ноль правил приборный"
        elif [ "$_w626_c8" != "k3s-server" ] && [ "${_w626_h8:-0}" -lt 1 ]; then
            die "6.2.1.8 НЕИЗМЕРИМ (половина «отказ обхода»): подделка не носит имени демона — стор знает её как «${_w626_c8}». При таком comm исключение не применилось бы в любом случае, и слой 2 контроль не проверял"
        elif [ "${_w626_h8:-0}" -lt 1 ]; then
            die "6.2.1.8 ПРОВАЛЕН (половина «отказ обхода»): процесс, назвавшийся k3s-server и прочитавший токен пода ($_w626_b8 байт), НЕ поднял ни одного из $W626_HOST_RULES — исключение следует за именем, а не за образом"
        else
            pass "6.2.1.8 ДОСТИГНУТО (половина «отказ обхода»): подделка носила имя демона (comm=$_w626_c8), но не унаследовала его тишину — поднято $_w626_h8 обязательных правил"
        fi
        rm -rf /tmp/w626-bypass 2>/dev/null
    fi
else
    echo "  ПРОПУЩЕН: 6.2.6.0 не взят"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.1.9 (регрессия) СЛОЙ 3: СМЕНА ПРАВ НА ФАЙЛОВОЙ ОСИ + вторая половина
# №243 (chmod даёт ровно одно событие: syscall-ось его больше не производит).
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.1.9 (регрессия): chmod с разрешённым путём + №243 ---"
if [ "$W626_INSTRUMENTED" -eq 1 ]; then
    _w626_hook_ok=$(_w626_metrics | awk '/^ebpf_guard_file_hook_attach_total\{.*result="ok"/ {s+=$NF} END{printf "%d", s+0}')
    _w626_hook_err=$(_w626_metrics | awk '/^ebpf_guard_file_hook_attach_total\{.*result="(error|missing)"/ {s+=$NF} END{printf "%d", s+0}')
    echo "  привязка chmod-хуков: ok=$_w626_hook_ok, error+missing=$_w626_hook_err"
    echo "  chmod без разрешённого пути (накопительно): $(_w626_metric_sum ebpf_guard_file_chmod_unresolved_total "" 2>/dev/null)"

    # №243, вторая половина: syscall-события за серию chmod. До правки каждый
    # chmod давал ВТОРОЕ событие на syscall-оси, которое никто не читает.
    _w626_sysc_m0=$(_w626_metrics > "$W626_ART/metrics-chmod-0.txt"; awk '/^ebpf_guard_events_total\{.*type="syscall"/{s+=$NF} END{printf "%d", s+0}' "$W626_ART/metrics-chmod-0.txt")
    _w626_t9=$(_w626_epoch)
    mkdir -p /tmp/w626-chmod 2>/dev/null
    : > /tmp/w626-chmod/payload 2>/dev/null
    chmod 0755 /tmp/w626-chmod/payload 2>/dev/null
    _w626_m1=$(stat -c '%a' /tmp/w626-chmod/payload 2>/dev/null)
    cp /bin/cat /usr/local/bin/w626-chmod-bin 2>/dev/null
    chmod 0755 /usr/local/bin/w626-chmod-bin 2>/dev/null
    _w626_m2=$(stat -c '%a' /usr/local/bin/w626-chmod-bin 2>/dev/null)
    # Серия из 50 chmod по одному пути: на syscall-оси это дало бы +50 событий.
    for _i in $(seq 1 50); do chmod 0644 /tmp/w626-chmod/payload 2>/dev/null; chmod 0755 /tmp/w626-chmod/payload 2>/dev/null; done
    echo "  сторож результата: права /tmp/w626-chmod/payload = ${_w626_m1:-НЕ ПРОЧИТАНЫ}, /usr/local/bin/w626-chmod-bin = ${_w626_m2:-НЕ ПРОЧИТАНЫ}"

    _w626_c9=0; _w626_w9=0
    while [ "$_w626_w9" -lt "$W626_POS_TIMEOUT" ]; do
        sleep "$W626_SETTLE"; _w626_w9=$(( _w626_w9 + W626_SETTLE ))
        _w626_c9=$(_w626_alerts | jq --argjson t "$_w626_t9" \
            '[.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.rule_id|test("chmod")))]|length' 2>/dev/null || echo 0)
        [ "${_w626_c9:-0}" -gt 1 ] && break
    done
    _w626_r9=$(_w626_alerts | jq -r --argjson t "$_w626_t9" \
        '.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.rule_id|test("chmod")))|.rule_id' 2>/dev/null | sort -u | tr '\n' ' ')
    _w626_metrics > "$W626_ART/metrics-chmod-1.txt"
    _w626_sysc_m1=$(awk '/^ebpf_guard_events_total\{.*type="syscall"/{s+=$NF} END{printf "%d", s+0}' "$W626_ART/metrics-chmod-1.txt")
    echo "  алертов о смене прав после подачи: $_w626_c9 (правила: ${_w626_r9:-нет})"
    echo "  №243, наблюдение: syscall-событий за серию из 100 chmod: $(( _w626_sysc_m1 - _w626_sysc_m0 )) (при chmod на syscall-оси было бы ≥ 100; фон ноды сюда тоже входит, поэтому это наблюдение, а вердикт №243 выносит monitored_syscalls в преflight'е)"

    if [ -z "${_w626_m1:-}" ] || [ -z "${_w626_m2:-}" ]; then
        die "6.2.1.9 НЕИЗМЕРИМ: сторож результата не прочитал права после chmod — подача не состоялась, ноль правил приборный"
    elif [ "$_w626_hook_ok" -eq 0 ]; then
        die "6.2.1.9 ПРОВАЛЕН (приборный ноль): ни один chmod-хук не привязан (ok=0, error+missing=$_w626_hook_err) — три правила о смене прав НЕ МОГУТ сработать"
    elif ! printf '%s' "$_w626_r9" | grep -q 'sigma_chmod_executable_tmp'; then
        die "6.2.1.9 ПРОВАЛЕН: chmod +x в /tmp состоялся (права $_w626_m1), а sigma_chmod_executable_tmp не поднялся — тихая смерть правила"
    elif ! printf '%s' "$_w626_r9" | grep -q 'evasion_chmod_sensitive'; then
        die "6.2.1.9 ПРОВАЛЕН: chmod системного бинаря состоялся (права $_w626_m2), а evasion_chmod_sensitive не поднялся"
    else
        pass "6.2.1.9 ДОСТИГНУТО: смена прав видна с разрешённым путём, и каждое из двух мест подняло СВОЁ правило (${_w626_r9})"
    fi
    rm -rf /tmp/w626-chmod /usr/local/bin/w626-chmod-bin 2>/dev/null
else
    echo "  ПРОПУЩЕН: 6.2.6.0 не взят"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.3.5/6.2.3.6 (item 3 постановки, №249/решение 4). Механизм немоты
# op=write устанавливается ПОДАЧЕЙ, не рассуждением: `echo … >> path` (shell
# перенаправление — bash открывает файл на СВОЙ fd, dup2()'ит его на fd 1,
# пишет, восстанавливает fd 1) и `dd of=path` на ОДИН И ТОТ ЖЕ путь. Три
# исхода и что каждый значит (решение 4, plan.md §6.2.3):
#   обе молчат при подтверждённой записи → ось OP: сужение №234 (op in
#     [write]) в принципе не совпадает с этим write(), fd→path тут ни при
#     чём — откатывается сужение;
#   молчит echo, поднимает dd → FD→PATH: dup2/dup3 не хукнуты (или не
#     привязались на этом ядре) — sys_enter_write видит fd 1 БЕЗ записи в
#     fd_path_map, путь резолвится пустым, filename-префикс не совпадает;
#   поднимают обе → №246 была дефектом сборки на стенде, закрыта деплоем.
# 06.09.2026 живьём на ebaka2: strace дал третий, незапланированный вариант —
# GNU dd (`of=` задан) ТОЖЕ дублирует fd (open→dup2(fd,1)→write(1,…)), а не
# пишет напрямую в свой fd, как предполагала постановка. Это не отменяет
# третий исход выше — он остаётся законным различителем на системах, где dd
# пишет напрямую, — но означает, что на ЭТОМ стенде echo и dd проверяют
# ОДИН И ТОТ ЖЕ механизм (fd→path), а не два разных пути. Хуки
# sys_enter_dup{,2,3} (bpf/fileaccess.bpf.c, dup_commit) закрывают его для
# обеих подач одинаково.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.3.5/6.2.3.6: механизм немоты op=write — echo >> и dd of= на один путь (№249) ---"
# ОТКРЫТЫЙ ВОПРОС 6 (закрыт этим стражем). Блок НАМЕРЕННО пишет в /var/log и
# НАМЕРЕННО поднимает sigma_log_deletion — то есть производит алерты. Пока он
# стоит ПОСЛЕ тихого окна (после 6.2.1.9), в измеряемую величину они не
# попадают. Но это свойство ПОРЯДКА СТРОК в файле, а порядок правится молча:
# перенос блока выше по тексту сделает измеритель источником собственного
# шума — ровно класс находки №242, на котором волна 6.2.2 уже потеряла замер.
# Поэтому порядок здесь ПРОВЕРЯЕТСЯ, а не подразумевается: t1 (закрытие
# тихого окна) обязан быть в прошлом к моменту первой подачи.
_w626_now5=$(_w626_epoch)
if [ -z "${_w626_t1:-}" ]; then
    die "6.2.3.5 НЕИЗМЕРИМ: тихое окно не открывалось к моменту подачи write-механизма — порядок блоков нарушен, границы окна неизвестны"
    W626_WRITE_ORDER_OK=0
elif [ "$_w626_now5" -le "$_w626_t1" ]; then
    die "6.2.3.5 НЕИЗМЕРИМ (открытый вопрос 6): подача write-механизма идёт ВНУТРИ тихого окна (сейчас $(_w626_utc "$_w626_now5") ≤ t1 $(_w626_utc "$_w626_t1")). Блок намеренно поднимает sigma_log_deletion, и эти алерты попадут в величину 6.2.6.1/6.2.6.2 как шум продукта. Вернуть блок ПОСЛЕ 6.2.1.9"
    W626_WRITE_ORDER_OK=0
else
    echo "  порядок (открытый вопрос 6): подача идёт через $((_w626_now5 - _w626_t1)) с ПОСЛЕ закрытия тихого окна — собственные алерты блока вне измеряемой величины"
    W626_WRITE_ORDER_OK=1
fi
if [ "$W626_INSTRUMENTED" -eq 1 ]; then
    _w626_dup_ok=$(_w626_metrics | awk -F'[ }]' '/^ebpf_guard_file_hook_attach_total\{hook="sys_enter_dup[23]?",result="ok"\}/ {s+=$NF} END{printf "%d", s+0}')
    _w626_dup_bad=$(_w626_metrics | awk -F'[ }]' '/^ebpf_guard_file_hook_attach_total\{hook="sys_enter_dup[23]?",result="(error|missing)"\}/ {s+=$NF} END{printf "%d", s+0}')
    echo "  привязка dup/dup2/dup3-хуков: ok=$_w626_dup_ok, error+missing=$_w626_dup_bad"

    _w626_echo_path="/var/log/w626-write-mechanism-echo.log"
    _w626_dd_path="/var/log/w626-write-mechanism-dd.log"
    rm -f "$_w626_echo_path" "$_w626_dd_path" 2>/dev/null
    _w626_t5=$(_w626_epoch)
    echo 'w626-op-write-echo-payload' >> "$_w626_echo_path"
    _w626_echo_bytes=$(wc -c < "$_w626_echo_path" 2>/dev/null | tr -d ' ')
    dd if=/dev/zero of="$_w626_dd_path" bs=1 count=32 2>/dev/null
    _w626_dd_bytes=$(wc -c < "$_w626_dd_path" 2>/dev/null | tr -d ' ')
    echo "  сторож результата: echo записал ${_w626_echo_bytes:-0} байт в $_w626_echo_path, dd — ${_w626_dd_bytes:-0} байт в $_w626_dd_path"

    _w626_w5=0; _w626_echo_hit=0; _w626_dd_hit=0
    while [ "$_w626_w5" -lt "$W626_POS_TIMEOUT" ]; do
        sleep "$W626_SETTLE"; _w626_w5=$(( _w626_w5 + W626_SETTLE ))
        _w626_alerts > "$W626_ART/alerts-write-mechanism.json"
        _w626_echo_hit=$(jq --argjson t "$_w626_t5" --arg p "$_w626_echo_path" \
            '[.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and .rule_id=="sigma_log_deletion" and (.details["file.path"]==$p))]|length' \
            "$W626_ART/alerts-write-mechanism.json" 2>/dev/null || echo 0)
        _w626_dd_hit=$(jq --argjson t "$_w626_t5" --arg p "$_w626_dd_path" \
            '[.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and .rule_id=="sigma_log_deletion" and (.details["file.path"]==$p))]|length' \
            "$W626_ART/alerts-write-mechanism.json" 2>/dev/null || echo 0)
        [ "${_w626_echo_hit:-0}" -ge 1 ] && [ "${_w626_dd_hit:-0}" -ge 1 ] && break
    done
    echo "  6.2.3.5, исход подачи: echo→sigma_log_deletion=${_w626_echo_hit:-0}, dd→sigma_log_deletion=${_w626_dd_hit:-0}"

    if [ -z "${_w626_echo_bytes:-}" ] || [ "$_w626_echo_bytes" = "0" ] || [ -z "${_w626_dd_bytes:-}" ] || [ "$_w626_dd_bytes" = "0" ]; then
        die "6.2.3.5 НЕИЗМЕРИМ: сторож результата не подтвердил запись (echo=${_w626_echo_bytes:-0}Б, dd=${_w626_dd_bytes:-0}Б) — подача не состоялась, ноль правила приборный"
        die "6.2.3.6 НЕИЗМЕРИМ: та же подача — без подтверждённой записи вердикт правилу вынести не на чем"
    elif [ "${_w626_echo_hit:-0}" -eq 0 ] && [ "${_w626_dd_hit:-0}" -eq 0 ]; then
        die "6.2.3.5 ПРОВАЛЕН: механизм — ОСЬ OP. Обе нагрузки молчат при подтверждённой записи — сужение №234 (op in [write]) в принципе не совпадает с этим write(), fd→path не при чём. Решение 4: откатить условие op у sigma_log_deletion"
        die "6.2.3.6 ПРОВАЛЕН: sigma_log_deletion не поднимается НИ НА ОДНОЙ подаче (echo=${_w626_echo_hit:-0}, dd=${_w626_dd_hit:-0}) — своя метка выносит свой вердикт, а не наследует его у 6.2.3.5"
    elif [ "${_w626_echo_hit:-0}" -eq 0 ] && [ "${_w626_dd_hit:-0}" -ge 1 ]; then
        die "6.2.3.5 ПРОВАЛЕН: механизм — FD→PATH. echo молчит, dd поднимает — dup2-хук не привязан или не переносит fd_path_map (ok=$_w626_dup_ok, error+missing=$_w626_dup_bad). Решение 4: хуки sys_enter_dup{,2,3} обязаны быть в сборке"
        die "6.2.3.6 ПРОВАЛЕН: sigma_log_deletion поднимается только на одной подаче из двух (echo=${_w626_echo_hit:-0}, dd=${_w626_dd_hit:-0})"
    else
        # 6.2.3.5 и 6.2.3.6 — ДВЕ РАЗНЫЕ МЕТКИ на одной подаче: 6.2.3.5
        # спрашивает «назван ли МЕХАНИЗМ немоты» (ось op против fd→path),
        # 6.2.3.6 — «поднимается ли правило на обеих подачах». В прогоне
        # 6.2.4 успешный исход печатал ТОЛЬКО 6.2.3.6, и 6.2.3.5 своего
        # вердикта не выносила (постановка 6.2.6.14 требует, чтобы вынесла:
        # метка без вердикта неотличима от нереализованной — №269/№270).
        pass "6.2.3.5 ДОСТИГНУТО: механизм немоты op=write назван подачей — обе нагрузки (echo=${_w626_echo_hit:-0}, dd=${_w626_dd_hit:-0}) поднимают правило, то есть ни ось op, ни fd→path немоты не дают на этом стенде"
        pass "6.2.3.6 ДОСТИГНУТО: sigma_log_deletion (op in [write]) поднимается НА ОБЕИХ подачах — echo и dd (на этом стенде dd тоже идёт через dup2, strace 06.09.2026) — механизм fd→path закрыт хуками sys_enter_dup{,2,3} (ok=$_w626_dup_ok, error+missing=$_w626_dup_bad)"
    fi
    rm -f "$_w626_echo_path" "$_w626_dd_path" 2>/dev/null
else
    echo "  ПРОПУЩЕН: 6.2.6.0 не взят"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.3.13 (item 4 постановки, №248): сужение верхушки разбивки (в) —
# sigma_failed_login_syscall_daemon и rootkit_pam_module_added_daemon сужены
# осью op=write (были: любой read/open от sshd|cron — 3090/2400 и 2970/2280
# алертов/окно на двух архивах 6.2.2, первые два источника разбивки 6.2.6.2).
# Юнит на ОБЕ половины: фон (штатные sshd/cron за тихое окно — читают PAM на
# каждом логине/job'е) обязан молчать; подделка identity (comm=sshd/cron),
# которая ДЕЙСТВИТЕЛЬНО пишет в PAM, обязана по-прежнему поднимать правило —
# иначе это не сужение, а немота (тот же класс проверки, что 6.2.1.8).
# Половина «фон» читает уже снятое тихое окно ($W626_ART/metrics-window-*)
# прямой дельтой (величина гейта — показание прибора, а не строка таблицы,
# память f6b-table-indexed-by-limiter-cut), не отдельное ожидание.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.3.13: сужение верхушки шума op=write — обе половины (№248) ---"
if [ "$W626_INSTRUMENTED" -eq 1 ] && [ -s "$W626_ART/metrics-window-start.txt" ] && [ -s "$W626_ART/metrics-window-end.txt" ]; then
    _w626_narrow_bg=0
    for _nr in sigma_failed_login_syscall_daemon rootkit_pam_module_added_daemon; do
        _a0=$(_w626_metric_sum ebpf_guard_alerts_total "$_nr" "$W626_ART/metrics-window-start.txt")
        _a1=$(_w626_metric_sum ebpf_guard_alerts_total "$_nr" "$W626_ART/metrics-window-end.txt")
        _f0=$(_w626_metric_sum ebpf_guard_alerts_filtered_total "$_nr" "$W626_ART/metrics-window-start.txt")
        _f1=$(_w626_metric_sum ebpf_guard_alerts_filtered_total "$_nr" "$W626_ART/metrics-window-end.txt")
        _d=$(( (_a1 - _a0) + (_f1 - _f0) ))
        echo "  фон, тихое окно, $_nr: +$_d за окно (было при op-фильтре ещё не введённом: 3090/2400 и 2970/2280 на архивах 6.2.2)"
        _w626_narrow_bg=$(( _w626_narrow_bg + (_d < 0 ? 0 : _d) ))
    done

    # Половина «цель»: comm=sshd/cron, ДЕЙСТВИТЕЛЬНО пишущий в PAM. comm
    # берётся из БАЗОВОГО ИМЕНИ ПУТИ execve (kbasename(bprm->filename)), не из
    # argv[0] — `exec -a name path` подставляет только argv[0] и оставляет
    # comm от path (см. образец 6.2.1.8): бинарь копируется в файл, названный
    # sshd/cron, и запускается ИМ САМИМ.
    mkdir -p "$W626_ART/spoof13" 2>/dev/null
    cp /bin/bash "$W626_ART/spoof13/sshd" 2>/dev/null
    cp /bin/bash "$W626_ART/spoof13/cron" 2>/dev/null
    chmod +x "$W626_ART/spoof13/sshd" "$W626_ART/spoof13/cron" 2>/dev/null
    _w626_pos1="/etc/pam.d/w626-narrow-spoof-sshd"
    _w626_pos2="/etc/security/w626-narrow-spoof-cron"
    rm -f "$_w626_pos1" "$_w626_pos2" 2>/dev/null
    _w626_t13=$(_w626_epoch)
    _w626_metrics > "$W626_ART/metrics-narrow-pos-0.txt"
    "$W626_ART/spoof13/sshd" -c "echo w626-narrow-spoof-payload >> $_w626_pos1" 2>/dev/null
    "$W626_ART/spoof13/cron" -c "echo w626-narrow-spoof-payload >> $_w626_pos2" 2>/dev/null
    _w626_pos_bytes=$(( $(wc -c < "$_w626_pos1" 2>/dev/null || echo 0) + $(wc -c < "$_w626_pos2" 2>/dev/null || echo 0) ))
    echo "  сторож результата: спуф-подача записала ${_w626_pos_bytes:-0} байт суммарно в $_w626_pos1/$_w626_pos2"

    _w626_w13=0; _w626_pos_hit=0
    while [ "$_w626_w13" -lt "$W626_POS_TIMEOUT" ]; do
        sleep "$W626_SETTLE"; _w626_w13=$(( _w626_w13 + W626_SETTLE ))
        _w626_metrics > "$W626_ART/metrics-narrow-pos-1.txt"
        _w626_pos_hit=0
        for _nr in sigma_failed_login_syscall_daemon rootkit_pam_module_added_daemon; do
            _pa0=$(_w626_metric_sum ebpf_guard_alerts_total "$_nr" "$W626_ART/metrics-narrow-pos-0.txt")
            _pa1=$(_w626_metric_sum ebpf_guard_alerts_total "$_nr" "$W626_ART/metrics-narrow-pos-1.txt")
            _pf0=$(_w626_metric_sum ebpf_guard_alerts_filtered_total "$_nr" "$W626_ART/metrics-narrow-pos-0.txt")
            _pf1=$(_w626_metric_sum ebpf_guard_alerts_filtered_total "$_nr" "$W626_ART/metrics-narrow-pos-1.txt")
            _w626_pos_hit=$(( _w626_pos_hit + (_pa1 - _pa0) + (_pf1 - _pf0) ))
        done
        [ "${_w626_pos_hit:-0}" -ge 1 ] && break
    done
    echo "  6.2.3.13, половина «цель»: +$_w626_pos_hit срабатываний двух правил на спуф-запись (comm=sshd/cron, op=write)"
    rm -f "$_w626_pos1" "$_w626_pos2" 2>/dev/null
    rm -rf "$W626_ART/spoof13" 2>/dev/null

    # Половины «фон» и «цель» НЕЗАВИСИМЫ и судятся порознь — та же правка, что
    # и у 6.2.4.5 (смок 6.2.6): в цепочке elif провал «фона» гасил вердикт по
    # «цели», и критерий, обещающий «обе половины», отчитывался об одной.
    _w626_t13_fails=""; _w626_t13_unmeas=""
    if [ -z "${_w626_pos_bytes:-}" ] || [ "$_w626_pos_bytes" = "0" ]; then
        _w626_t13_unmeas=" [цель] сторож результата не подтвердил запись — спуф не состоялся, ноль правил приборный;"
    elif [ "${_w626_pos_hit:-0}" -eq 0 ]; then
        _w626_t13_fails="$_w626_t13_fails [цель] подделка носила имя sshd/cron и подтверждённо ЗАПИСАЛА в PAM (${_w626_pos_bytes}Б), но ни sigma_failed_login_syscall_daemon, ни rootkit_pam_module_added_daemon не сработали — сужение выродилось в немоту, а не в фильтр по op;"
    else
        echo "  половина «цель» ВЗЯТА: +$_w626_pos_hit срабатываний на спуф-запись"
    fi
    if [ "$_w626_narrow_bg" -gt 0 ]; then
        _w626_t13_fails="$_w626_t13_fails [фон] $_w626_narrow_bg алертов от двух сужённых правил за тихое окно — узкий op=write фильтр не убрал рутинное чтение PAM демоном, сужение №248 не сработало по существу;"
    else
        echo "  половина «фон» ВЗЯТА: 0 алертов двух сужённых правил за тихое окно"
    fi
    if [ -n "$_w626_t13_fails" ]; then
        die "6.2.3.13 ПРОВАЛЕН, половины:$_w626_t13_fails${_w626_t13_unmeas:+ НЕИЗМЕРИМЫ:$_w626_t13_unmeas}"
    elif [ -n "$_w626_t13_unmeas" ]; then
        die "6.2.3.13 НЕИЗМЕРИМ, половины:$_w626_t13_unmeas"
    else
        pass "6.2.3.13 ДОСТИГНУТО: обе половины — фон (0 алертов за тихое окно) молчит, запись под именем sshd/cron (+$_w626_pos_hit) по-прежнему поднимает — сужение №248 сузило ось op, а не выключило правило"
    fi
else
    echo "  ПРОПУЩЕН: 6.2.6.0 не взят или тихое окно не снято"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.3.14 (item 5 постановки, №247/решение 2): c2_periodic_beacon_pattern
# получило исключение фона ноды (node-host-daemon/kube-system-pod — тот же
# образец, что beacon_fixed_interval уже несёт с волны 6.2.1). Решение 2
# требует ТРЕТИЙ контроль: подделка identity (comm=k3s-server) не должна
# наследовать тишину демона — на хосте cgroup-ось (container.id/k8s.pod)
# пуста одинаково у настоящего демона и у подделки, различает их только
# кернел-назначенный exe_path (слой 2, тот же принцип, что 6.2.1.8). Инъекция
# периодического трафика — тот же приём, что 6.2.2.6 использует для
# позитивной половины (setsid, вне дерева самого контроля — память
# observer-exclusion-blinds-controls; /dev/tcp/127.0.0.1/19090 — порт самого
# агента, заведомо принимающий соединения).
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.3.14: подделка identity демона (comm=k3s-server) не должна унаследовать тишину бикон-исключения (№247) ---"
if [ "$W626_INSTRUMENTED" -eq 1 ]; then
    mkdir -p "$W626_ART/spoof14" 2>/dev/null
    cp /bin/bash "$W626_ART/spoof14/k3s-server" 2>/dev/null
    chmod +x "$W626_ART/spoof14/k3s-server" 2>/dev/null
    _w626_beacon14_before=$(( $(_w626_metric_sum ebpf_guard_alerts_total "c2_periodic_beacon_pattern") + $(_w626_metric_sum ebpf_guard_alerts_filtered_total "c2_periodic_beacon_pattern") + $(_w626_ratelimited "c2_periodic_beacon_pattern") ))
    # exec -a ставит comm="k3s-server" (базовое имя пути execve), но
    # /proc/<pid>/exe остаётся в $W626_ART/spoof14 — мимо префиксов
    # исключения (/usr/, /bin/, /sbin/, /opt/, /var/lib/rancher/).
    ( setsid "$W626_ART/spoof14/k3s-server" -c 'for i in 1 2 3 4 5; do exec 9<>/dev/tcp/127.0.0.1/19090 2>/dev/null; exec 9>&-; sleep 6; done' >/dev/null 2>&1 & )
    _w626_beacon14_after=$_w626_beacon14_before
    _w626_w14=0
    while [ "$_w626_w14" -lt "$W626_POS_TIMEOUT" ]; do
        sleep "$W626_SETTLE"; _w626_w14=$(( _w626_w14 + W626_SETTLE ))
        _w626_beacon14_after=$(( $(_w626_metric_sum ebpf_guard_alerts_total "c2_periodic_beacon_pattern") + $(_w626_metric_sum ebpf_guard_alerts_filtered_total "c2_periodic_beacon_pattern") + $(_w626_ratelimited "c2_periodic_beacon_pattern") ))
        [ "$(( _w626_beacon14_after - _w626_beacon14_before ))" -ge 1 ] && break
    done
    _w626_c14=$(_w626_alerts | jq -r --arg rid "c2_periodic_beacon_pattern" '[.[]|select(.rule_id==$rid)][-1].comm // "нет алертов"' 2>/dev/null)
    rm -rf "$W626_ART/spoof14" 2>/dev/null
    _w626_d14=$(( _w626_beacon14_after - _w626_beacon14_before ))
    echo "  срабатываний c2_periodic_beacon_pattern после подделки (comm в последнем алерте: ${_w626_c14:-нет}): $_w626_d14"
    if [ "${_w626_d14:-0}" -lt 1 ]; then
        die "6.2.3.14 ПРОВАЛЕН: процесс, назвавшийся k3s-server (exe вне системных каталогов), НЕ поднял c2_periodic_beacon_pattern — исключение node-host-daemon следует за именем, а не за образом (№247, решение 2)"
    else
        pass "6.2.3.14 ДОСТИГНУТО: подделка носила имя демона, но не унаследовала его тишину — правило поднялось $_w626_d14 раз на подделанном образе"
    fi
else
    echo "  ПРОПУЩЕН: 6.2.6.0 не взят"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.2.6 ПРАВИЛО СОВПАДАЕТ НЕ ШИРЕ СВОЕГО ИМЕНИ (№231, №234 + sigma_iptables_flush).
#
# Критерий требует ОБЕ половины по каждому из трёх правил. Половины разнесены
# по способу проверки честно, а не по удобству:
#   * ЮНИТ — обязательная часть критерия («юнит, а не прогон»): он покрывает
#     и те половины, которые на живом стенде подать нельзя без вреда
#     (настоящий `iptables -F` на ноде k3s снёс бы её сеть — это не контроль,
#     а авария);
#   * ЖИВАЯ ЧАСТЬ — то, что подать можно: молчание фона (напечатано выше по
#     окну), инъекция периодического бикона, чтение и запись /var/log,
#     подделка строки iptables без самого flush.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.2.6 (половина 2/2): юнит + инъекции ---"
_w626_unit_out="$W626_ART/unit-6.2.2.6.txt"
if [ -x "$W626_GO" ] && [ -d "$W626_REPO/internal/correlator" ]; then
    ( cd "$W626_REPO" && "$W626_GO" test -count=1 -run 'Wave6_2_2|Wave6_2_1' ./internal/correlator/... ) > "$_w626_unit_out" 2>&1
    _w626_unit_rc=$?
    tail -5 "$_w626_unit_out" | sed 's/^/    /'
    if [ "$_w626_unit_rc" -eq 0 ]; then
        pass "6.2.2.6 ДОСТИГНУТО (половина «юнит»): обе половины трёх правок условий зелены (см. $_w626_unit_out)"
    else
        die "6.2.2.6 ПРОВАЛЕН (половина «юнит»): go test -run 'Wave6_2_2|Wave6_2_1' ./internal/correlator/... вернул $_w626_unit_rc — правки условий не держат ни фон, ни свой сценарий (см. $_w626_unit_out)"
    fi
else
    die "6.2.2.6 НЕИЗМЕРИМ (половина «юнит»): нет $W626_GO или дерева $W626_REPO/internal/correlator — юнит-половину критерия нечем взять"
fi

# Инъекция 1: периодический бикон. Одна и та же тройка (pid, daddr, dport),
# ≥3 соединения с ровным кадансом внутри 5 минут — ровно то, чего требует
# новое условие (conn_periodic_count_5m gt 2, conn_periodic_cv_5m lt 0.35).
# comm НЕ должен быть в списке исключений правила (curl/wget/... там есть),
# поэтому берётся копия оболочки с собственным именем.
# Алерт правила — severity=info, в стор он НЕ ПОПАДАЕТ (ровно причина, по
# которой сужение №220 по стору его не видело): читается ПО МЕТРИКЕ.
echo "  инъекция «периодический бикон» (одна тройка pid+addr+port, ровный каданс):"
_w626_beacon_before=$(( $(_w626_metric_sum ebpf_guard_alerts_total "c2_periodic_beacon_pattern beacon_fixed_interval") + $(_w626_metric_sum ebpf_guard_alerts_filtered_total "c2_periodic_beacon_pattern beacon_fixed_interval") + $(_w626_ratelimited "c2_periodic_beacon_pattern beacon_fixed_interval") ))
cp /bin/bash /usr/local/bin/w626beacon 2>/dev/null
# setsid уводит нагрузку из дерева самого контроля: исключение наблюдателя
# (5.9a) режет в ЯДРЕ и ослепило бы контроль (память
# observer-exclusion-blinds-controls) — ноль тогда был бы приборным.
setsid /usr/local/bin/w626beacon -c 'for i in 1 2 3 4 5; do exec 9<>/dev/tcp/127.0.0.1/19090 2>/dev/null; exec 9>&-; sleep 6; done' >/dev/null 2>&1
sleep "$W626_SETTLE"
_w626_beacon_after=$(( $(_w626_metric_sum ebpf_guard_alerts_total "c2_periodic_beacon_pattern beacon_fixed_interval") + $(_w626_metric_sum ebpf_guard_alerts_filtered_total "c2_periodic_beacon_pattern beacon_fixed_interval") + $(_w626_ratelimited "c2_periodic_beacon_pattern beacon_fixed_interval") ))
rm -f /usr/local/bin/w626beacon 2>/dev/null
echo "    срабатываний бикон-правил за инъекцию (по метрике, включая info): $(( _w626_beacon_after - _w626_beacon_before ))"
if [ "$(( _w626_beacon_after - _w626_beacon_before ))" -lt 1 ]; then
    die "6.2.2.6 ПРОВАЛЕН (половина «своё правило поднимается», инъекция бикона): пять соединений на один адрес:порт с кадансом 6с не подняли ни c2_periodic_beacon_pattern, ни beacon_fixed_interval. Порог периодичности (count>2, cv<0.35, окно 5 мин) выбран инженерной оценкой и живым трафиком до сих пор не проверялся (открытый вопрос 2) — этот ноль и есть его проверка"
else
    pass "6.2.2.6 ДОСТИГНУТО (половина «своё правило поднимается»): инъекция периодического бикона поднята правилом $(( _w626_beacon_after - _w626_beacon_before )) раз — порог периодичности подтверждён живым трафиком (открытый вопрос 2)"
fi

# Инъекция 2: sigma_log_deletion — обе половины (№234). Чтение /var/log
# молчит, запись поднимает.
echo "  инъекция «чтение против записи /var/log» (№234):"
_w626_ld_t=$(_w626_epoch)
journalctl -u "$W626_SVC" --since "-1 min" --no-pager >/dev/null 2>&1
sleep "$W626_SETTLE"
_w626_ld_read=$(_w626_alerts | jq --argjson t "$_w626_ld_t" '[.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.rule_id=="sigma_log_deletion") and (.comm=="journalctl"))]|length' 2>/dev/null || echo 0)
_w626_lw_t=$(_w626_epoch)
# Пачкой, а не одной записью: одиночная запись неотличима от потерянной
# сэмплированием (file_rate), и ноль был бы приборным.
setsid /bin/sh -c 'i=0; while [ $i -lt 300 ]; do echo w626-log-probe >> /var/log/w626-probe.log; i=$((i+1)); done' >/dev/null 2>&1
sleep "$W626_SETTLE"
_w626_ld_write=$(_w626_alerts | jq --argjson t "$_w626_lw_t" '[.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.rule_id=="sigma_log_deletion"))]|length' 2>/dev/null || echo 0)
# РАЗЛИЧИТЕЛЬ ПРИЧИНЫ. owasp_log_tampering стоит на том же пути, но БЕЗ
# условия на op. Если он поднялся, а sigma_log_deletion нет — событие дошло
# до движка, и немота у правила именно в оси op, а не в потере события,
# сэмплировании, исключении наблюдателя или неразрешённом пути. Без этой
# строки вердикт называл бы симптом и оставлял четыре объяснения.
_w626_ld_proof=$(_w626_alerts | jq --argjson t "$_w626_lw_t" '[.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.rule_id=="owasp_log_tampering") and ((.details["file.path"] // "")|test("w626-probe")))]|length' 2>/dev/null || echo 0)
rm -f /var/log/w626-probe.log 2>/dev/null
echo "    journalctl читает /var/log/journal → алертов sigma_log_deletion: $_w626_ld_read (обязан быть 0)"
echo "    300 записей в /var/log/w626-probe.log → алертов sigma_log_deletion: $_w626_ld_write (обязан быть ≥ 1)"
echo "    различитель: owasp_log_tampering на том же пути (условия на op НЕ имеет): ${_w626_ld_proof:-0}"
if [ "${_w626_ld_read:-0}" -gt 0 ]; then
    die "6.2.2.6 ПРОВАЛЕН (половина «фон молчит», №234): journalctl, ЧИТАЮЩИЙ /var/log/journal, поднял sigma_log_deletion $_w626_ld_read раз — правило по-прежнему совпадает шире своего имени"
elif [ "${_w626_ld_write:-0}" -lt 1 ]; then
    if [ "${_w626_ld_proof:-0}" -gt 0 ]; then
        die "6.2.2.6 ПРОВАЛЕН (половина «своё правило поднимается», №234): 300 записей в /var/log НЕ подняли sigma_log_deletion, при том что owasp_log_tampering на ТОМ ЖЕ пути поднялся $_w626_ld_proof раз. Событие дошло до движка с разрешённым путём — значит немота ровно в оси op: ни одно файловое событие этого пути не приходит с op=write, и сужение №234 сделало правило немым НА ЖИВОМ СТЕНДЕ, оставшись зелёным на юните (юнит строит событие с Op=write сам). Это находка о ПРОДУКТЕ, а не о контроле, и она же ставит под вопрос всякое правило вида «op in [write] + filename prefix»"
    else
        die "6.2.2.6 ПРОВАЛЕН (половина «своё правило поднимается», №234): 300 записей в /var/log не подняли ни sigma_log_deletion, ни owasp_log_tampering на том же пути — событие до движка не дошло вовсе (потеря, сэмплирование, исключение наблюдателя или неразрешённый путь), и ось op здесь ни при чём. Это НЕИЗМЕРИМОСТЬ подачи, а не вердикт правилу"
    fi
else
    pass "6.2.2.6 ДОСТИГНУТО (обе половины №234): чтение молчит ($_w626_ld_read), запись поднимает ($_w626_ld_write)"
fi

# Инъекция 3: sigma_iptables_flush — только НЕГАТИВНАЯ половина живьём.
# Позитивная (настоящий `iptables -F`) на ноде k3s снесла бы её сеть; она
# закрыта юнитом выше и подаваться на живой ноде НЕ ДОЛЖНА.
echo "  инъекция «строка iptables без flush» (№234-сосед, sigma_iptables_flush):"
_w626_ipt_t=$(_w626_epoch)
setsid /bin/sh -c 'grep iptables /etc/hosts; tar -F /tmp/w626-nope.txt' >/dev/null 2>&1
sleep "$W626_SETTLE"
_w626_ipt=$(_w626_alerts | jq --argjson t "$_w626_ipt_t" '[.[]|select(((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.rule_id=="sigma_iptables_flush"))]|length' 2>/dev/null || echo 0)
echo "    подделка «grep iptables …; tar -F …» → алертов sigma_iptables_flush: $_w626_ipt (обязан быть 0)"
echo "    позитивная половина (настоящий iptables -F) живьём НЕ подаётся: на ноде k3s это авария, а не контроль — она закрыта юнитом выше"
if [ "${_w626_ipt:-0}" -gt 0 ]; then
    die "6.2.2.6 ПРОВАЛЕН (половина «фон молчит», sigma_iptables_flush): строка, где iptables и -F принадлежат РАЗНЫМ командам, подняла правило $_w626_ipt раз — класс [^;|&] границу команды не удержал"
else
    pass "6.2.2.6 ДОСТИГНУТО (половина «фон молчит», sigma_iptables_flush): подделка через границу команды правило не подняла"
fi

# ═════════════════════════════════════════════════════════════════════════════
# 6.2.4.5 (долг 6.2.4, метка сохранена) — ИСХОД РАЗВИЛОК №253/№261, ЧЕТЫРЕ
# ПОЛОВИНЫ. Ни один архив этот критерий не содержит: в 6.2.4 он не был вжит
# в пайплайн вовсе (находка №269), а правка №253 была признана работающей
# РУКАМИ по срезам метрик. Здесь он исполняется впервые.
#
#   (1) НЕГАТИВНАЯ  — четыре двойника молчат в тихом окне ПРИ НЕНУЛЕВОМ
#       rule_exceptions_total по каждому (иначе тишина означает выключенное
#       правило, а не переехавший объём). Обе половины уже сняты выше
#       (подпункт 6.2.6.1 (1)/(2) и список comm 6.2.6.15) — здесь они
#       сводятся в вердикт СВОЕЙ метки.
#   (2) ПОЗИТИВНАЯ  — родительские правила поднимаются на подаче НЕ от
#       демона: обычный процесс, читающий /etc/shadow, обязан поднять
#       sigma_passwd_shadow_read/sensitive_file_read.
#   (3) НА ПОДДЕЛКУ  — копия /bin/cat с ИМЕНЕМ демона (comm=cron, образ
#       чужой) обязана поднять ДВОЙНИКА: ось идёт за образом, а не за именем.
#       Артефакт — вне /root (память control-artifacts-must-live-outside-root),
#       со сторожем результата на прочитанные байты (память
#       positive-control-needs-result-sentinel): execve ENOENT дал бы ноль,
#       неотличимый от вердикта.
#   (4) НОВАЯ (№261) — подача от КОРОТКОЖИВУЩЕГО ПОТОМКА ДЕМОНА. Ровно тот
#       механизм, который съел весь остаток гейта: ежеминутный fork cron'а
#       читает /etc/passwd в PAM/NSS-lookup'е ДО execve и умирает за единицы
#       миллисекунд, поэтому readlink("/proc/<pid>/exe") проигрывает гонку и
#       verified-daemon-image не применяется. Ось item 1 (verified-daemon-lineage,
#       proc.parent_exe_path) обязана примениться к ШТАТНОМУ потомку демона
#       и НЕ примениться к подделке из (3).
# ═════════════════════════════════════════════════════════════════════════════
echo "--- 6.2.4.5: исход развилок №253/№261, четыре половины (долг 6.2.4) ---"
W626_TWIN_PARENT_RULES="sigma_passwd_shadow_read sensitive_file_read"
_w626_t45_start=$(_w626_epoch)

# ---- половина (1): негативная, по уже снятому тихому окну ----
_w626_h1_alerts=$(printf '%s' "${_w626_exe_exc_comms:-[]}" | jq 'map(.n)|add // 0' 2>/dev/null)
_w626_h1_exc_ok=$([ "${_w626_twin_zero:-1}" -eq 0 ] && echo 1 || echo 0)
echo "  (1) негативная: алертов четырёх двойников в тихом окне = ${_w626_h1_alerts:-?}; все четыре дали ненулевой rule_exceptions_total: $([ "$_w626_h1_exc_ok" -eq 1 ] && echo да || echo НЕТ)"

# ---- половина (2): позитивная, подача НЕ от демона ----
#
# СМОК 6.2.6 (08.09.2026) вскрыл здесь ЛОЖНЫЙ НОЛЬ: половина ждала стор
# ФИКСИРОВАННЫМ `sleep $W626_SETTLE` (в смоке — 5 с) и объявляла 0 алертов
# провалом сужения. Живая перепроверка той же подачи показала, что правило
# СРАБОТАЛО (`ebpf_guard_alerts_total{rule_id="sensitive_file_read"}` +2,
# ни лимитера, ни дедупа, ни фильтра severity), а алерт доехал до стора
# позже окна ожидания. Все прочие позитивные контроли файла ждут результата
# ЦИКЛОМ до W626_POS_TIMEOUT — эта половина была единственной с голым sleep.
#
# Вторая правка того же места: ВХОД ВЕРДИКТА — МЕТРИКА, А НЕ СТОР (память
# narrowing-input-must-be-metric-not-store). Один из двух родителей,
# `sigma_passwd_shadow_read`, имеет severity=info, а `store.min_severity` на
# стенде = warning: в стор он не попадает НИКОГДА и по построению. Стор здесь
# годится как подтверждение, но не как источник нуля — поэтому дельта
# `alerts_total` + `alerts_filtered_total` по обоим родителям снимается
# всегда и именно она выносит вердикт.
#
# ТРЕТЬЯ правка того же места (смок №2): ноль стора здесь оказался СРЕЗОМ
# ЛИМИТЕРА, а не отставанием записи — за подачу лимитер срезал 26 алертов
# родительских правил (память control-after-attacks-hits-filled-limiter:
# ноль контроля, идущего после атак, может быть срезом, а не вердиктом).
# Поэтому подача ПОВТОРЯЕТСЯ через окно лимитера (10 алертов/правило/60 с),
# а ноль атрибутируется поимённо: срез → НЕИЗМЕРИМ, немота метрики → ПРОВАЛ.
#
# Про метрику честно: `alerts_total` НЕ несёт лейбла comm, поэтому её
# приращение доказывает лишь, что правила не немы ГЛОБАЛЬНО, и не может
# доказать, что сработала ИМЕННО эта подача. Comm-адресный источник здесь
# один — стор; метрика отделяет «правило молчит» от «алерт не дошёл».
cp /bin/cat "$W626_ART/w626shadow" 2>/dev/null
chmod +x "$W626_ART/w626shadow" 2>/dev/null
_w626_h2_tries=$([ "$W626_SMOKE" = "1" ] && echo 2 || echo 3)
_w626_h2_hits=0; _w626_h2_waited=0; _w626_h2_md=0; _w626_h2_rld=0; _w626_h2_try=0
while [ "$_w626_h2_try" -lt "$_w626_h2_tries" ]; do
    _w626_h2_try=$(( _w626_h2_try + 1 ))
    _w626_h2_m0=$(( $(_w626_metric_sum ebpf_guard_alerts_total "$W626_TWIN_PARENT_RULES") \
                  + $(_w626_metric_sum ebpf_guard_alerts_filtered_total "$W626_TWIN_PARENT_RULES") ))
    _w626_h2_rl0=$(_w626_ratelimited "$W626_TWIN_PARENT_RULES")
    _w626_h2_bytes=$("$W626_ART/w626shadow" /etc/shadow 2>/dev/null | wc -c)
    _w626_h2_w=0
    while [ "$_w626_h2_w" -lt "$W626_POS_TIMEOUT" ]; do
        sleep "$W626_SETTLE"; _w626_h2_w=$(( _w626_h2_w + W626_SETTLE ))
        _w626_h2_hits=$(_w626_alerts | jq --arg ids "$W626_TWIN_PARENT_RULES" --argjson t "$_w626_t45_start" \
            '[.[]|select((.rule_id as $r|($ids|split(" "))|index($r)) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.comm=="w626shadow"))]|length' 2>/dev/null || echo 0)
        [ "${_w626_h2_hits:-0}" -gt 0 ] && break
    done
    _w626_h2_m1=$(( $(_w626_metric_sum ebpf_guard_alerts_total "$W626_TWIN_PARENT_RULES") \
                  + $(_w626_metric_sum ebpf_guard_alerts_filtered_total "$W626_TWIN_PARENT_RULES") ))
    _w626_h2_rl1=$(_w626_ratelimited "$W626_TWIN_PARENT_RULES")
    _w626_h2_md=$(( _w626_h2_md + _w626_h2_m1 - _w626_h2_m0 ))
    _w626_h2_rld=$(( _w626_h2_rld + _w626_h2_rl1 - _w626_h2_rl0 ))
    _w626_h2_waited=$(( _w626_h2_waited + _w626_h2_w ))
    [ "${_w626_h2_hits:-0}" -gt 0 ] && break
    # Ноль не от лимитера — повтор его не изменит, ждать 60 с незачем.
    [ "$(( _w626_h2_rl1 - _w626_h2_rl0 ))" -gt 0 ] || break
    echo "      (подача $_w626_h2_try дала 0 при срезе лимитера $(( _w626_h2_rl1 - _w626_h2_rl0 )) — пережидаю окно лимитера 60с и повторяю)"
    sleep 60
done
echo "  (2) позитивная: обычный процесс (comm=w626shadow) прочитал ${_w626_h2_bytes}Б /etc/shadow → алертов родительских правил: ${_w626_h2_hits:-0} (стор, подач $_w626_h2_try, ожидание ${_w626_h2_waited}s)"
echo "      срез лимитера за подачи = $_w626_h2_rld; приращение alerts_total+alerts_filtered_total по ($W626_TWIN_PARENT_RULES) = $_w626_h2_md"
echo "      (метрика без лейбла comm — доказывает лишь ненемоту правил, не факт этой подачи; info-родитель sigma_passwd_shadow_read при store.min_severity=warning в стор не попадает по построению)"

# ---- половины (3) и (4, отрицательная сторона): подделка ИМЕНИ демона ----
# comm задаёт basename ПУТИ execve, а не argv[0] (память
# exec-a-argv0-spoof-kills-proc-args), поэтому подделка — КОПИЯ бинаря с
# именем cron, а не `exec -a cron`.
_w626_t45_spoof=$(_w626_epoch)
cp /bin/cat "$W626_ART/cron" 2>/dev/null
chmod +x "$W626_ART/cron" 2>/dev/null
# СНИМОК ДЛЯ ПОЗИТИВНОЙ ПОЛОВИНЫ 6.2.6.20 (item 4, №283). Подача (3) — это
# единственное место прогона, где заведомо есть процесс с ДОВЕРЕННЫМ ИМЕНЕМ
# демона и ЧУЖИМ образом. Исключения anomaly_detection построены на оси
# proc.exe_path (никакого proc.comm в условии), поэтому они обязаны эту
# подачу НЕ подавить — и проверяется это не рассуждением, а срезом метрики
# с осью comm вокруг ровно этого интервала. Снимок берётся здесь, потому что
# позже интервал уже не восстановить.
_w626_metrics > "$W626_ART/metrics-spoof-0.txt" 2>/dev/null
_w626_h3_m0=$(( $(_w626_metric_sum ebpf_guard_alerts_total "$W626_TWIN_RULES") \
              + $(_w626_metric_sum ebpf_guard_alerts_filtered_total "$W626_TWIN_RULES") ))
_w626_h3_rl0=$(_w626_ratelimited "$W626_TWIN_RULES")
_w626_h3_bytes=$("$W626_ART/cron" /etc/shadow 2>/dev/null | wc -c)
# Тот же ложный ноль, что и у половины (2): ждать результата циклом, а не
# фиксированным sleep. В смоке 6.2.6 эта половина дала 1 по везению — стор
# успел; на боевой длине везение не гарантия.
_w626_h3_hits=0; _w626_h3_waited=0
while [ "$_w626_h3_waited" -lt "$W626_POS_TIMEOUT" ]; do
    sleep "$W626_SETTLE"; _w626_h3_waited=$(( _w626_h3_waited + W626_SETTLE ))
    _w626_h3_hits=$(_w626_alerts | jq --arg ids "$W626_TWIN_RULES" --argjson t "$_w626_t45_spoof" \
        '[.[]|select((.rule_id as $r|($ids|split(" "))|index($r)) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.comm=="cron"))]|length' 2>/dev/null || echo 0)
    [ "${_w626_h3_hits:-0}" -gt 0 ] && break
done
_w626_h3_m1=$(( $(_w626_metric_sum ebpf_guard_alerts_total "$W626_TWIN_RULES") \
              + $(_w626_metric_sum ebpf_guard_alerts_filtered_total "$W626_TWIN_RULES") ))
_w626_h3_rl1=$(_w626_ratelimited "$W626_TWIN_RULES")
_w626_h3_md=$(( _w626_h3_m1 - _w626_h3_m0 ))
_w626_h3_rld=$(( _w626_h3_rl1 - _w626_h3_rl0 ))
_w626_metrics > "$W626_ART/metrics-spoof-1.txt" 2>/dev/null
_w626_h3_comm=$(_w626_alerts | jq -r --argjson t "$_w626_t45_spoof" \
    '[.[]|select((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t)|.comm]|unique|join(" ")' 2>/dev/null)
echo "  (3) на подделку: копия /bin/cat с именем cron прочитала ${_w626_h3_bytes}Б /etc/shadow → алертов двойников с comm=cron: ${_w626_h3_hits:-0} (ожидание ${_w626_h3_waited}s; comm алертов периода: ${_w626_h3_comm:-нет})"
echo "      метрика двойников за подачу (подтверждение, не вердикт): приращение alerts_total+alerts_filtered_total = $_w626_h3_md; срез лимитера = $_w626_h3_rld"

# ---- половина (4): ШТАТНЫЙ короткоживущий потомок демона ----
# Подача — настоящий cron: задание в /etc/cron.d заставляет его форкаться
# ежеминутно, и это ровно та форма, что дала 30 алертов окна в архиве 6.2.4
# (comm=cron, свежие pid'ы по ~3 мс). Своего execve потомок до чтения
# /etc/passwd не делает, поэтому оси exe_path он недоступен ПО ПОСТРОЕНИЮ, и
# единственное, что может его закрыть, — ось родителя (item 1).
_w626_t45_cron=$(_w626_epoch)
_w626_cron_lineage0=$(_w626_metric_sum ebpf_guard_rule_exceptions_total "verified-daemon-lineage")
# Ноль алертов здесь — направление ПРОХОДА, поэтому он обязан быть подтверждён
# метрикой: ноль стора может быть отставанием записи, и тогда половина (4)
# прошла бы ЛОЖНО — ровно тот класс, что смок нашёл у половины (2), только в
# сторону ложного PASS.
_w626_h4_m0=$(( $(_w626_metric_sum ebpf_guard_alerts_total "$W626_TWIN_RULES") \
              + $(_w626_metric_sum ebpf_guard_alerts_filtered_total "$W626_TWIN_RULES") ))
# СТОРОЖ ЛОЖНОГО ПРОХОДА — НА ОСИ comm, А НЕ НА СУММЕ ПО НОДЕ (найдено смоком
# 09.09.2026, второй предпрогон). Прежний сторож брал приращение
# alerts_total+alerts_filtered_total по правилам-двойникам БЕЗ лейбла comm,
# то есть считал ЛЮБОЙ алерт двойника на ноде за 130 с — а половина (1) того
# же критерия печатает, что двойники в тихом окне дают алерты от ЧУЖИХ comm
# (остаток гейта). Ненулевая сумма за 130 с поэтому практически гарантирована,
# и половина (4) — ГЛАВНАЯ проверка волны (ось verified-daemon-lineage, №261) —
# объявлялась НЕИЗМЕРИМОЙ на каждом прогоне по построению, независимо от того,
# вылечена гонка или нет. На смоке: +19 по ноде при нуле от cron.
# Правильная величина — приращение ebpf_guard_alert_volume_by_source_total
# по паре {rule_id ∈ двойники, comm=cron} (item 1, ось, которой у alerts_total
# нет). Счётчик инкрементируется на КАЖДОМ отправленном алерте, до фильтра
# min_severity и после слоя исключений (cmd/ebpf-guard/main.go:2187): закрытый
# осью родословной потомок cron его НЕ двигает, а не закрытый — двигает,
# независимо от отставания стора. Ровно та величина, ради которой item 1 и
# заведён (тот же приём, что у утечки comm=cron в 6.2.6.22в).
_w626_metrics > "$W626_ART/metrics-h4-0.txt" 2>/dev/null
printf '* * * * * root /bin/cat /etc/shadow > /dev/null 2>&1\n' > /etc/cron.d/w626-lineage 2>/dev/null
chmod 0644 /etc/cron.d/w626-lineage 2>/dev/null
_w626_cron_wait=130
echo "  (4) ожидание ежеминутного форка cron: ${_w626_cron_wait}s (задание /etc/cron.d/w626-lineage)"
sleep "$_w626_cron_wait"
rm -f /etc/cron.d/w626-lineage 2>/dev/null
_w626_cron_lineage1=$(_w626_metric_sum ebpf_guard_rule_exceptions_total "verified-daemon-lineage")
_w626_cron_lineage_d=$(( ${_w626_cron_lineage1:-0} - ${_w626_cron_lineage0:-0} ))
_w626_h4_alerts=$(_w626_alerts | jq --arg ids "$W626_TWIN_RULES" --argjson t "$_w626_t45_cron" \
    '[.[]|select((.rule_id as $r|($ids|split(" "))|index($r)) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and (.comm=="cron"))]|length' 2>/dev/null)
_w626_h4_m1=$(( $(_w626_metric_sum ebpf_guard_alerts_total "$W626_TWIN_RULES") \
              + $(_w626_metric_sum ebpf_guard_alerts_filtered_total "$W626_TWIN_RULES") ))
_w626_h4_md=$(( _w626_h4_m1 - _w626_h4_m0 ))
_w626_metrics > "$W626_ART/metrics-h4-1.txt" 2>/dev/null
# Наличие самой оси проверяется отдельно: пустая выдача w626_volume_by_source
# неотличима от «ось не снимается», а ноль по несуществующей метрике — это
# ровно ложный проход, ради которого сторож и заведён (Шаг 0в пайплайна
# требует exporter.volume_by_source: true, но контроль обязан судить по тому,
# что видит сам, а не по тому, что кто-то проверил раньше).
# Библиотека — часть сторожа: без неё w626_volume_by_source не существует,
# «command not found» дал бы пустую величину, а пустая читалась бы как ноль,
# то есть как ПРОХОД. Отсутствие оси и отсутствие библиотеки поэтому
# сводятся к одному признаку — числу строк оси, которое здесь обнуляется.
_w626_h4_axis=0
_w626_h4_md_cron=0
if [ "$W626_LIB_OK" -eq 1 ]; then
    _w626_h4_axis=$(grep -c '^ebpf_guard_alert_volume_by_source_total{' "$W626_ART/metrics-h4-1.txt" 2>/dev/null || echo 0)
    _w626_h4_md_cron=$(w626_volume_by_source "$W626_ART/metrics-h4-0.txt" "$W626_ART/metrics-h4-1.txt" \
        "$W626_TWIN_RULES" cron 2>/dev/null | awk '{s+=$3} END{printf "%d", s+0}')
fi
echo "  (4) штатный потомок: приращение rule_exceptions_total{verified-daemon-lineage} = $_w626_cron_lineage_d; алертов двойников с comm=cron за период: ${_w626_h4_alerts:-0}"
echo "      сторож ложного PASS (ось comm, item 1): приращение alert_volume_by_source_total{двойники, comm=cron} = ${_w626_h4_md_cron:-0} при ${_w626_h4_axis:-0} строках оси в срезе"
echo "      справочно (в вердикт НЕ идёт, №288/второй предпрогон): приращение метрики двойников по ВСЕЙ ноде без лейбла comm = $_w626_h4_md — включает чужие comm половины (1)"

# ---- ВЕРДИКТ 6.2.4.5: ЧЕТЫРЕ НЕЗАВИСИМЫЕ ПОЛОВИНЫ ----
#
# СМОК 6.2.6 (08.09.2026), второй дефект этого блока: вердикт был цепочкой
# `if/elif`, и ПЕРВАЯ сработавшая ветка гасила все последующие. Половины же
# независимы — они проверяют РАЗНЫЕ свойства одной правки, и провал одной
# ничего не говорит об остальных. На смоке провалилась половина (1) (остаток
# гейта, продуктовая величина, на боевом прогоне ожидается снова), и из-за
# этого половины (2), (3), (4) не вынесли вердикта вовсе — включая половину
# (4), которая и есть ГЛАВНАЯ проверка волны (ось verified-daemon-lineage,
# №261). То есть боевой прогон почти наверняка не измерил бы то, ради чего
# запущен, и лог выглядел бы как «один честный провал».
#
# Теперь каждая половина судится сама, печатает свою строку, и метка получает
# РОВНО ОДИН вердикт (иначе счётчик провалов считал бы один критерий четырежды).
_w626_t45_fails=""
_w626_t45_unmeas=""
# Приборность подачи — общая для (2) и (3): без подтверждённого чтения любой
# ноль ниже приборный (память positive-control-needs-result-sentinel).
if [ "${_w626_h2_bytes:-0}" -lt 1 ] || [ "${_w626_h3_bytes:-0}" -lt 1 ]; then
    _w626_t45_unmeas="$_w626_t45_unmeas [подача] сторож результата не подтвердил чтение (позитивная ${_w626_h2_bytes:-0}Б, подделка ${_w626_h3_bytes:-0}Б);"
fi
# --- половина (1) ---
if [ "$_w626_h1_exc_ok" -ne 1 ]; then
    _w626_t45_fails="$_w626_t45_fails [1] тишина двойников в окне НЕ подтверждена ненулевым rule_exceptions_total по каждому из четырёх — правило выключено, а не сужено;"
elif [ "${_w626_h1_alerts:-0}" -gt 0 ]; then
    # Правила-двойники по построению совпадают только на именах демонов, и
    # исключение обязано снять их ВСЕ: остаток — это ровно те 30 алертов
    # окна, что составляли весь остаток гейта в архиве 6.2.4 (№261).
    _w626_t45_fails="$_w626_t45_fails [1] четыре двойника дали ${_w626_h1_alerts} алертов ВНУТРИ тихого окна при работающих исключениях — часть фона ноды исключение не покрывает (поимённо по comm см. подпункт разбивки выше); это остаток гейта, а не погрешность;"
else
    echo "  (1) ВЗЯТА: двойники молчат в окне при ненулевом исключении на каждом"
fi
# --- половина (2): вердикт по МЕТРИКЕ, стор — подтверждение ---
if [ "${_w626_h2_bytes:-0}" -lt 1 ]; then
    :   # неизмерима, уже записано выше
elif [ "${_w626_h2_hits:-0}" -gt 0 ]; then
    echo "  (2) ВЗЯТА: обычный процесс поднимает родительские правила (стор $_w626_h2_hits за $_w626_h2_try подач)"
elif [ "${_w626_h2_rld:-0}" -gt 0 ]; then
    _w626_t45_unmeas="$_w626_t45_unmeas [2] за $_w626_h2_try подач стор дал 0, но лимитер срезал $_w626_h2_rld алертов родительских правил — ноль здесь СРЕЗ, а не вердикт (память control-after-attacks-hits-filled-limiter); немотой сужения №253 это НЕ является;"
elif [ "${_w626_h2_md:-0}" -lt 1 ]; then
    _w626_t45_fails="$_w626_t45_fails [2] обычный процесс прочитал /etc/shadow (${_w626_h2_bytes}Б), лимитер не срезал ничего, а родительские правила ($W626_TWIN_PARENT_RULES) не выросли НИ НА ОДНО совпадение по метрике — сужение №253 выродилось в немоту всего класса, а не в исключение фона ноды;"
else
    _w626_t45_unmeas="$_w626_t45_unmeas [2] правила не немы (метрика +$_w626_h2_md, без лейбла comm), лимитер не резал, но за ${_w626_h2_waited}s алерт ЭТОЙ подачи в стор не доехал — половина неизмерима по стору;"
fi
# --- половина (3) ---
if [ "${_w626_h3_bytes:-0}" -lt 1 ]; then
    :
elif [ "${_w626_h3_hits:-0}" -gt 0 ]; then
    echo "  (3) ВЗЯТА: подделка имени демона поднимает двойника (стор $_w626_h3_hits, метрика +$_w626_h3_md)"
elif [ "${_w626_h3_rld:-0}" -gt 0 ]; then
    _w626_t45_unmeas="$_w626_t45_unmeas [3] стор дал 0, но лимитер срезал $_w626_h3_rld алертов двойников — ноль здесь СРЕЗ, а не вердикт;"
elif [ "${_w626_h3_md:-0}" -lt 1 ]; then
    _w626_t45_fails="$_w626_t45_fails [3] подделка носила ИМЯ демона (comm=cron) при чужом образе ($W626_ART/cron) и прочитала ${_w626_h3_bytes}Б /etc/shadow, а двойники не поднялись (стор 0, метрика 0, лимитер не резал) — исключение идёт за ИМЕНЕМ, а не за образом (немой обход, память comm-not-in-is-a-mute-bypass);"
else
    _w626_t45_unmeas="$_w626_t45_unmeas [3] двойники не немы (метрика +$_w626_h3_md, без лейбла comm), но за ${_w626_h3_waited}s алерт этой подделки в стор не доехал;"
fi
# --- половина (4), №261: ГЛАВНАЯ проверка волны ---
if [ "$_w626_cron_lineage_d" -lt 1 ]; then
    _w626_t45_unmeas="$_w626_t45_unmeas [4] за ${_w626_cron_wait}s с заданием в /etc/cron.d приращение rule_exceptions_total{verified-daemon-lineage} = 0: либо ось item 1 не задеплоена, либо cron не форкнулся — ноль алертов был бы приборным, а не доказательством, что гонка вылечена;"
elif [ "${_w626_h4_alerts:-0}" -gt 0 ]; then
    _w626_t45_fails="$_w626_t45_fails [4] штатный короткоживущий потомок cron поднял ${_w626_h4_alerts} алертов двойников при работающей оси родословной (+$_w626_cron_lineage_d применений) — гонка readlink НЕ вылечена, и остаток гейта (30 алертов/окно в архиве 6.2.4) остаётся на месте;"
elif [ "${_w626_h4_axis:-0}" -lt 1 ]; then
    _w626_t45_unmeas="$_w626_t45_unmeas [4] ось {rule_id, comm} недоступна (0 строк alert_volume_by_source_total в срезе либо библиотека не подключилась, W626_LIB_OK=$W626_LIB_OK) — ноль стора подтвердить нечем, а ноль по неснимаемой метрике был бы ЛОЖНЫМ ПРОХОДОМ; половина неизмерима;"
elif [ "${_w626_h4_md_cron:-0}" -gt 0 ]; then
    _w626_t45_fails="$_w626_t45_fails [4] за ${_w626_cron_wait}s штатный потомок cron поднял ${_w626_h4_md_cron} алертов двойников ПО МЕТРИКЕ с comm=cron (стор показал ${_w626_h4_alerts:-0}) при работающей оси родословной (+$_w626_cron_lineage_d применений) — гонка readlink НЕ вылечена, и остаток гейта (30 алертов/окно в архиве 6.2.4) остаётся на месте;"
else
    echo "  (4) ВЗЯТА: штатный короткоживущий потомок cron закрыт осью родословной (+$_w626_cron_lineage_d применений; стор 0, ось {двойники, comm=cron} +0 при ${_w626_h4_axis} строках оси в срезе — тишина подтверждена метрикой, а не отставанием стора)"
fi
# --- один вердикт на метку ---
if [ -n "$_w626_t45_fails" ]; then
    die "6.2.4.5 ПРОВАЛЕН, половины:$_w626_t45_fails${_w626_t45_unmeas:+ НЕИЗМЕРИМЫ:$_w626_t45_unmeas}"
elif [ -n "$_w626_t45_unmeas" ]; then
    die "6.2.4.5 НЕИЗМЕРИМ, половины:$_w626_t45_unmeas"
else
    pass "6.2.4.5 ДОСТИГНУТО: все четыре половины — (1) двойники молчат в окне при ненулевом исключении на каждом; (2) обычный процесс поднимает родительские правила (метрика +$_w626_h2_md, стор ${_w626_h2_hits}); (3) подделка имени демона поднимает двойника (${_w626_h3_hits}); (4) штатный короткоживущий потомок cron закрыт осью родословной (+$_w626_cron_lineage_d применений, 0 алертов) — ось идёт за образом и за родителем, но не за именем"
fi
rm -f "$W626_ART/w626shadow" "$W626_ART/cron" 2>/dev/null

# ═════════════════════════════════════════════════════════════════════════════
# 6.2.6.20 (№283, item 4) — ПОЛ ВОЛНЫ НАЗВАН И ПЕРЕЕХАЛ, А НЕ ИСЧЕЗ.
#
# ЧТО ЭТО ЗА ПОЛ. anomaly_detection даёт ~8 алертов за окно и синтезируется
# движком МИМО слоя правил: до item 4 ни одно исключение куста 6.2 его не
# сужало, то есть половина разрешённого бюджета гейта лежала вне всего
# антиспуф-аппарата волн 6.2.1…6.2.5. Item 4 провёл его через слой именованных
# исключений (rules/anomaly.yaml, Rule.Synthetic, EvaluateNamedExceptions).
#
# ПОЧЕМУ НОЛЬ ПРИ НУЛЕ — ПРОВАЛ, А НЕ УСПЕХ. Пол волны нельзя СНЯТЬ, его можно
# только СУЗИТЬ. Ноль алертов anomaly_detection ПРИ нуле подавлений означает
# не «пол ушёл», а «детектор аномалий выключен» — и тогда величина 6.2.6.1
# получена на агенте без половины своей нагрузки, то есть не сравнима ни с
# одним прошлым прогоном куста. Именно этот исход ловит первая ветка.
#
# ПОЗИТИВНАЯ ПОЛОВИНА — ОСЬ ОБРАЗ, НЕ comm. Исключения anomaly.yaml несут
# только proc.exe_path/proc.ancestor_exe_path (никакого proc.comm), поэтому
# подделка ИМЕНИ доверенного демона обязана аномалию поднять. Читается по
# срезам вокруг подачи (3) критерия 6.2.4.5 — единственного места прогона, где
# заведомо есть comm доверенного демона с чужим образом. Ноль здесь НЕ провал:
# аномалия EWMA-пороговая, и одна подача может честно не перейти порог —
# поэтому исход называется НЕИЗМЕРИМОЙ половиной, а не ложью.
# ═════════════════════════════════════════════════════════════════════════════
echo "--- 6.2.6.20: пол волны (anomaly_detection) назван и переехал в исключения (№283) ---"
_w626_anom_vol=$(( $(_w626_metric_sum ebpf_guard_alerts_total "anomaly_detection" "$W626_ART/metrics-window-end.txt") \
                 + $(_w626_metric_sum ebpf_guard_alerts_filtered_total "anomaly_detection" "$W626_ART/metrics-window-end.txt") \
                 - $(_w626_metric_sum ebpf_guard_alerts_total "anomaly_detection" "$W626_ART/metrics-window-start.txt") \
                 - $(_w626_metric_sum ebpf_guard_alerts_filtered_total "anomaly_detection" "$W626_ART/metrics-window-start.txt") ))
_w626_anom_exc_out=""
_w626_anom_exc=0
if [ "$W626_LIB_OK" -eq 1 ]; then
    _w626_anom_exc_out=$(w626_anomaly_exceptions "$W626_ART/metrics-window-start.txt" "$W626_ART/metrics-window-end.txt")
    printf '%s\n' "$_w626_anom_exc_out" | sed 's/^/    /'
    _w626_anom_exc=$(printf '%s\n' "$_w626_anom_exc_out" | awk '$1=="ИТОГО"{sub("delta=","",$2); print $2}')
fi
echo "  алертов anomaly_detection за окно (после исключений): ${_w626_anom_vol} (база 6.2.5 = 8/окно, без слоя исключений вовсе)"
echo "  подавлений rule_exceptions_total{rule_id=\"anomaly_detection\"} за окно: ${_w626_anom_exc:-0} — это и есть ДОКАЗАТЕЛЬСТВО ПЕРЕЕЗДА объёма (той же метрикой, что у YAML-правил)"
# 6.2.9.F.1 (№292, item 1 волны 6.2.9.F): СТОРОЖ ПОПЫТОК — ноль подавлений
# отличается по причине в зависимости от того, вызывался ли слой ВООБЩЕ.
# Архив collect-6.2.6-run2 показал 427→452 (+25 попыток) при +0 совпадений:
# старая форма критерия читала это как «слой не задеплоен либо не
# вызывается» — диагноз, опровергнутый этой же метрикой (слой вызван 25 раз,
# просто ни один из четырёх кандидатов item 4 не оказался в списке
# verified-daemon-*). Три состояния: 0 попыток — слой НЕ ДОСТИГНУТ (провал);
# N попыток, 0 совпадений — слой ДОСТИГНУТ, ОСЬ НЕ ТА (не провал сам по себе);
# N попыток, M>0 совпадений — слой РАБОТАЕТ.
_w626_anom_attempts=$(( $(_w626_metric_sum ebpf_guard_rule_exception_evaluations_total "anomaly_detection" "$W626_ART/metrics-window-end.txt") \
                      - $(_w626_metric_sum ebpf_guard_rule_exception_evaluations_total "anomaly_detection" "$W626_ART/metrics-window-start.txt") ))
echo "  попыток EvaluateNamedExceptions{rule_id=\"anomaly_detection\"} за окно: ${_w626_anom_attempts:-0} (0 отличает «слой не достигнут» от «слой достигнут, ось не та»)"
# СОБСТВЕННАЯ ВЕРДИКТНАЯ СТРОКА item 1. Без неё критерий 6.2.9.F.1 живёт
# только ВНУТРИ веток соседнего критерия: прогон, на котором обе ветки не
# исполнились (библиотека не подключилась — НЕИЗМЕРИМ выше по потоку),
# неотличим от прогона, где потребитель счётчика просто не был написан, —
# ровно тот класс, ради которого заведён страж полноты (№269/№270). Здесь
# метка называет ТРИ состояния словом и выносится безусловно.
if [ "${_w626_anom_attempts:-0}" -gt 0 ] && [ "${_w626_anom_exc:-0}" -gt 0 ]; then
    pass "6.2.9.F.1 ИЗМЕРЕНО (№292, порог величине не назначается): СЛОЙ РАБОТАЕТ — ${_w626_anom_attempts} попыток слоя именованных исключений по anomaly_detection за окно при ${_w626_anom_exc} совпадениях"
elif [ "${_w626_anom_attempts:-0}" -gt 0 ]; then
    pass "6.2.9.F.1 ИЗМЕРЕНО (№292, порог величине не назначается): СЛОЙ ДОСТИГНУТ, ОСЬ НЕ ТА — ${_w626_anom_attempts} попыток слоя именованных исключений по anomaly_detection за окно при НУЛЕ совпадений. Ноль подавлений здесь продуктовый, а не приборный: счётчик попыток отличает его от невызванного слоя, чего прежняя форма критерия сделать не могла"
else
    die "6.2.9.F.1 ПРОВАЛЕН (№292): СЛОЙ НЕ ДОСТИГНУТ — ноль попыток слоя именованных исключений по anomaly_detection за окно. Либо anomaly.yaml не задеплоен, либо EvaluateNamedExceptions не вызывается, либо бинарь на стенде старше правки, заводившей счётчик попыток"
fi

# позитивная половина: подделка имени доверенного демона в подаче (3) 6.2.4.5
_w626_anom_spoof="НЕ_СНЯТА"
if [ "$W626_LIB_OK" -eq 1 ] && [ -s "$W626_ART/metrics-spoof-0.txt" ] && [ -s "$W626_ART/metrics-spoof-1.txt" ]; then
    _w626_anom_spoof=$(w626_volume_by_source "$W626_ART/metrics-spoof-0.txt" "$W626_ART/metrics-spoof-1.txt" anomaly_detection cron | awk '{s+=$3} END{printf "%d", s+0}')
fi
echo "  позитивная половина (ось образ, не comm): алертов anomaly_detection с comm=cron за подачу подделки (3) 6.2.4.5 = ${_w626_anom_spoof}"

if [ "$W626_LIB_OK" -ne 1 ]; then
    die "6.2.6.20 НЕИЗМЕРИМ: библиотека не подключилась — переезд объёма в исключения доказывать нечем"
elif [ "${_w626_anom_attempts:-0}" -eq 0 ]; then
    die "6.2.6.20 ПРОВАЛЕН (№283/№292): СЛОЙ НЕ ДОСТИГНУТ — 0 попыток EvaluateNamedExceptions{rule_id=\"anomaly_detection\"} за окно (двойной ноль, ${_w626_anom_vol:-0} алертов И 0 подавлений). Пол волны нельзя снять — можно только сузить, поэтому нулевые попытки означают выключенный детектор аномалий или незадеплоенный слой исключений, а не успешное сужение. Величина 6.2.6.1 получена на агенте без половины своей нагрузки и с прошлыми прогонами куста не сравнима"
elif [ "${_w626_anom_exc:-0}" -eq 0 ]; then
    pass "6.2.6.20 ИЗМЕРЕНО (№283/№292, item 1 волны 6.2.9.F): СЛОЙ ДОСТИГНУТ, ОСЬ НЕ ТА — ${_w626_anom_attempts} попыток EvaluateNamedExceptions{rule_id=\"anomaly_detection\"} за окно, 0 подавлений, ${_w626_anom_vol} алертов anomaly_detection доехало. Слой НЕ выключен (это отличает его от двойного нуля выше) — ни один из сработавших кандидатов не нёс proc.exe_path/proc.ancestor_exe_path из списка verified-daemon-*. Пол волны остаётся ВНЕ сужения куста по факту, но аппарат item 4 задеплоен и вызывается — прежний диагноз «не задеплоен либо не вызывается» (найден ложным разбором №292) этим прогоном опровергнут"
elif [ "$_w626_anom_spoof" = "НЕ_СНЯТА" ] || [ "${_w626_anom_spoof:-0}" -eq 0 ]; then
    pass "6.2.6.20 ИЗМЕРЕНО (№283, порог величине не назначается): пол волны назван числом — ${_w626_anom_vol} алертов anomaly_detection за окно ПОСЛЕ ${_w626_anom_exc} подавлений (база 6.2.5 = 8/окно вовсе без слоя исключений), объём ПЕРЕЕХАЛ в rule_exceptions_total, а не исчез. Позитивная половина (подделка имени поднимает аномалию) НЕИЗМЕРИМА на этом прогоне: подача (3) дала ${_w626_anom_spoof} — аномалия EWMA-пороговая, одна подача честно может порога не перейти, и ноль здесь приборный, а не вердикт"
else
    pass "6.2.6.20 ДОСТИГНУТО (№283): ${_w626_anom_vol} алертов anomaly_detection за окно после ${_w626_anom_exc} подавлений — объём переехал в исключение, а не исчез; позитивная половина взята числом: подделка имени доверенного демона (comm=cron, чужой образ) подняла ${_w626_anom_spoof} аномалий, то есть ось исключения — ОБРАЗ, а не имя"
fi

# ═════════════════════════════════════════════════════════════════════════════
# ПОДАЧИ ДЛЯ 6.2.4.7 и 6.2.6.16 (вердикты выносятся ниже, вместе с 6.2.4.6 —
# им нужен один и тот же снимок инцидентов).
#
# 6.2.4.7 — ПОБЕГ ПО-ПРЕЖНЕМУ ПРОМОТИРУЕТСЯ. Item 2 волны сузил шлюз
# промоушена (лист внутри доверенного контейнерного дерева больше не взводит
# HasUntrustedSignal в одиночку). Этот контроль — его отрицательный контроль:
# правка обязана убрать ЛОЖЬ, а не ДЕТЕКТ. Подача — настоящий вход в хостовые
# namespace'ы (setns/nsenter) и чтение /proc/modules, то есть ровно те
# правила, которыми ложь и печаталась.
#
# 6.2.6.16 — ШЛЮЗ СУДИТСЯ ПО КОРНЮ. Подача формы архива живьём: старт пода
# даёт container_escape_*/rootkit_* рутиной инициализации namespace под
# containerd-shim/runc. Инцидент обязан остаться suspicious.
# ═════════════════════════════════════════════════════════════════════════════
echo "--- подача 6.2.4.7: побег (setns в хостовый namespace, /proc/modules) ---"
W626_ESCAPE_RULES="container_escape_nsenter container_escape_mount container_escape_pivot_root escape_pivot_root container_escape_unshare_user rootkit_proc_modules_read container_escape_cap_sys_admin"
_w626_t47=$(_w626_epoch)
_w626_metrics > "$W626_ART/metrics-escape-start.txt"
_w626_esc_done=0
if command -v nsenter >/dev/null 2>&1; then
    nsenter -t 1 -m -u -i -n -p /bin/true >/dev/null 2>&1 && _w626_esc_done=$(( _w626_esc_done + 1 ))
fi
if command -v unshare >/dev/null 2>&1; then
    unshare -Ur /bin/true >/dev/null 2>&1 && _w626_esc_done=$(( _w626_esc_done + 1 ))
fi
_w626_mod_bytes=$(cat /proc/modules 2>/dev/null | wc -c)
[ "${_w626_mod_bytes:-0}" -gt 0 ] && _w626_esc_done=$(( _w626_esc_done + 1 ))
sleep "$W626_SETTLE"
echo "  подач побега состоялось: $_w626_esc_done (nsenter/unshare/чтение /proc/modules, ${_w626_mod_bytes:-0}Б)"

echo "--- подача 6.2.6.16: инициализация контейнера (старт пода) ---"
_w626_t516=$(_w626_epoch)
# снимок на t516 закрывает окно подачи 6.2.4.7 (t47..t47_end=t516) И
# одновременно открывает окно подачи 6.2.6.16 (t516..t516_end) — одна точка,
# два соседних окна без разрыва (6.2.9.F.4, №294).
_w626_metrics > "$W626_ART/metrics-t516.txt"
if [ "$W626_INSTRUMENTED" -eq 1 ]; then
    "$W626_KUBECTL" -n "$W626_NS" delete pod w626-init-probe --ignore-not-found --wait=false >/dev/null 2>&1
    "$W626_KUBECTL" -n "$W626_NS" run w626-init-probe --image=busybox:1.36 --restart=Never --command -- sleep 20 >/dev/null 2>&1
    sleep 45
    "$W626_KUBECTL" -n "$W626_NS" delete pod w626-init-probe --ignore-not-found --wait=false >/dev/null 2>&1
    sleep "$W626_SETTLE"
fi
_w626_t516_end=$(_w626_epoch)
_w626_metrics > "$W626_ART/metrics-init-end.txt"
_w626_submission_loss_guard "побег в хостовый namespace" "$W626_ART/metrics-escape-start.txt" "$W626_ART/metrics-t516.txt"
_w626_esc_loss_suffix=""
[ "${_W626_LOSS_NONZERO:-0}" -eq 1 ] && _w626_esc_loss_suffix=" — НИЖНЯЯ ОЦЕНКА (6.2.9.F.4, №294): потери внутри окна подачи = ${_W626_LOSS_LAST} событий"
_w626_submission_loss_guard "инициализация контейнера" "$W626_ART/metrics-t516.txt" "$W626_ART/metrics-init-end.txt"
_w626_init_loss_suffix=""
[ "${_W626_LOSS_NONZERO:-0}" -eq 1 ] && _w626_init_loss_suffix=" — НИЖНЯЯ ОЦЕНКА (6.2.9.F.4, №294): потери внутри окна подачи = ${_W626_LOSS_LAST} событий"

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.4.6 ИНЦИДЕНТНЫЙ СЛОЙ ЗА ПРОГОН ЦЕЛИКОМ (№235, ПЕРЕСТРОЕН №251,
# ПЕРЕИМЕНОВАН И ДОПОЛНЕН ITEM 3 ВОЛНЫ 6.2.6).
#
# МЕТКА. Постановка волны 6.2.6 требует критерий 6.2.4.6 (долг волны 6.2.4,
# метка сохранена намеренно — память criteria-index-pins-replay-labels), и
# он ЗАМЕНЯЕТ 6.2.3.7. Прогон 6.2.4 напечатал здесь старую метку 6.2.3.7 —
# это и есть находка №269 («метка, реализованная под чужим номером, считается
# отсутствующей»), и страж полноты 6.2.6.18 её ловит. Отличие 6.2.4.6 от
# 6.2.3.7 по существу: прощения фазой атак больше нет, вычитается ТОЛЬКО
# окно собственных стартов подов контроля 6.2.6.10 (item 3, №263).
#
# №251: старая версия (6.2.2.9) проверяла корень инцидента только против
# runc:[...]/flannel/comm-измерителя и промахивалась мимо остального
# W626_NODE_ACTORS (containerd-shim, k3s-server, kubelet, coredns,
# local-path-prov, kube-proxy, pause, iptables/ip6tables, kubectl, bridge,
# loopback) — список УЖЕ БЫЛ в файле, цикл его не использовал. Здесь корень
# сверяется с ПОЛНЫМ W626_NODE_ACTORS ∪ W626_INSTR_COMMS_FLAT.
#
# Плюс разделение по фазам: инцидент таким корнем, чьё время попадает в
# [_w626_attack_phase_start, _w626_attack_phase_end] (окно позитивных
# контролей и инъекций этого же прогона), есть ОЖИДАЕМЫЙ true positive —
# печатается, но в ложь не засчитывается. Инцидент того же корня ВНЕ этого
# окна (то есть в тихом окне объёма, до открытия входа) — засчитывается:
# там штатная работа ноды не была спровоцирована ничем этого прогона, и
# incident_confirmed_attack на ней — ложь слоя, а не ожидаемый эффект
# инъекции. Не «величина без порога», как в 6.2.1.5: вердикт.
# ─────────────────────────────────────────────────────────────────────────────
# ─────────────────────────────────────────────────────────────────────────────
# ПОЛОЖИТЕЛЬНЫЙ КОНТРОЛЬ ОСИ ЮНИТА (item 4 волны 6.2.9.F.1, под меткой 6.2.4.6).
#
# Правка item 4 снимает ярлык confirmed_attack с МЯГКОЙ работы доверенного
# юнита. Без этого контроля она снимала бы ложь и ДЕТЕКТ одинаково молча:
# «ноль ложных инцидентов» читался бы как успех и в том случае, когда слой
# перестал промотировать вообще что-либо под юнитом из списка.
#
# Контроль: транзиентный юнит w626-fake-motd.service (ВНЕСЁН В trusted_units
# намеренно — иначе он ничего не доказывает) запускает КОПИЮ bash из /tmp,
# которая читает /etc/shadow и ходит в сеть. Ожидание: инцидент обязан
# остаться incident_confirmed_attack — образ из мирописуемого каталога есть
# твёрдая улика, которой список юнитов не подчиняется.
#
# Почему копия bash, а не скрипт: у скрипта comm — имя интерпретатора
# (память shebang-control-comm-is-interpreter), а нужно, чтобы САМ алертующий
# процесс исполнялся из /tmp; и чтение /etc/shadow, и TCP-соединение делаются
# встроенными средствами (read, /dev/tcp), то есть тем же pid.
_W626_FAKE_UNIT="w626-fake-motd"
_w626_fake_attack=0
_w626_fake_ran=0
echo "--- 6.2.4.6 положительный контроль (item 4): атака ВНУТРИ доверенного юнита обязана промотироваться ---"
if [ -n "${_w626_units:-}" ] || grep -qE '^[[:space:]]*trusted_units:' "$_w626_cfg" 2>/dev/null; then
    systemctl reset-failed "${_W626_FAKE_UNIT}.service" >/dev/null 2>&1
    cp /bin/bash /tmp/w626fakemotd 2>/dev/null && chmod 755 /tmp/w626fakemotd 2>/dev/null
    # ДВЕ ПРАВКИ ПОЛЕЗНОЙ НАГРУЗКИ (ревизия 14.09.2026, до прогона):
    #
    # (1) ПРОЦЕСС ОБЯЗАН ПЕРЕЖИТЬ СВОЙ СОБСТВЕННЫЙ readlink. Твёрдая улика
    #     этого контроля — образ из мирописуемого каталога, а он снимается
    #     readlink'ом /proc/<pid>/exe в момент РАЗБОРА алерта. Прежняя
    #     нагрузка заканчивалась `exit 0` сразу после чтений, то есть
    #     проигрывала ровно ту гонку, которой посвящены №261/№285/№303: образ
    #     не разрешился бы, HasHardEvidence не взвелось бы, доверенный юнит
    #     простил бы инцидент — и контроль объявил бы «детект мёртв» там, где
    #     мёртв был ПРИБОР. Процесс держится живым W626_FAKE_LINGER секунд
    #     ПОСЛЕ улик — ждёт обычным /bin/sleep. Ждать встроенным `read -t` на
    #     /dev/zero нельзя: NUL-байты идут бесконечным потоком, и `read`
    #     превратился бы в восьмисекундный busy-loop, то есть сам стал бы
    #     источником шума в измеряемом окне. Дочерний sleep стоит один
    #     execve, а алертующий процесс — по-прежнему сам bash из /tmp, и
    #     живёт он всё это время.
    # (2) ОТКАЗ /dev/tcp НЕ ИМЕЕТ ПРАВА УБИВАТЬ НАГРУЗКУ. На 127.0.0.1:19090
    #     никто не слушает намеренно (нужен SYN, а не сессия), и в
    #     неинтерактивном bash неудачный `exec` с перенаправлением завершает
    #     оболочку немедленно — то есть половина (1) снималась бы не всегда, а
    #     только когда порт случайно занят. Открытие уведено в подоболочку.
    _W626_FAKE_LINGER="${W626_FAKE_LINGER:-8}"
    if [ -x /tmp/w626fakemotd ] && systemd-run --quiet --unit="$_W626_FAKE_UNIT" --property=RemainAfterExit=yes \
        /tmp/w626fakemotd -c 'read -r _l < /etc/shadow; read -r _g < /etc/gshadow; read -r _s < /etc/sudoers; cat /proc/self/maps >/dev/null; (exec 3<>/dev/tcp/127.0.0.1/19090) 2>/dev/null; sleep '"$_W626_FAKE_LINGER"'; exit 0' >/dev/null 2>&1; then
        _w626_fake_ran=1
        # Ждать дольше, чем живёт нагрузка: иначе срез алертов снимается до
        # того, как инцидент вообще сложился.
        sleep "$(( W626_SETTLE > _W626_FAKE_LINGER ? W626_SETTLE : _W626_FAKE_LINGER + 5 ))"
        _w626_alerts > "$W626_ART/alerts-fake-motd.json"
        _w626_fake_attack=$(jq '[.[]|select(.rule_id=="incident_confirmed_attack")
            |select(((.details.root_unit // "") | test("w626-fake-motd")) or ((.details.root_comm // "") | test("w626fakemotd")) or (((.details.comms // []) | join(",")) | test("w626fakemotd")))] | length' \
            "$W626_ART/alerts-fake-motd.json" 2>/dev/null)
        _w626_fake_attack=${_w626_fake_attack:-0}
        echo "  юнит $_W626_FAKE_UNIT отработал (копия bash из /tmp: /etc/shadow + /dev/tcp, держался живым ${_W626_FAKE_LINGER}с ради readlink); подтверждённых атак под ним: ${_w626_fake_attack}"
    else
        echo "  юнит $_W626_FAKE_UNIT НЕ запустился (нет /bin/bash или systemd-run отказал) — половина «детект жив» этим прогоном не снята"
    fi
    systemctl stop "${_W626_FAKE_UNIT}.service" >/dev/null 2>&1
    systemctl reset-failed "${_W626_FAKE_UNIT}.service" >/dev/null 2>&1
    rm -f /tmp/w626fakemotd 2>/dev/null
else
    echo "  correlator.trusted_units в $_w626_cfg не задан — ось item 4 выключена, положительный контроль не требуется"
fi

_w626_attack_phase_end=$(_w626_epoch)
printf 'attack_phase_start=%s\nattack_phase_end=%s\n' "$_w626_attack_phase_start" "$_w626_attack_phase_end" >> "$W626_ART/window-epoch.txt"
echo "--- 6.2.4.6: инцидентный слой не называет атакой штатную работу ноды (долг 6.2.4, заменяет 6.2.3.7) ---"
# ITEM 4 ВОЛНЫ 6.2.9.F.1: список доверенных ЮНИТОВ печатается в архив ЦЕЛИКОМ.
# Без него «ноль ложных incident_confirmed_attack» неотличим от «список
# раздули перед прогоном»: вердикт обязан читаться вместе с тем, что ему
# разрешили простить. Рядом — состояние самой оси по метрике: «resolved = 0»
# при непустом списке означает, что юнит корня не снимается вовсе (нет
# резолвера, procfs, или корень умирает раньше), и тогда ось не работает, а
# не «лжи нет».
# СМОК 14.09.2026 НАШЁЛ ДЕФЕКТ ЭТОЙ САМОЙ ПЕЧАТИ: прежняя awk-программа
# выходила на ПЕРВОЙ же строке блока, не являющейся элементом списка, — то
# есть на строке КОММЕНТАРИЯ внутри списка. В конфиге стенда за таким
# комментарием стоит `w626-fake-motd.service`, юнит положительного контроля,
# и печать молча роняла ровно его: читатель видел 9 юнитов из 10, причём
# невидимым оказывался единственный, который в продуктовый конфиг не
# переносится. Это тот же класс, что находки №296/№300 — печатная величина
# противоречит тому, чем на самом деле кормится продукт, и «ноль лжи»
# перестаёт быть отделимым от «список раздули». Комментарии и пустые строки
# внутри блока пропускаются; выход — только на строке, которая не элемент,
# не комментарий и не пустая. Рядом печатается ЧИСЛО юнитов: список из
# одного элемента и обрезанный список так уже не спутать.
_w626_units=$(awk '
    /^[[:space:]]*trusted_units:/{f=1;next}
    f && /^[[:space:]]*#/{next}
    f && /^[[:space:]]*$/{next}
    f && /^[[:space:]]*-[[:space:]]/{sub(/^[[:space:]]*-[[:space:]]*/,"");sub(/[[:space:]]*#.*$/,"");print;next}
    f{exit}' "$_w626_cfg" 2>/dev/null | paste -sd' ' - 2>/dev/null)
_w626_units_n=$(printf '%s' "${_w626_units:-}" | wc -w | tr -d ' ')
echo "  ITEM 4 (№235→6.2.4.6): correlator.trusted_units (${_w626_units_n:-0} шт.) = ${_w626_units:-ПУСТ (ось юнита выключена)}"
# Печать выше читается из ФАЙЛА конфига. Проверка, что тот же файл получил
# АГЕНТ, снимается отдельно (иначе список печатался бы из конфига, которым
# продукт не кормится): сверяется путь --config у живого процесса.
_w626_units_cfg_live=$(tr '\0' '\n' < /proc/$(pgrep -f '/build/ebpf-guard --config' | head -1)/cmdline 2>/dev/null | sed -n 's/^--config=//p' | head -1)
if [ -n "${_w626_units_cfg_live:-}" ] && [ "$_w626_units_cfg_live" != "$_w626_cfg" ]; then
    echo "    ВНИМАНИЕ: агент запущен с конфигом $_w626_units_cfg_live, а список выше прочитан из $_w626_cfg — список НЕ есть то, чем кормится продукт"
else
    echo "    конфиг агента и источник списка совпадают: ${_w626_units_cfg_live:-путь не снят}"
fi
# Присутствие СЕРИИ проверяется отдельно от её значения: _w626_metric_sum
# печатает 0 и когда серии нет вовсе, а «ноль» и «прибора нет» — разные
# состояния (класс №269, тот же, что «метка под чужим номером»).
if grep -q '^ebpf_guard_incident_root_unit_total' "$W626_ART/metrics-window-end.txt" 2>/dev/null; then
    _w626_unit_resolved=$(_w626_metric_sum ebpf_guard_incident_root_unit_total resolved "$W626_ART/metrics-window-end.txt")
    _w626_unit_unres=$(_w626_metric_sum ebpf_guard_incident_root_unit_total unresolved "$W626_ART/metrics-window-end.txt")
    echo "    ось юнита по метрике на закрытии окна: resolved=${_w626_unit_resolved:-0} unresolved=${_w626_unit_unres:-0} (resolved=0 при НЕПУСТОМ списке = ось не сработала ни разу, и ноль лжи ниже её заслугой не является)"
else
    echo "    ось юнита по метрике: СЕРИИ ebpf_guard_incident_root_unit_total НЕТ — правка item 4 на стенде не задеплоена, и вердикт ниже к ней отношения не имеет"
fi
# Окно стартов подов 6.2.6.10 (item 3). Если контроль churn не исполнялся
# (прогон неприборный), окно пустое — вычитать нечего, и вердикт выносится за
# прогон целиком, как того и требует постановка.
: "${_w626_pod_start_phase_start:=0}"
: "${_w626_pod_start_phase_end:=0}"
printf 'pod_start_phase_start=%s\npod_start_phase_end=%s\n' "$_w626_pod_start_phase_start" "$_w626_pod_start_phase_end" >> "$W626_ART/window-epoch.txt"
echo "  окно стартов подов контроля 6.2.6.10 (item 3, вычитается из вердикта): [$(_w626_utc "${_w626_pod_start_phase_start:-0}"), $(_w626_utc "${_w626_pod_start_phase_end:-0}")]"
echo "  фаза атак (позитивные контроли+инъекции этого прогона): [$(_w626_utc "$_w626_attack_phase_start"), $(_w626_utc "$_w626_attack_phase_end")]"
_w626_alerts > "$W626_ART/alerts-incidents.json"
_w626_inc_all=$(jq '[.[]|select(.rule_id=="incident_confirmed_attack")]|length' "$W626_ART/alerts-incidents.json" 2>/dev/null || echo 0)
echo "  incident_confirmed_attack за прогон: $_w626_inc_all"
echo "  по корневому comm:"
jq -r '[.[]|select(.rule_id=="incident_confirmed_attack")]|group_by(.details.root_comm // .comm)|map({c:(.[0].details.root_comm // .[0].comm),n:length})|sort_by(-.n)[]|"    \(.c): \(.n)"' "$W626_ART/alerts-incidents.json" 2>/dev/null | head -15
# ─── ДВА КЛАССА КОРНЯ СУДЯТСЯ ПО-РАЗНОМУ (правка смока 06.09.2026, ДО прогона).
#
# Первая версия этого блока судила ОБА класса корня одним правилом «вне фазы
# атак = ложь». Смок показал, что правило неисполнимо по построению, и оба
# провала были СВОИМИ:
#   * инцидент 14:26:57, цепочка bash → bash → bash → bash → cut — это
#     преflight самого измерителя (churn подов, kubectl), до открытия окна;
#   * инцидент 14:28:33, цепочка bash → … → cat, comm=ld — это окно профиля
#     (`go tool pprof`), между закрытием тихого окна и началом фазы атак.
# Измеритель РАБОТАЕТ вне фазы атак — в прологе, в преflight'е, между окнами и
# после фазы; ни один из этих отрезков не был в [attack_phase_start,
# attack_phase_end], и его собственные цепочки печатались как ложь продукта.
# Комментарий выше называет умысел прямо: «вне этого окна (ТО ЕСТЬ В ТИХОМ
# ОКНЕ ОБЪЁМА)». Тихое окно и «всё вне фазы атак» — не одно и то же, и здесь
# восстановлен умысел, а не смягчён критерий.
#
#   КОРЕНЬ-ИЗМЕРИТЕЛЬ  → ложь ТОЛЬКО внутри [t0,t1]. Там измеритель обязан не
#                        работать вовсе (это же и меряет 6.2.6.3), поэтому
#                        инцидент с его корнем в окне есть дефект; вне окна —
#                        его штатная работа, печатается и в ложь не идёт.
#   КОРЕНЬ-НОДА        → ложь ЗА ПРОГОН ЦЕЛИКОМ, как требует постановка
#                        («корень которого в W626_NODE_ACTORS — ноль»).
#                        Прежняя реализация прощала их внутри фазы атак — но
#                        containerd-shim, поднимающий контейнер, есть штатная
#                        работа ноды независимо от того, чей kubectl попросил
#                        под. Прощение внутри фазы выхолащивало критерий ровно
#                        там, где живёт находка №250: смок дал 5 таких
#                        инцидентов (containerd-shim 4, k3s-server 1) и все
#                        пять были списаны в «ожидаемый TP».
# Пересечение списков (kubectl входит в оба) разрешается в пользу измерителя —
# на этом стенде kubectl зовёт только он; имена пересечения печатаются.
_w626_inc_jq_root='(.details.root_comm // .comm)'
_w626_inc_count() { # $1=класс (instr|node) $2=режим (win|outwin|phase|outphase|podstart|outpodstart|all)
    # Сам счёт живёт в wave6.2.6-metrics-lib.sh (w626_incident_roots): у
    # библиотеки есть офлайн-сторож на архиве collect-6.2.4, где обе лжи
    # инцидентного слоя известны поимённо. Критерий этого блока переписывался
    # четыре волны подряд и ни разу не проверялся до стенда — теперь
    # проверяется.
    w626_incident_roots "$W626_ART/alerts-incidents.json" "$1" "$2" \
        "${_w626_t0:-0}" "${_w626_t1:-0}" \
        "$_w626_attack_phase_start" "$_w626_attack_phase_end" \
        "${_w626_pod_start_phase_start:-0}" "${_w626_pod_start_phase_end:-0}" \
        "$W626_INSTR_COMMS_FLAT" "$W626_NODE_ACTORS"
}
_w626_inc_node_all=$(_w626_inc_count node all | jq 'length' 2>/dev/null)
_w626_inc_node_names=$(_w626_inc_count node all | jq -r 'unique|join(" ")' 2>/dev/null)
_w626_inc_node_phase=$(_w626_inc_count node phase | jq 'length' 2>/dev/null)
# ITEM 3 (№263): вердиктная величина 6.2.4.6 — нодовые корни ВНЕ окна
# собственных стартов подов; внутри него ложь считается и печатается, но в
# вердикт не идёт (цена старта пода — предмет отдельного критерия 6.2.6.10 со
# своим порогом, а не повод простить весь прогон).
_w626_inc_node_podstart=$(_w626_inc_count node podstart | jq 'length' 2>/dev/null)
_w626_inc_node_podstart_names=$(_w626_inc_count node podstart | jq -r 'unique|join(" ")' 2>/dev/null)
_w626_inc_node_out=$(_w626_inc_count node outpodstart | jq 'length' 2>/dev/null)
_w626_inc_node_out_names=$(_w626_inc_count node outpodstart | jq -r 'unique|join(" ")' 2>/dev/null)
_w626_inc_instr_win=$(_w626_inc_count instr win | jq 'length' 2>/dev/null)
_w626_inc_instr_win_names=$(_w626_inc_count instr win | jq -r 'unique|join(" ")' 2>/dev/null)
_w626_inc_instr_out=$(_w626_inc_count instr outwin | jq 'length' 2>/dev/null)
# Пересечение — чистой оболочкой, без внешних команд: любой лишний execve
# здесь есть собственное событие измерителя (тот же принцип, что у встроенного
# printf в _w626_epoch).
_w626_inc_overlap=""
for _w626_ov in $W626_INSTR_COMMS_FLAT; do
    case " $W626_NODE_ACTORS " in *" $_w626_ov "*) _w626_inc_overlap="$_w626_inc_overlap $_w626_ov" ;; esac
done
_w626_inc_overlap="${_w626_inc_overlap# }"

# ITEM 7 (№280) — ТРЕТИЙ КЛАСС, ПО ДЕРЕВУ, а не по корню (w626_incident_tree_bg,
# wave6.2.6-metrics-lib.sh). Ловит инцидент вида
# sshd→sshd→sh→run-parts→00-header→uname — корень sshd не входит ни в
# W626_NODE_ACTORS, ни в W626_INSTR_COMMS_FLAT, и прежняя (только по корню)
# классификация его вообще не видела (архив collect-6.2.5, 19:46:18Z,
# score=59, verdict=attack — инцидент напечатан справочно строкой выше
# "по корневому comm", но ни в одну из двух корзин вердикта не попадал).
# Корни, уже посчитанные классами node/instr, исключаются явно — иначе один
# и тот же инцидент (например containerd-shim с run-parts где-то в хвосте)
# считался бы дважды. Окно стартов подов вычитается тем же принципом, что и
# у node-класса (item 3, №263).
_w626_inc_tree_exclude="$W626_NODE_ACTORS $W626_INSTR_COMMS_FLAT"
_w626_inc_tree_bg=$(w626_incident_tree_bg "$W626_ART/alerts-incidents.json" "$_w626_inc_tree_exclude" \
    "${_w626_pod_start_phase_start:-0}" "${_w626_pod_start_phase_end:-0}")
_w626_inc_tree_bg_count=$(printf '%s\n' "$_w626_inc_tree_bg" | grep -c . || true)
_w626_inc_tree_bg_names=$(printf '%s\n' "$_w626_inc_tree_bg" | awk -F'\t' 'NF{print $1"["$2"]"}' | paste -sd' ' - 2>/dev/null)

_w626_inc_bad=$(( ${_w626_inc_node_out:-0} + ${_w626_inc_instr_win:-0} + ${_w626_inc_tree_bg_count:-0} ))
_w626_inc_names="${_w626_inc_node_out_names:-}${_w626_inc_instr_win_names:+ }${_w626_inc_instr_win_names:-}${_w626_inc_tree_bg_names:+ }${_w626_inc_tree_bg_names:-}"
echo "  корень НОДОВЫЙ АКТОР, за прогон целиком: ${_w626_inc_node_all:-0} (${_w626_inc_node_names:-нет})"
echo "    из них внутри фазы атак: ${_w626_inc_node_phase:-0} — 6.2.3.7 прощала именно их; 6.2.4.6 прощения фазой атак НЕ делает"
echo "    из них ВНУТРИ окна стартов подов 6.2.6.10 (item 3, печатается, в вердикт НЕ идёт): ${_w626_inc_node_podstart:-0} (${_w626_inc_node_podstart_names:-нет})"
echo "    ВЕРДИКТНАЯ величина 6.2.4.6 — нодовые корни ВНЕ окна стартов подов: ${_w626_inc_node_out:-0} (${_w626_inc_node_out_names:-нет})"
echo "  корень ИЗМЕРИТЕЛЬ внутри тихого окна [t0,t1] (ложь): ${_w626_inc_instr_win:-0} (${_w626_inc_instr_win_names:-нет})"
echo "  корень ИЗМЕРИТЕЛЬ вне тихого окна (его штатная работа — печатается, в ложь не идёт): ${_w626_inc_instr_out:-0}"
echo "  ПО ДЕРЕВУ (item 7, №280) — корень ВНЕ обоих реестров, но цепочка несёт фонового актора ноды: ${_w626_inc_tree_bg_count:-0} (${_w626_inc_tree_bg_names:-нет})"
echo "  пересечение списков (разрешено в пользу измерителя): ${_w626_inc_overlap:-нет}"
if [ "${_w626_inc_all:-0}" -gt 0 ]; then
    echo "  доля ложных от всех инцидентов прогона: $(awk -v b="${_w626_inc_bad:-0}" -v n="$_w626_inc_all" 'BEGIN{printf "%.1f%%", 100.0*b/n}')"
fi
if [ "${_w626_inc_bad:-0}" -gt 0 ]; then
    die "6.2.4.6 ПРОВАЛЕН: инцидентный слой назвал подтверждённой атакой штатную работу ноды (${_w626_inc_node_out:-0} вне окна стартов подов; всего за прогон ${_w626_inc_node_all:-0}), работу измерителя внутри тихого окна (${_w626_inc_instr_win:-0}) или фоновую работу ноды по ДЕРЕВУ вне обоих реестров (${_w626_inc_tree_bg_count:-0}, item 7 №280) — корни: ${_w626_inc_names:-?}. Порог слою назначается ПОСЛЕ того, как ложь убрана, а не вместо этого (находка №235/№251/№280)"
elif [ -n "${_w626_units:-}" ] && [ "${_w626_fake_ran:-0}" -eq 1 ] && [ "${_w626_fake_attack:-0}" -lt 1 ]; then
    die "6.2.4.6 НЕИЗМЕРИМ (item 4, положительный контроль): ложных инцидентов ноль, НО и подложная атака внутри доверенного юнита ($_W626_FAKE_UNIT: копия bash из /tmp читает /etc/shadow и ходит в сеть) НЕ промотирована — ось юнита сняла ложь и ДЕТЕКТ одинаково. Ноль лжи при мёртвом детекте вердиктом не является (память positive-control-needs-result-sentinel)"
else
    pass "6.2.4.6 ДОСТИГНУТО: ни один incident_confirmed_attack не имеет корнем нодового актора вне окна стартов подов (внутри него — ${_w626_inc_node_podstart:-0}, item 3), ни один — корнем измерителя внутри тихого окна, и ни один — фоновой работой ноды по дереву вне обоих реестров (item 7): всего инцидентов-атак за прогон $_w626_inc_all, из них работа измерителя вне окна: ${_w626_inc_instr_out:-0}"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.4.7 (долг 6.2.4) — ПОБЕГ ПО-ПРЕЖНЕМУ ПРОМОТИРУЕТСЯ.
#
# Отрицательный контроль правки item 2: она обязана убрать ЛОЖЬ, а не ДЕТЕКТ.
# Подача сделана выше (setns в хостовые namespace'ы, user-namespace, чтение
# /proc/modules). Читается двумя ступенями, и порядок ступеней — часть
# критерия: сначала «правила вообще поднялись» (иначе ноль ниже приборный:
# нет хука — нет события — нет промоушена, и item 2 тут ни при чём), и лишь
# затем «инцидент промотирован в attack».
#
# ITEM 7 (№278): вторая ступень считала ЛЮБОЙ incident_confirmed_attack за
# окном подачи как доказательство промоушена — а окно подачи ничем не
# отделено от остального прогона, и посторонний инцидент (например, чужой
# позитивный контроль этого же прогона, попавший в то же окно по времени)
# засчитывался бы как подтверждение item 2, хотя к setns/`/proc/modules`
# отношения не имеет. Подающие процессы ЭТОГО контроля поимённо известны —
# `nsenter`/`unshare` (setns) и `cat` (чтение /proc/modules); второй счёт
# фильтруется по корню ИЗ ЭТОГО СПИСКА. Инциденты с иными корнями печатаются
# СПРАВОЧНО и в вердикт не идут.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.4.7: побег из-под пода по-прежнему промотируется (долг 6.2.4) ---"
W626_ESCAPE_SUBMITTERS="nsenter unshare cat"
# ВЕРХНЯЯ ГРАНИЦА ОКНА ПОДАЧИ (№288, найдено смоком 09.09.2026). Прежде счёт
# шёл с ОТКРЫТЫМ верхним концом (`timestamp >= t47`), а сразу за подачей побега
# идёт подача старта пода — и весь её шум (container_escape_nsenter от
# containerd/loopback/bridge/runc:[1:CHILD], escape_pivot_root и
# rootkit_proc_modules_read от runc:[2:INIT]) попадал в тот же счёт. На смоке
# из 28 «алертов побега» подаче измерителя принадлежал ОДИН
# (rootkit_proc_modules_read, comm=cat), остальные 27 — инициализация
# контейнера. То есть доказательство «детект жив» у критерия было почти
# целиком ЧУЖИМ — ровно форма находки №278 («половину доказательства составил
# инцидент, который тот же прогон называет ложью»), только на половине алертов,
# а не инцидентов. Граница — начало подачи 6.2.6.16: два окна перестают
# смешиваться, и каждое доказывает своё.
_w626_t47_end="$_w626_t516"
_w626_esc_hits=$(jq --arg ids "$W626_ESCAPE_RULES" --argjson t "$_w626_t47" --argjson te "$_w626_t47_end" \
    '[.[]|select((.rule_id as $r|($ids|split(" "))|index($r)) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $te))]|length' \
    "$W626_ART/alerts-incidents.json" 2>/dev/null)
_w626_esc_rules=$(jq -r --arg ids "$W626_ESCAPE_RULES" --argjson t "$_w626_t47" --argjson te "$_w626_t47_end" \
    '[.[]|select((.rule_id as $r|($ids|split(" "))|index($r)) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $te))|.rule_id]|unique|join(" ")' \
    "$W626_ART/alerts-incidents.json" 2>/dev/null)
# ПОИМЁННО ПО comm — сторож результата подачи (№288, вторая половина).
# Число алертов само по себе не говорит, СКОЛЬКО из них принадлежит подаче, а
# сколько фону: на смоке из 28 (старая форма) подаче принадлежали 5
# — `nsenter:2 unshare:2 cat:1`, — то есть 82% «доказательства детекта» были
# чужими. Разделение обязано быть видно числом, а не выводиться из суммы:
# ноль от подающих процессов при непустом окне означает «правила не увидели
# САМУ подачу», и это НЕ вердикт об item 2, а неизмеримость (ветка ниже).
_w626_esc_comms=$(jq -r --arg ids "$W626_ESCAPE_RULES" --argjson t "$_w626_t47" --argjson te "$_w626_t47_end" \
    '[.[]|select((.rule_id as $r|($ids|split(" "))|index($r)) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $te))]
     | group_by(.comm)|map("\(.[0].comm):\(length)")|join(" ")' "$W626_ART/alerts-incidents.json" 2>/dev/null)
_w626_esc_own=$(jq -r --arg subs "$W626_ESCAPE_SUBMITTERS" --arg ids "$W626_ESCAPE_RULES" --argjson t "$_w626_t47" --argjson te "$_w626_t47_end" \
    '[.[]|select((.rule_id as $r|($ids|split(" "))|index($r)) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $te))
       | select((.comm) as $c | ($subs|split(" "))|index($c)) ]|length' "$W626_ART/alerts-incidents.json" 2>/dev/null)
_w626_esc_inc_all=$(jq --argjson t "$_w626_t47" --argjson te "$_w626_t47_end" \
    '[.[]|select(.rule_id=="incident_confirmed_attack" and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $te))]|length' \
    "$W626_ART/alerts-incidents.json" 2>/dev/null)
_w626_esc_inc_all_roots=$(jq -r --argjson t "$_w626_t47" --argjson te "$_w626_t47_end" \
    '[.[]|select(.rule_id=="incident_confirmed_attack" and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $te))|(.details.root_comm // .comm)]|unique|join(" ")' \
    "$W626_ART/alerts-incidents.json" 2>/dev/null)
# КОРЕНЬ, ЦЕПОЧКА ИЛИ СОСТАВ (№294, разбор архива collect-6.2.6,
# 10.09.2026). Правка №288 (комментарий выше) перешла с root_comm на
# process_chain — но process_chain у incident_confirmed_attack есть ОДНА
# ветвь предков КОРНЯ (`bash→bash→…→curl`), а не список участников
# инцидента. Подающие процессы (nsenter/unshare/cat) в дереве стоят
# БРАТЬЯМИ друг другу и корню, не предками — ни один не попадает в
# process_chain никогда, и критерий 6.2.4.7 был обречён на «ПРОВАЛЕН»
# структурно, тем же способом, каким №288 был обречён на root_comm.
#
# Архив прогона это подтвердил числом: инцидент
# alert-inc-1788970459168-60-attack (16:14:19.466Z, score 51) содержит
# 5 ИЗ 7 алертов окна подачи (пересечение alert_ids), но
# process_chain=[bash,bash,bash,bash,bash,bash,curl] не несёт ни nsenter,
# ни unshare, ни cat — их несёт details.comms (участники инцидента
# ПЛОСКИМ списком, без древесной позиции): comms=[curl,cat,nsenter,true,
# unshare]. Именно это поле IncidentTracker пишет как состав, и по нему
# признание подачи своей взаимодействует с реальными данными, а не с
# гаданием по одной ветви.
#
# ПОЧЕМУ .details.comms, А НЕ ПЕРЕСЕЧЕНИЕ alert_ids. Оба поля дают
# одинаковый ответ на этом архиве, но alert_ids требует пересечения с
# отдельно собранным списком id алертов подачи — лишняя зависимость от
# другого запроса того же окна. comms — минимальный самодостаточный вход:
# сам инцидент отвечает на вопрос «наш ли участник внутри».
_w626_esc_inc=$(jq --arg subs "$W626_ESCAPE_SUBMITTERS" --argjson t "$_w626_t47" --argjson te "$_w626_t47_end" \
    '[.[]|select(.rule_id=="incident_confirmed_attack" and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $te)
        and ((.details.comms // []) | any(. as $c | ($subs|split(" "))|index($c) != null)))]|length' \
    "$W626_ART/alerts-incidents.json" 2>/dev/null)
_w626_esc_inc_roots=$(jq -r --arg subs "$W626_ESCAPE_SUBMITTERS" --argjson t "$_w626_t47" --argjson te "$_w626_t47_end" \
    '[.[]|select(.rule_id=="incident_confirmed_attack" and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t) and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $te)
        and ((.details.comms // []) | any(. as $c | ($subs|split(" "))|index($c) != null)))
      | "\((.details.root_comm // .comm))[\(.details.process_chain // [] | join("→"))]"]|unique|join(" ")' \
    "$W626_ART/alerts-incidents.json" 2>/dev/null)
echo "  окно подачи побега [$(_w626_utc "$_w626_t47"), $(_w626_utc "$_w626_t47_end")] — верхняя граница есть начало подачи 6.2.6.16 (№288: без неё в счёт шёл шум старта пода)"
echo "  подач состоялось: ${_w626_esc_done:-0}; алертов правил побега В ОКНЕ подачи: ${_w626_esc_hits:-0} (${_w626_esc_rules:-нет})"
echo "  из них от САМИХ подающих процессов (${W626_ESCAPE_SUBMITTERS}): ${_w626_esc_own:-0}; поимённо по comm: ${_w626_esc_comms:-нет}"
echo "  incident_confirmed_attack в окне подачи, ВСЕ корни (справочно): ${_w626_esc_inc_all:-0} (${_w626_esc_inc_all_roots:-нет})"
echo "  incident_confirmed_attack в окне подачи, подающий процесс В ЦЕПОЧКЕ (№288 — root_comm пишет КОРЕНЬ дерева, подающий стоит листом), вердиктная величина: ${_w626_esc_inc:-0} (${_w626_esc_inc_roots:-нет})"
if [ "${_w626_esc_done:-0}" -lt 1 ]; then
    die "6.2.4.7 НЕИЗМЕРИМ: ни одна подача побега не состоялась (нет nsenter/unshare, /proc/modules не прочитан) — ноль алертов приборный, а не вердикт"
elif [ "${_w626_esc_own:-0}" -lt 1 ]; then
    # НОВАЯ ВЕТКА (№288). Отделяет «подача состоялась, но правила её НЕ УВИДЕЛИ»
    # от «правила видят чужое». На смоке ${_w626_esc_hits} было 28 при нуле от
    # подающих процессов: все 28 принадлежали старту пода. Прежняя цепочка
    # ветвей объявила бы это ПРОВАЛОМ item 2 — то есть обвинила бы правку в
    # вырезанном детекте по чужим алертам.
    die "6.2.4.7 НЕИЗМЕРИМ (№288): подача состоялась (${_w626_esc_done} из трёх), в окне ${_w626_esc_hits} алертов класса побега, но НИ ОДИН не принадлежит подающим процессам (${W626_ESCAPE_SUBMITTERS}) — поимённо по comm: ${_w626_esc_comms:-нет}. Правила класса побега не увидели САМУ подачу (nsenter/unshare без своего execve-хука либо чтение вне покрытия), и всё, что в окне есть, — фон. Вердикта об item 2 из этого не следует НИКАКОГО: инцидентному слою нечего было промотировать из НАШЕЙ подачи"
elif [ "${_w626_esc_hits:-0}" -lt 1 ]; then
    die "6.2.4.7 НЕИЗМЕРИМ: подача побега состоялась (${_w626_esc_done} из трёх), а ни одно правило класса побега не поднялось. Это неизмеримость ПОДАЧИ (нет привязки хука setns/файлового чтения), а не вердикт item 2: инцидентному слою нечего было промотировать"
elif [ "${_w626_esc_inc:-0}" -lt 1 ]; then
    die "6.2.4.7 ПРОВАЛЕН: правила побега увидели САМУ подачу (${_w626_esc_own} алертов от ${W626_ESCAPE_SUBMITTERS} из ${_w626_esc_hits} в окне: ${_w626_esc_rules}), но НИ ОДИН инцидент с подающим процессом в цепочке не промотирован в attack (посторонних корней за то же окно: ${_w626_esc_inc_all:-0}, ${_w626_esc_inc_all_roots:-нет} — справочно, в вердикт не идут) — правка item 2 (containerInitTrustedRoot в шлюзе Add) вырезала ДЕТЕКТ, а не ложь. Это ровно тот исход, ради которого критерий заведён отдельной меткой${_w626_esc_loss_suffix}"
else
    pass "6.2.4.7 ДОСТИГНУТО: подача побега поднята и УЗНАНА (${_w626_esc_own} алертов от самих подающих процессов из ${_w626_esc_hits} в окне: ${_w626_esc_rules}) и дала ${_w626_esc_inc} incident_confirmed_attack с подающим процессом в цепочке (${_w626_esc_inc_roots}) — сужение шлюза промоушена детект не вырезало (item 7 №278: посторонних корней за то же окно ${_w626_esc_inc_all:-0}, в вердикт не включены)${_w626_esc_loss_suffix}"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.6.16 (№262, новый) — ШЛЮЗ ПРОМОУШЕНА СУДИТСЯ ПО КОРНЮ.
#
# Форма архива collect-6.2.4 живьём: старт пода даёт container_escape_*/
# rootkit_* рутиной инициализации namespace (mount/pivot_root/cap_sys_admin/
# proc_modules_read под containerd-shim → runc → runc:[N:STAGE]), и до item 2
# лист этого дерева (cat/mount/loopback) в одиночку взводил HasUntrustedSignal
# и переводил инцидент в attack. Инцидент обязан остаться suspicious.
#
# ОБЕ ПОЛОВИНЫ ЧИТАЮТСЯ ВМЕСТЕ: этот критерий взят только при взятом 6.2.4.7,
# иначе «инцидента нет» означает не «шлюз судит по корню», а «детекта нет
# вовсе» — постановка требует ровно этой связки.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.6.16: шлюз промоушена судится по корню (№262) ---"
_w626_init_hits=$(jq --arg ids "$W626_ESCAPE_RULES" --argjson t0 "$_w626_t516" --argjson t1 "$_w626_t516_end" \
    '[.[]|select((.rule_id as $r|($ids|split(" "))|index($r))
        and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t0)
        and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $t1)
        and (.comm|test("^(runc|containerd|conmon|crun|dockerd|pause)")))]|length' \
    "$W626_ART/alerts-incidents.json" 2>/dev/null)
_w626_init_attack=$(jq --argjson t0 "$_w626_t516" --argjson t1 "$_w626_t516_end" --arg actors "$W626_NODE_ACTORS" \
    '[.[]|select(.rule_id=="incident_confirmed_attack"
        and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t0)
        and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $t1)
        and (((.details.root_comm // .comm) as $c | (($actors|split(" "))|index($c))) != null))]|length' \
    "$W626_ART/alerts-incidents.json" 2>/dev/null)
_w626_init_attack_roots=$(jq -r --argjson t0 "$_w626_t516" --argjson t1 "$_w626_t516_end" --arg actors "$W626_NODE_ACTORS" \
    '[.[]|select(.rule_id=="incident_confirmed_attack"
        and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t0)
        and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $t1)
        and (((.details.root_comm // .comm) as $c | (($actors|split(" "))|index($c))) != null))
      | "\((.details.root_comm // .comm))[\(.details.process_chain // [] | join("→"))]"]|unique|join(" ")' \
    "$W626_ART/alerts-incidents.json" 2>/dev/null)
# ОКНО СТАРТОВ ПОДОВ 6.2.6.10 СУДИТСЯ ЗДЕСЬ ЖЕ. Item 3 вычитает его из
# вердикта 6.2.4.6 (там оно — цена старта пода, а не ложь слоя), и без этой
# половины оно не судилось бы НИЧЕМ: ровно та форма, что дала обе лжи архива
# collect-6.2.4 (containerd-shim→runc→runc:[1:CHILD] в 20:35:37 и
# k3s-server→containerd→flannel→bridge в 20:35:36 — оба внутри фазы churn).
# Вычитание из 6.2.4.6 не имеет права ничего терять: что там прощено как
# «цена старта пода», здесь обязано быть suspicious.
_w626_init_attack_churn=$(jq --argjson t0 "${_w626_pod_start_phase_start:-0}" --argjson t1 "${_w626_pod_start_phase_end:-0}" --arg actors "$W626_NODE_ACTORS"     '[.[]|select(.rule_id=="incident_confirmed_attack"
        and ($t1 > 0)
        and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) >= $t0)
        and ((.timestamp|sub("\\.[0-9]+Z$";"Z")|fromdateiso8601? // 0) <= $t1)
        and (((.details.root_comm // .comm) as $c | (($actors|split(" "))|index($c))) != null))]|length'     "$W626_ART/alerts-incidents.json" 2>/dev/null)
echo "  окно подачи [$(_w626_utc "$_w626_t516"), $(_w626_utc "$_w626_t516_end")]"
echo "  incident_confirmed_attack с корнем-нодовым актором внутри окна стартов подов 6.2.6.10 (item 3 вычел их из 6.2.4.6 — судятся здесь): ${_w626_init_attack_churn:-0}"
echo "  алертов класса побега/руткита от рантайм-comm внутри подачи: ${_w626_init_hits:-0}"
echo "  incident_confirmed_attack с корнем-нодовым актором внутри подачи: ${_w626_init_attack:-0} (${_w626_init_attack_roots:-нет})"
# ITEM 5 ВОЛНЫ 6.2.9.F.1: разбивка проверки plumbing-хопов по ИСХОДУ. Обход
# containerInitTrustedRoot переведён с имён на образы (readlink
# /proc/<pid>/exe против allowlist /opt/cni/bin/*, /var/lib/rancher/k3s/data/
# */bin/*), и без этой строки «ноль ложных инцидентов» неотличим от «проверка
# ни разу не вызывалась» — тот же класс, что счётчик попыток исключений
# (№292) и ленивый промоушен базы дрейфа. Читать так:
#   verified > 0            — ось работает, хопы подтверждены образом;
#   unresolved ≫ verified   — гонка readlink: плагины умирают быстрее, чем
#                             разрешается образ, и доверие держится на имени;
#   mismatch > 0            — образ разрешён и НЕ из allowlist: либо спуф
#                             имени, либо у этого стенда другой путь плагинов
#                             (разбирать поимённо, не расширять список молча);
#   серии нет               — правка item 5 не задеплоена.
if grep -q '^ebpf_guard_incident_plumbing_hop_total' "$W626_ART/metrics-window-end.txt" 2>/dev/null; then
    echo "  item 5 (№262), проверка plumbing-хопов по ОБРАЗУ — исходы на закрытии окна:"
    _w626_ph_verified=0; _w626_ph_mismatch=0; _w626_ph_unresolved=0; _w626_ph_no_pid=0; _w626_ph_not_listed=0
    for _w626_ph in verified mismatch unresolved no_pid not_listed; do
        _w626_ph_val=$(_w626_metric_sum ebpf_guard_incident_plumbing_hop_total "$_w626_ph" "$W626_ART/metrics-window-end.txt")
        _w626_ph_val=${_w626_ph_val:-0}
        echo "    $_w626_ph: $_w626_ph_val"
        case "$_w626_ph" in
            verified) _w626_ph_verified=$_w626_ph_val ;;
            mismatch) _w626_ph_mismatch=$_w626_ph_val ;;
            unresolved) _w626_ph_unresolved=$_w626_ph_val ;;
            no_pid) _w626_ph_no_pid=$_w626_ph_val ;;
            not_listed) _w626_ph_not_listed=$_w626_ph_val ;;
        esac
    done
    echo "    отрицательный контроль на спуф (exec -a flannel из /tmp) снят ОФЛАЙН юнит-тестом TestWave6_2_9_F1_CNIPlumbing_SpoofedImageStillPromotes: подделать дерево k3s-server→containerd на стенде нечем, а исход «образ разрешён и чужой» виден здесь строкой mismatch"
    # ITEM 6 ВОЛНЫ 6.2.9.F.2 (№311). «verified+mismatch+unresolved+no_pid = 0»
    # означает НЕ «обход по образу дал ноль лжи», а «обход НИ РАЗУ НЕ
    # ВЫЗВАН» — ни один хоп не дошёл до проверки образа (архив
    # collect-6.2.9.F.1-run2: not_listed=78, все прочие исходы нулевые).
    # Разбивка молчала об этом различии, и предыдущая запись волны
    # приписала правке item 5 вывод, которого прогон не доказывал.
    _w626_ph_called=$((_w626_ph_verified + _w626_ph_mismatch + _w626_ph_unresolved + _w626_ph_no_pid))
    if [ "$_w626_ph_called" -eq 0 ]; then
        echo "  ⚠ item 5 (№311): обход по образу НИ РАЗУ НЕ ВЫЗВАН (not_listed=${_w626_ph_not_listed}, все остальные исходы 0) — вывод о правке item 5 этим прогоном НЕ СНИМАЕТСЯ, ни в какую сторону"
    else
        echo "    обход по образу вызывался (verified+mismatch+unresolved+no_pid=${_w626_ph_called}) — разбивка выше отражает РЕАЛЬНУЮ проверку, а не молчание оси"
    fi
else
    echo "  item 5 (№262): серии ebpf_guard_incident_plumbing_hop_total НЕТ — проверка хопов по образу на стенде не задеплоена, вердикт ниже к ней отношения не имеет"
fi
# ОСТАТОК ITEM 5 — ОБРАЗЫ КОРНЯ И СУПЕРВИЗОРНЫХ ХОПОВ (разбор 14.09.2026).
#
# Правка item 5 закрывает ИМЕННУЮ половину провала 6.2.6.16 (обход упирался в
# CNI-плагин). Разбор архива показал, что ЭТОТ инцидент промотировала ВТОРАЯ,
# СЕТЕВАЯ половина: k8s_kubectl_apiserver_exec с comm=k3s-server — штатный
# разговор control-plane с apiserver при старте пода. Позволено ли такому
# трафику, ПОДТВЕРЖДЁННОМУ ОБРАЗОМ, не быть квалифицирующим сигналом — это
# решение владельца, а не правка: заводить его на ИМЕНАХ нельзя
# (`exec -a k3s-server`), а точных путей образов k3s-server/containerd на
# стенде В АРХИВЕ НЕТ — стор их не хранит, и офлайн они не выдумываются.
#
# Поэтому прогон обязан ПРИНЕСТИ эту величину. Она снимается прямо здесь и
# без гонки: в отличие от CNI-плагинов, живущих миллисекунды, k3s-server и
# containerd — долгоживущие демоны, и их /proc/<pid>/exe читается когда
# угодно. Без этой строки развилка вернётся из прогона такой же незакрытой,
# какой в него ушла, и решение владельца снова принималось бы по догадке.
echo "  остаток item 5 — ОБРАЗЫ корня и супервизорных хопов на ЭТОМ стенде (вход решения владельца по сетевой половине 6.2.6.16; величина, а не вердикт):"
for _w626_sup in k3s-server containerd containerd-shim-runc-v2 runc; do
    _w626_sup_pid=$(pgrep -x "$_w626_sup" 2>/dev/null | head -1)
    if [ -n "${_w626_sup_pid:-}" ]; then
        _w626_sup_exe=$(readlink "/proc/$_w626_sup_pid/exe" 2>/dev/null)
        echo "    $_w626_sup (pid $_w626_sup_pid): ${_w626_sup_exe:-ОБРАЗ НЕ РАЗРЕШИЛСЯ (нет прав или процесс умер между pgrep и readlink)}"
    else
        echo "    $_w626_sup: НЕ ЗАПУЩЕН на этом стенде — образа нет, и отсутствие пути здесь НЕ означает «путь неизвестен продукту»"
    fi
done
if [ "$W626_INSTRUMENTED" -ne 1 ]; then
    die "6.2.6.16 НЕИЗМЕРИМ: прогон неприборный (6.2.6.0 не взят) — под не стартовал, форму архива подать нечем"
elif [ "${_w626_init_hits:-0}" -lt 1 ]; then
    die "6.2.6.16 НЕИЗМЕРИМ: старт пода не дал НИ ОДНОГО алерта класса container_escape_*/rootkit_* от рантайм-comm — форма архива не воспроизведена, и «инцидента нет» ничего не доказывает (ноль приборный)"
elif [ "${_w626_init_attack:-0}" -gt 0 ] || [ "${_w626_init_attack_churn:-0}" -gt 0 ]; then
    die "6.2.6.16 ПРОВАЛЕН (№262): рутинная инициализация контейнера дала ${_w626_init_attack} incident_confirmed_attack с корнем нодового актора в окне подачи (${_w626_init_attack_roots}) и ${_w626_init_attack_churn:-0} в окне стартов подов 6.2.6.10 — шлюз промоушена по-прежнему судит по листу, а не по корню дерева${_w626_init_loss_suffix}"
elif [ "${_w626_esc_inc:-0}" -lt 1 ]; then
    die "6.2.6.16 НЕИЗМЕРИМ: инициализация контейнера в attack не промотирована, но и 6.2.4.7 не взят — по этому прогону нельзя отличить «шлюз судит по корню» от «детект вырезан целиком» (постановка требует читать обе половины вместе)"
else
    pass "6.2.6.16 ДОСТИГНУТО: ${_w626_init_hits} алертов класса побега от рантайм-comm при старте пода не дали ни одного incident_confirmed_attack с корнем нодового актора (ни в окне подачи, ни в окне стартов подов 6.2.6.10), и при этом настоящий побег (6.2.4.7) промотирован — шлюз судится по корню дерева, а не по листу${_w626_init_loss_suffix}"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.6.11 ПОЗИТИВНЫЙ ПОДКОНТРОЛЬ ЗАМОРОЗКИ (№237, открытый вопрос 11).
#
# ПОЧЕМУ САМЫМ ПОСЛЕДНИМ. Подконтроль ВРЕМЕННО понижает
# max_signatures_per_workload и перезапускает агент: это обнуляет счётчики
# метрик и базу дрейфа. Любой контроль, стоящий после него, мерил бы уже
# другой агент. Конфиг восстанавливается и агент перезапускается обратно
# ВСЕГДА — в том числе если подконтроль провалится (trap).
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.6.11 (вердикт): заморозка доказывается приращением счётчика ---"
_w626_cfg_bak="$W626_ART/config-test.yaml.orig"
_w626_restore_cfg() {
    if [ -f "$_w626_cfg_bak" ]; then
        cp "$_w626_cfg_bak" "$_w626_cfg" 2>/dev/null
        systemctl restart "$W626_SVC" 2>/dev/null
        echo "  конфиг стенда восстановлен из $_w626_cfg_bak, агент перезапущен"
    fi
    rm -rf /root/w626-sig 2>/dev/null
    rm -f /usr/local/bin/w626sig 2>/dev/null
}
trap '_w626_restore_cfg' EXIT

if ! grep -qE '^\s*max_signatures_per_workload:' "$_w626_cfg" 2>/dev/null; then
    die "6.2.6.11 НЕИЗМЕРИМ: в $_w626_cfg нет ключа max_signatures_per_workload — понизить его нечем, и дельта 0 останется неотличима от «счётчик сломан» (находка №237)"
else
    cp "$_w626_cfg" "$_w626_cfg_bak" 2>/dev/null
    sed -i 's/^\(\s*\)max_signatures_per_workload:.*/\1max_signatures_per_workload: 3/' "$_w626_cfg"
    echo "  max_signatures_per_workload временно понижен до 3 (было ${_w626_maxsig:-?}), рестарт агента"
    systemctl restart "$W626_SVC" 2>/dev/null
    sleep "$W626_SETTLE"
    # №267 (item 5): фильтр по comm="w626sig" — иначе рост bash/sshd от
    # прочих контролей внутри того же 20-секундного settle засчитывается в
    # приращение подконтроля, и «+2» верно совпадает со счётом случайно, а не
    # доказательно (архив 6.2.4: +2 = 1×bash + 1×w624sig). _w626_metric_sum
    # теперь матчит значение ЛЮБОГО лейбла в кавычках (см. правку выше).
    _w626_capA=$(_w626_metric_sum ebpf_guard_drift_baseline_signature_cap_reached_total "w626sig")
    # Нагрузка: один comm (=один WorkloadKey) открывает ДЕСЯТКИ РАЗНЫХ путей
    # под /root/ — каждый путь есть отдельная сигнатура drift_new_file_dir_sensitive
    # (normalizeDriftPath сохраняет путь целиком, схлопывая лишь числовые
    # сегменты). setsid — по той же причине, что у инъекции бикона.
    mkdir -p /root/w626-sig 2>/dev/null
    for _i in $(seq 1 40); do echo "s$_i" > "/root/w626-sig/f$_i" 2>/dev/null; done
    cp /bin/cat /usr/local/bin/w626sig 2>/dev/null
    _w626_sig_read=0
    for _i in $(seq 1 40); do
        _w626_sig_read=$(( _w626_sig_read + $(setsid /usr/local/bin/w626sig "/root/w626-sig/f$_i" 2>/dev/null | wc -c) ))
    done
    sleep "$W626_SETTLE"
    _w626_capB=$(_w626_metric_sum ebpf_guard_drift_baseline_signature_cap_reached_total "w626sig")
    _w626_capD=$(( _w626_capB - _w626_capA ))
    _w626_frozen_now=$(_w626_metric_sum ebpf_guard_drift_baseline_frozen_workloads "")
    echo "  сторож результата: прочитано байт нагрузкой = $_w626_sig_read (40 разных путей под /root/, один comm=w626sig)"
    echo "  приращение signature_cap_reached_total НА СВОЕЙ НАГРУЗКЕ (comm=w626sig, №267): $_w626_capD (было $_w626_capA, стало $_w626_capB); замороженных нагрузок сейчас: $_w626_frozen_now"
    if [ "${_w626_sig_read:-0}" -lt 1 ]; then
        die "6.2.6.11 НЕИЗМЕРИМ: нагрузка не прочитала ни байта — ноль приращения приборный, а не вердикт (память positive-control-needs-result-sentinel)"
    elif [ "$_w626_capD" -gt 0 ]; then
        pass "6.2.6.11 ДОСТИГНУТО: при max_signatures_per_workload=3 счётчик заморозки вырос на $_w626_capD — приращение ДОКАЗАНО, а не выведено из наличия имени метрики в выдаче (находка №237)"
    else
        die "6.2.6.11 ПРОВАЛЕН: нагрузка завела 40 различных сигнатур на ОДНУ нагрузку при потолке 3, а signature_cap_reached_total не вырос ни разу. Два возможных объяснения, и оба — находка: счётчик не движется, либо дерево нагрузки срезано в ядре исключением наблюдателя 5.9a (память observer-exclusion-blinds-controls) — тогда ноль приборный и контроль требует носителя вне дерева измерителя"
    fi
fi
_w626_restore_cfg
trap - EXIT

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.6.14 — РЕГРЕССИОННЫЙ ПУЧОК ВОЛН 6.2.1/6.2.2/6.2.3, СВОДНЫЙ ВЕРДИКТ.
#
# Постановка называет тринадцать меток и требует, чтобы КАЖДАЯ вынесла СВОЙ
# вердикт (6.2.3.5 в прогоне 6.2.4 своего вердикта не вынесла — была свёрнута
# в 6.2.3.6). Сама метка 6.2.6.14 при этом в прогоне 6.2.4-форка не
# печаталась вовсе, то есть страж полноты 6.2.6.18 обязан был бы объявить её
# отсутствующей. Здесь она сводит тринадцать в одну строку — не заменяя их
# собственные вердикты, а проверяя, что они есть.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.6.14: регрессионный пучок волн 6.2.1/6.2.2/6.2.3 (тринадцать меток) ---"
W626_REGRESSION_LABELS="6.2.1.2 6.2.1.2b 6.2.1.3 6.2.1.6 6.2.1.8 6.2.1.9 6.2.2.2 6.2.2.3 6.2.2.6 6.2.3.5 6.2.3.6 6.2.3.13 6.2.3.14"
_w626_reg_missing=""; _w626_reg_failed=""; _w626_reg_ok=0
for _w626_rl in $W626_REGRESSION_LABELS; do
    if ! grep -qE "^${_w626_rl//./\\.} " "$W626_EMITTED" 2>/dev/null; then
        _w626_reg_missing="$_w626_reg_missing $_w626_rl"
    elif grep -qE "^${_w626_rl//./\\.} FAIL$" "$W626_EMITTED" 2>/dev/null; then
        _w626_reg_failed="$_w626_reg_failed $_w626_rl"
    else
        _w626_reg_ok=$(( _w626_reg_ok + 1 ))
    fi
done
echo "  вынесли ДОСТИГНУТО: $_w626_reg_ok из 13; провалены:${_w626_reg_failed:- нет}; БЕЗ вердикта:${_w626_reg_missing:- нет}"
if [ -n "${_w626_reg_missing:-}" ]; then
    die "6.2.6.14 НЕИЗМЕРИМ: регрессионные метки${_w626_reg_missing} не вынесли СВОЕГО вердикта в этом прогоне — ровно то, что 6.2.3.5 сделала в прогоне 6.2.4 (свёрнута в 6.2.3.6). Пучок нельзя считать взятым по меткам, которых в логе нет"
elif [ -n "${_w626_reg_failed:-}" ]; then
    die "6.2.6.14 ПРОВАЛЕН: регрессия волн 6.2.1/6.2.2/6.2.3 не удержана —${_w626_reg_failed} (собственные вердикты этих меток см. выше)"
else
    pass "6.2.6.14 ДОСТИГНУТО: все тринадцать регрессионных меток вынесли свой вердикт и ни одна не провалена"
fi

# ─────────────────────────────────────────────────────────────────────────────
# 6.2.6.21 (№284, item 9) — КРИТЕРИЙ ВЫХОДА ИЗ КУСТА 6.2.x, ВЖАТ В ПАЙПЛАЙН.
#
# Постановка (plan.md, «Критерий выхода из куста 6.2.x»): куст закрывается
# ПОСЛЕ волны 6.2.6 в любом исходе. Исход А («ЗАКРЫТ») требует ТРЁХ условий
# ОДНОВРЕМЕННО, и первые два — НА ДВУХ ПРОГОНАХ ПОДРЯД:
#   1. 6.2.6.1 ≤ 100/ч по формуле (а), запас ≥ 1,5× (≤ 11 алертов/окно) —
#      на КАЖДОМ из двух прогонов;
#   2. 6.2.4.6 = 0 ложных incident_confirmed_attack — на ОБОИХ прогонах;
#   3. ни один вердикт прогона не опровергнут разбором архива (находок
#      класса «измеритель» — ноль).
#
# ОДИН прогон не может подтвердить исход А (условия 1/2 требуют ДВУХ). Этот
# критерий поэтому не решает за куст сам по себе — он печатает три условия
# ЧИСЛОМ для ЭТОГО прогона и решает немедленно только в ОДНУ сторону: если
# условие 1 или 2 уже провалено ЗДЕСЬ, второй прогон исход А не спасёт, и
# куст закрывается «С НЕВЗЯТЫМ ГЕЙТОМ» без ожидания повтора. Если оба условия
# взяты — решение печатается как ОТЛОЖЕННОЕ до второго прогона, а не как
# ЗАКРЫТ, ровно по букве постановки. Условие 3 пайплайн не автоматизирует —
# это вывод разбора архива людьми, не число, которое можно посчитать здесь.
# ─────────────────────────────────────────────────────────────────────────────
echo "--- 6.2.6.21: критерий выхода из куста 6.2.x (№284) ---"
# ЧТЕНИЕ РЕЕСТРА: метка взята, только если у неё ЕСТЬ строка OK и НЕТ строки
# FAIL. Одного grep OK мало по двум причинам: (1) подпунктные вердикты пишутся
# отдельным ключом «<метка>/подпункт» ровно для того, чтобы сюда не попадать,
# и без этой проверки любая будущая правка, вернувшая их под общий ключ, снова
# дала бы ложный PASS; (2) метка может вынести оба вердикта, если контроль
# исполнится дважды — тогда взятой она не является.
_w626_label_taken() { # $1=метка
    if command -v w626_label_taken >/dev/null 2>&1; then
        w626_label_taken "$1" "$W626_EMITTED"
        return $?
    fi
    grep -qE "^${1//./\\.} OK$" "$W626_EMITTED" 2>/dev/null || return 1
    grep -qE "^${1//./\\.} FAIL$" "$W626_EMITTED" 2>/dev/null && return 1
    return 0
}
_w626_c1_gate_ok=0
_w626_label_taken 6.2.6.1 && _w626_c1_gate_ok=1
# УСЛОВИЕ 1 ПЕРЕПИСАНО РЕШЕНИЕМ 11.09.2026 (item 6, исход А). Прежде оно
# звучало «гейт ≤ 100/ч формула (а) + запас 1,5×, на ДВУХ прогонах подряд».
# Находка №297 сняла ЕДИНИЦУ этой величины: домножение оконного счёта на
# 3600/окно предполагает поток, которого у ноды нет (2-3 непустых секунды из
# 600), и сравнение с порогом судило фазу таймеров, а не продукт. Требование
# двух прогонов подряд уходит вместе с порогом: подтверждать повтором имело
# смысл величину, стоящую у черты, а у измеренной без порога величины черты
# нет. Условие 1 становится требованием ИЗМЕРИМОСТИ в новой единице —
# «цена одного события ноды снята и разложена по корням деревьев».
#
# Что условие 1 НЕ делает: оно не смягчает выход из куста. Настоящим
# продуктовым условием был и остаётся пункт 2 (ноль ложных
# incident_confirmed_attack), и он на всех снятых прогонах провален —
# 50-motd-news→dpkg промотирован в подтверждённую атаку. Замена единицы
# величины не превращает исход Б в исход А.
_w626_c1_price_ok=0
[ "${_W626_TREE_SELF_OK:-0}" -eq 1 ] && [ "${_W626_EVENT_PRICE:-0}" -gt 0 ] && _w626_c1_price_ok=1
_w626_c1_f7_ok=0
_w626_label_taken 6.2.9.F.7 && _w626_c1_f7_ok=1
# ITEM 3 ВОЛНЫ 6.2.9.F.2 (№308) — ЧЕТВЁРТАЯ ПОЛОВИНА условия 1: вердикт
# 6.2.6.0 (приборность окна — ОБЕ половины, ось пода И потери). Второй прогон
# 14.09.2026 напечатал условие 1 ВЗЯТО на окне, которое СОСЕДНИЙ контроль
# того же прогона объявил НЕИЗМЕРИМЫМ (1 потеря за окно) — величина куста не
# имеет права называться измеренной на приборе, который сам себя объявил
# сломанным. Читается из того же реестра, что и три других половины: обе
# половины 6.2.6.0 пишут под один и тот же ключ, и FAIL любой из них уже
# исключает OK (см. _w626_label_taken).
_w626_c1_window_ok=0
_w626_label_taken 6.2.6.0 && _w626_c1_window_ok=1
# ITEM 2 ВОЛНЫ 6.2.9.F.2 (№305) — «победитель демон» останавливает условие 1
# так же, как непройденная половина 6.2.6.0: флаг снят выше, рядом с расчётом
# packs (_W626_EVENT_IS_DAEMON).
_w626_c1_demon_ok=1
[ "${_W626_EVENT_IS_DAEMON:-0}" -eq 1 ] && _w626_c1_demon_ok=0
_w626_c1_ok=0
[ "$_w626_c1_gate_ok" -eq 1 ] && [ "$_w626_c1_price_ok" -eq 1 ] && [ "$_w626_c1_f7_ok" -eq 1 ] \
    && [ "$_w626_c1_window_ok" -eq 1 ] && [ "$_w626_c1_demon_ok" -eq 1 ] && _w626_c1_ok=1
# Третья половина условия 1 печатается РЯДОМ с двумя метками (остаток №300,
# 14.09.2026): при тихом узле (цена 0, обе метки OK — форма прогона №299)
# прежняя строка объявляла условие НЕ_ВЗЯТЫМ, не называя ни одной проваленной
# величины, и читатель шёл искать причину выше по логу.
# СЛОВО УСЛОВИЯ (правка 14.09.2026, item 2): демон-победитель — не «условие
# НЕ ВЗЯТО» в общем смысле («данных не хватило»), а отдельно названная причина
# «единица не применима» — плановый текст item 2 требует именно слова
# НЕИЗМЕРИМО, а не молчаливого НЕ_ВЗЯТО среди прочих.
_w626_c1_word="ВЗЯТО"
if [ "$_w626_c1_demon_ok" -ne 1 ]; then
    _w626_c1_word="НЕИЗМЕРИМО (победитель — демон)"
elif [ "$_w626_c1_ok" -ne 1 ]; then
    _w626_c1_word="НЕ_ВЗЯТО"
fi
echo "  условие 1 (величина куста ИЗМЕРИМА в единице «алертов на одно событие ноды», решение 11.09.2026; порог этой величине НЕ назначен): ${_w626_c1_word} — цена события ${_W626_EVENT_PRICE:-?} алертов на «${_W626_EVENT_ROOT:-?}», цена СНЯТА=$([ "$_w626_c1_price_ok" -eq 1 ] && echo OK || echo FAIL), 6.2.6.1=$([ "$_w626_c1_gate_ok" -eq 1 ] && echo OK || echo FAIL), 6.2.9.F.7=$([ "$_w626_c1_f7_ok" -eq 1 ] && echo OK || echo FAIL), 6.2.6.0=$([ "$_w626_c1_window_ok" -eq 1 ] && echo OK || echo FAIL), победитель-демон=$([ "$_w626_c1_demon_ok" -eq 1 ] && echo НЕТ || echo ДА)"
echo "    справочно (единица снята, вердиктом не является): величина (а) ${_w626_vol:-?} алертов/окно = ${_w626_vol_hour:-?}/ч при прежнем пороге ${W626_GATE}/ч"

_w626_c2_ok=0
_w626_label_taken 6.2.4.6 && _w626_c2_ok=1
# ITEM 4 ВОЛНЫ 6.2.9.F.2 (№310) — условие 2 печатает, был ли ЦЕЛЕВОЙ класс
# лжи (дерево 50-motd-news) вообще ПРЕДЪЯВЛЕН прогону: ноль ложных
# incident_confirmed_attack на прогоне, где motd-дерево в окно не приходило,
# ничего не доказывает про ось юнита, ради которой условие 2 заведено. Факт
# предъявления берётся из 6.2.9.F.8 (ExecMainStartTimestamp форсированного
# юнита внутри окна) — той же переменной, которой судится сам факт события.
# ПРЕДЪЯВЛЕНИЕ КЛАССА (правка аудита 14.09.2026, №315): предикат и текст
# строки живут в библиотеке и имеют офлайн-сторож на ЧЕТЫРЁХ входах —
# инлайновая редакция не проверялась ничем, хотя порядок исполнения волны
# требует сторожа для item 4 поимённо. Заодно ужесточён сам предикат: старт
# юнита внутри окна БЕЗ единого алерта под его корнем — не предъявление, а
# второй вид того же нуля (инцидент из нуля алертов не складывается).
_w626_c2_class_ok=0
w626_c2_class_ok "${_w626_f8_ran:-0}" "${_w626_f8_alerts:-0}" && _w626_c2_class_ok=1
w626_c2_line "$_w626_c2_ok" "${_w626_f8_ran:-0}" "${_w626_f8_alerts:-0}" "${_W626_FORCE_SCHEDULED:-0}" \
    "${_W626_FORCE_TARGET:-?}" "${_w626_inc_node_out:-?}" "${_w626_inc_node_podstart:-0}"
echo

# ITEM 7 ВОЛНЫ 6.2.9.F.2 (№312) — условие 3 не предрешается константой «находок
# класса «измеритель» — ноль»: это заявление печаталось ДО разбора, который
# его же и опровергает. Пайплайн способен посчитать только то, что он сам
# видит, — список меток, провалившихся НА ЭТОМ прогоне (реестр $W626_EMITTED),
# и обязан напечатать его вместо готового вердикта.
_w626_c3_failed=$(grep -E ' FAIL$' "$W626_EMITTED" 2>/dev/null | awk '{print $1}' | sort -u)
_w626_c3_failed_n=$(printf '%s\n' "$_w626_c3_failed" | grep -c . || true)
# Текст обеих веток — в библиотеке, со сторожем на пустом и непустом реестре
# (№315): «пустой реестр» не имеет права прочитаться как «находок — ноль».
w626_c3_line "${_w626_c3_failed_n:-0}" "$(printf '%s' "$_w626_c3_failed" | paste -sd' ' -)"
echo

# №300 (14.09.2026): текст провала собирается из ФАКТИЧЕСКИ проваленных
# условий, с их числами. Прежняя редакция печатала «условие 1 и/или условие
# 2», хотя обе величины были на руках, — главный вердикт куста не называл
# того, что провалил, и читался только вместе со строками выше. Сборка живёт
# в библиотеке (w626_c21_why) и имеет офлайн-сторож на трёх синтетических
# входах. Побочно снята фраза «седьмой волны не будет»: запрет снят
# владельцем 14.09.2026, и вердикт, повторяющий отменённое решение, отравляет
# реестр так же, как подпунктные метки (память subclause-verdicts-poison-label-registry).
# СЛОВО ВЕРДИКТА (№314, аудит 14.09.2026): ветка провала печатала ОДИН текст
# на любом падении условия 1 — включая падения по ПРИБОРНЫМ половинам,
# добавленным items 2 и 3 этой же волны (6.2.6.0 и признак демона). Сломанный
# прибор закрывал бы куст словами «ЗАКРЫТ С НЕВЗЯТЫМ ПРОДУКТОВЫМ УСЛОВИЕМ» —
# ровно тот класс, против которого волна и заведена. Слово выбирает
# библиотека (w626_c21_kind), сторож — на пяти входах.
_w626_c21_kind=$(w626_c21_kind "$_w626_c1_ok" "$_w626_c2_ok" "$_w626_c1_gate_ok" \
    "$_w626_c1_price_ok" "$_w626_c1_f7_ok" "$_w626_c1_window_ok" "$_w626_c1_demon_ok")
_w626_c21_kind=${_w626_c21_kind:-ПРОВАЛЕН}
if [ "$_w626_c1_ok" -eq 0 ] || [ "$_w626_c2_ok" -eq 0 ]; then
    _w626_c21_why=$(w626_c21_why "$_w626_c1_ok" "$_w626_c2_ok" "${_W626_EVENT_PRICE:-?}" "${_W626_EVENT_ROOT:-?}" \
        "$_w626_c1_gate_ok" "$_w626_c1_f7_ok" "${_w626_inc_node_out:-?}" "${_w626_inc_tree_bg_count:-?}" "${_w626_inc_names:-нет}" \
        "$_w626_c1_price_ok" "$_w626_c1_window_ok" "$_w626_c1_demon_ok")
    if [ "$_w626_c21_kind" = "НЕИЗМЕРИМ" ]; then
        die "6.2.6.21 НЕИЗМЕРИМ: продуктовые половины (6.2.6.1 — объём, 6.2.4.6 — ложные инциденты) НЕ провалены; условие 1 уронили ПРИБОРНЫЕ половины. ${_w626_c21_why}. Куст этим прогоном НЕ закрывается «с невзятым продуктовым условием»: прогон о продукте не высказывается вовсе — величина не измерена, а не провалена (тот же разбор, что у гейта 11.09.2026). Требуется повтор прогона на исправном приборе"
    else
        die "6.2.6.21 ПРОВАЛЕН: РЕШЕНИЕ ПО КУСТУ 6.2.x — ЗАКРЫТ С НЕВЗЯТЫМ ПРОДУКТОВЫМ УСЛОВИЕМ. ${_w626_c21_why}. Порог 100/ч решением 11.09.2026 снят как ЕДИНИЦА, а не понижен и не повышен (находка №297: у величины нет потока, который эта единица предполагает; репер Falco №298 — 0 алертов против наших ${_W626_EVENT_PRICE:-?} на одном событии). Новой величине порог в этой волне НЕ назначается (правило 5.9.6). Остаток — долг следующей волны куста (запрет на седьмую волну снят владельцем 14.09.2026; прежний текст здесь повторял отменённое решение №284)"
    fi
else
    # Критерий выхода ВОЛНЫ 6.2.9.F.2 (пункт 5) требует условие 2 ВЗЯТО именно
    # при ПРЕДЪЯВЛЕННОМ классе лжи — регистровый OK этого не различает
    # (item 4, №310), поэтому главный вердикт печатает предостережение
    # отдельной строкой, не подменяя ИЗМЕРЕНО молчаливым провалом: 6.2.6.21 —
    # критерий про реестр 6.2.4.6, а не про предъявленность входа.
    pass "6.2.6.21 ИЗМЕРЕНО: условия 1 и 2 ВЗЯТЫ на ЭТОМ прогоне. Требование ДВУХ прогонов подряд снято вместе с порогом (решение 11.09.2026, исход А): подтверждать повтором имело смысл величину у черты, а у величины без порога черты нет. Решение по кусту остаётся отложенным только до разбора архива на условие 3 — список проваленных меток этого прогона напечатан строкой выше, окончательное слово за разбором. Цена одного события ноды ${_W626_EVENT_PRICE:-?} алертов на «${_W626_EVENT_ROOT:-?}»; тот же вопрос внешнему реперу (№298) даёт 0"
    if [ "${_w626_c2_class_ok:-0}" -ne 1 ]; then
        echo "  ⚠ волна 6.2.9.F.2, пункт 5 критерия выхода: условие 2 ВЗЯТО НА НЕПРЕДЪЯВЛЕННОМ ВХОДЕ — целевой класс лжи в это окно не приходил (№310), ИЗМЕРЕНО выше не закрывает пункт (5)"
    fi
fi

echo "--- уборка ---"
"$W626_KUBECTL" -n "$W626_NS" delete pod --all --ignore-not-found --wait=false >/dev/null 2>&1
rm -f /usr/local/bin/w626hostcat /usr/local/bin/w626sig /usr/local/bin/w626beacon 2>/dev/null
rm -rf /root/w626-sig /tmp/w626-bypass /tmp/w626-chmod 2>/dev/null
rm -f /etc/cron.d/w626-lineage 2>/dev/null   # подача половины (4) критерия 6.2.4.5
# Транзиентные юниты форсирования события ноды (6.2.9.F.8): с
# RemainAfterExit=yes они переживают собственный выход и блокируют СЛЕДУЮЩИЙ
# прогон по имени. Уборка здесь — вторая защита; первая стоит перед
# постановкой таймера, потому что стенд может остаться грязным и от прогона,
# прерванного до этой строки.
systemctl stop "w626-force-node-event.timer" >/dev/null 2>&1
systemctl stop "w626-force-node-event.service" >/dev/null 2>&1
systemctl reset-failed "w626-force-node-event.timer" >/dev/null 2>&1
systemctl reset-failed "w626-force-node-event.service" >/dev/null 2>&1

echo
echo "=== ИТОГ КОНТРОЛЕЙ ВОЛНЫ 6.2.6: проваленных $WAVE624_FAILS ==="
echo "артефакты: $W626_ART"
[ "$WAVE624_FAILS" -gt 0 ] && echo "вердикты: $W626_VERDICTS"
exit 0
